TURATH_CHUNK(71,[{"num":14200,"demo":false,"sanad":"","matn":["عَنْ كَلَدَةَ بْنِ حَنْبَلٍ، أَنَّ صَفْوَانَ بْنَ أُمَيَّةَ، بَعَثَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِلَبَنٍ وَجِدَايَةٍ وَضَغَابِيسَ، - وَالنَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِأَعْلَى مَكَّةَ، - فَدَخَلْتُ، وَلَمْ أُسَلِّمْ فَقَالَ: ارْجِعْ فَقُلِ: السَّلاَمُ عَلَيْكُمْ. وَذَاكَ بَعْدَ مَا أَسْلَمَ صَفْوَانُ بْنُ أُمَيَّةَ."],"takhrij":"حسن: رواه أبو داود (5176)، والترمذي (2710)، والنسائي في الكبرى (6702)، وأحمد (15425) كلهم من طرق عن ابن جريج، أخبرني عمرو بن أبي سفيان، أن عمرو بن عبد الله بن صفوان أخبره أن كلدة بن حنبل أخبره فذكره.","grade":"حسن","chapter_ar":"باب التسليم قبل الاستئذان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5176), al-Tirmidhī (2710), al-Nasā’ī in al-Sunan al-Kubrā (6702), and Aḥmad (15425).","chapter_en":"Giving Salām Before Seeking Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["Kaldah ibn Ḥanbal narrated: Ṣafwān ibn Umayyah sent me to the Messenger of Allah ﷺ carrying milk, a young gazelle, and ḍaghābīs, while the Prophet ﷺ was in the upper part of Makkah. I entered without giving salām. He said: “Go back and say: ‘Peace be upon you.’” This occurred after Ṣafwān ibn Umayyah had embraced Islam."]},"buhuth":{"en":["It was said that ḍaghābīs is an edible plant.","In al-Nihāyah, it is explained as small cucumbers, the singular being ḍaghbūs."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7397],"tks":"حسن: رواه أبو داود (5176)، والترمذي (2710)، والنسائي في الكبرى (6702)، وأحمد (15425)."},{"num":14201,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ بَنِي عَامِرٍ، أَنَّهُ اسْتَأْذَنَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَأَلِجُ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِخَادِمِهِ: اخْرُجِي إِلَيْهِ، فَإِنَّهُ لَا يُحْسِنُ الِاسْتِئْذَانَ، فَقُولِي لَهُ: فَلْيَقُلِ: السَّلَامُ عَلَيْكُمْ آَدْخُلُ؟، قَالَ: فَسَمِعْتُهُ يَقُولُ ذَلِكَ، فَقُلْتُ: السَّلَامُ عَلَيْكُمْ، آَدْخُلُ؟ قَالَ: فَأَذِنَ، أَوْ قَالَ: فَدَخَلْتُ."],"takhrij":"صحيح: رواه أحمد (23127) –واللفظ له-، وأبو داود (5179)، والنسائي في عمل اليوم والليلة (316) كلهم من طريق شعبة، عن منصور، عن ربعي بن حراش، عن رجل من بني عامر فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب التسليم قبل الاستئذان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23127), and this is his wording, Abū Dāwūd (5179), and al-Nasā’ī in ʿAmal al-Yawm wa-al-Laylah (316).","chapter_en":"Giving Salām Before Seeking Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["A man from Banū ʿĀmir narrated: He sought permission to enter upon the Prophet ﷺ and said: “May I enter?” The Prophet ﷺ said to his servant: “Go out to him, for he does not know how to seek permission properly. Tell him to say: ‘Peace be upon you. May I enter?’” The man said: I heard him say that, so I said: “Peace be upon you. May I enter?” Then permission was granted to me—or he said: I entered."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (23127) - واللفظ له -، وأبو داود (5179)، والنسائي في عمل اليوم والليلة (316)."},{"num":14202,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ، أَنَّهُ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي مَشْرُبَةٍ لَهُ فَقَالَ: السَّلاَمُ عَلَيْكَ يَا رَسُولَ اللَّهِ، السَّلاَمُ عَلَيْكُمْ أَيَدْخُلُ عُمَرُ."],"takhrij":"صحيح: رواه أبو داود (5201)، والنسائي في الكبرى (10080) كلاهما من طريق أسود بن عامر، حدثنا حسن بن صالح، عن أبيه، عن سلمة بن كهيل، عن سعيد بن جبير، عن ابن عباس، عن عمر فذكره.","grade":"صحيح","chapter_ar":"باب التسليم قبل الاستئذان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5201) and al-Nasā’ī in al-Sunan al-Kubrā (10080).","chapter_en":"Giving Salām Before Seeking Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":7,"content":{"translation":{"en":["ʿUmar ibn al-Khaṭṭāb came to the Prophet ﷺ while he was in an upper room and said: “Peace be upon you, O Messenger of Allah. Peace be upon you. May ʿUmar enter?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5201)، والنسائي في الكبرى (10080)."},{"num":14203,"demo":false,"sanad":"","matn":["عن ابْنِ مَسْعُودٍ، يَقُولُ:  قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذْنُكَ عَلَيَّ أَنْ يُرْفَعَ الْحِجَابُ، وَأَنْ تَسْتَمِعَ سِوَادِي، حَتَّى أَنْهَاكَ."],"takhrij":"صحيح: رواه مسلم في السلام (2169) من طرق عن إبراهيم بن سويد، قال: سمعت عبد الرحمن بن يزيد، قال: سمعت ابن مسعود، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب رفع الحجاب وفتح الباب من علامات الإذن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2169).","chapter_en":"Raising the Curtain and Opening the Door Are Signs of Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":8,"content":{"translation":{"en":["Ibn Masʿūd narrated: The Messenger of Allah ﷺ said to me: “Your permission to enter upon me is that the curtain be raised and that you hear my private conversation, until I tell you otherwise.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2169)."},{"num":14204,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَ لَبَنًا فِي قَدَحٍ، فَقَالَ: أَبَا هِرٍّ، الْحَقْ أَهْلَ الصُّفَّةِ فَادْعُهُمْ إِلَىَّ. قَالَ: فَأَتَيْتُهُمْ فَدَعَوْتُهُمْ، فَأَقْبَلُوا فَاسْتَأْذَنُوا، فَأُذِنَ لَهُمْ، فَدَخَلُوا."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6246) من طرق عن عمر بن ذر، أخبرنا مجاهد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إذا دُعي الرجل فلا يدخل حتى يستأذن","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6246).","chapter_en":"Even If a Man Is Invited, He Should Not Enter Until He Seeks Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated: I entered with the Messenger of Allah ﷺ, and he found some milk in a bowl. He said: “O Abū Hirr, go to the people of al-Ṣuffah and invite them to come to me.” I went to them and invited them. They came, sought permission to enter, and when permission was granted they entered."]}},"tuhfa":{},"full":1,"rep":[9685],"tks":"صحيح: رواه البخاري (6246)."},{"num":14205,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: رَسُولُ الرَّجُلِ إِلَى الرَّجُلِ إِذْنُهُ."],"takhrij":"صحيح: رواه أبو داود (5189)، والبخاري في الأدب المفرد (1076) كلاهما عن موسى بن إسماعيل، حدثنا حماد بن سلمة، عن حبيب وهشام، عن محمد، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب رسول الرجل إلى الرجل إذنه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5189) and al-Bukhārī in al-Adab al-Mufrad (1076).","chapter_en":"A Man’s Messenger to Another Man Constitutes Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “A man’s messenger to another man constitutes his permission.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6528],"tks":"صحيح: رواه أبو داود (5189)، والبخاري في الأدب المفرد (1076)."},{"num":14206,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا دُعِيَ أَحَدُكُمْ إِلَى طَعَامٍ، فَجَاءَ مَعَ الرَّسُولِ، فَإِنَّ ذَلِكَ لَهُ إِذْنٌ."],"takhrij":"صحيح: روأه أبو داود (5190)، والبخاري في الأدب المفرد (1075)، والإمام أحمد (10894) كلهم من حديث عبد الأعلى، حدثنا سعيد، عن قتادة، عن أبي رافع، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب رسول الرجل إلى الرجل إذنه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5190), al-Bukhārī in al-Adab al-Mufrad (1075), and Imām Aḥmad (10894).","chapter_en":"A Man’s Messenger to Another Man Constitutes Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If one of you is invited to a meal and comes along with the messenger who invited him, then that itself constitutes permission for him to enter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5190)، والبخاري في الأدب المفرد (1075)، والإمام أحمد (10894)."},{"num":14207,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَى بَابَ قَوْمٍ لَمْ يَسْتَقْبِلِ الْبَابَ مِنْ تِلْقَاءِ وَجْهِهِ، وَلَكِنْ مِنْ رُكْنِهِ الأَيْمَنِ، أَوِ الأَيْسَرِ، وَيَقُولُ: السَّلاَمُ عَلَيْكُمُ، السَّلاَمُ عَلَيْكُمْ. وَذَلِكَ أَنَّ الدُّورَ لَمْ يَكُنْ عَلَيْهَا يَوْمَئِذٍ سُتُورٌ."],"takhrij":"حسن: رواه أبو داود (5186)، وأحمد (17694)، والبخاري في الأدب المفرد (1078) كلهم من طريق بقية بن الوليد، حدثنا محمد بن عبد الرحمن، عن عبد الله بن بسر قال: فذكره.","grade":"حسن","chapter_ar":"باب أن المستأذن لا يستقبل الباب من تلقاء وجهه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5186), Aḥmad (17694), and al-Bukhārī in al-Adab al-Mufrad (1078).","chapter_en":"One Seeking Permission Should Not Stand Directly Facing the Door","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated: When the Messenger of Allah ﷺ came to the door of a people, he would not stand directly facing the doorway. Rather, he would stand to its right side or left side and say: “Peace be upon you. Peace be upon you.” That was because houses at that time did not have curtains covering their entrances."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12864],"tks":"حسن: رواه أبو داود (5186)، وأحمد (17694)، والبخاري في الأدب المفرد (1078)."},{"num":14208,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ يَقُولُ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَيْنٍ كَانَ عَلَى أَبِي، فَدَقَقْتُ الْبَابَ، فَقَالَ: مَنْ ذَا فَقُلْتُ: أَنَا، فَقَالَ: أَنَا أَنَا كَأَنَّهُ كَرِهَهَا."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6250)، ومسلم في الآداب (2155) كلاهما من طرق عن شعبة، عن محمد بن المنكدر قال: سمعت جابرا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهة قول المستأذن: أنا، إذا قيل: من أنت؟","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6250) and Muslim (2155).","chapter_en":"The Dislike of Saying “It Is Me” When the Person Seeking Permission Is Asked, “Who Are You?”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I came to the Prophet ﷺ concerning a debt that was owed by my father and knocked on the door. He asked: “Who is it?” I replied: “It is me.” He said: “Me, me?” as though he disliked that answer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[12863],"tks":"متفق عليه: رواه البخاري (6250)، ومسلم (2155)."},{"num":14209,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا زَارَ أَحَدُكُمْ أَخَاهُ، فَجَلَسَ عِنْدَهُ، فَلاَ يَقُومَنَّ حَتَّى يَسْتَأْذِنَهُ."],"takhrij":"حسن: رواه أبو الشيخ في طبقات المحدثين بأصبهان (2/205) عن إسحاق بن محمد بن حكيم قال: حدثنا يحيى بن واقد، حدثنا ابنُ أبي غنية، حدثنا أبي، حدثنا جبلة بن سحيم، عن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب الاستئذان للانصراف","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū al-Shaykh in Ṭabaqāt al-Muḥaddithīn bi-Aṣbahān (2/205).","chapter_en":"Seeking Permission Before Leaving","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Prophet ﷺ said: “When one of you visits his brother and sits with him, he should not get up to leave until he seeks his permission.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو الشيخ في طبقات المحدثين بأصبهان (2/205)."},{"num":14210,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَلَقَ اللَّهُ آدَمَ عَلَى صُورَتِهِ، طُولُهُ سِتُّونَ ذِرَاعًا، فَلَمَّا خَلَقَهُ قَالَ: اذْهَبْ فَسَلِّمْ عَلَى أُولَئِكَ النَّفَرِ مِنَ الْمَلاَئِكَةِ جُلُوسٌ، فَاسْتَمِعْ مَا يُحَيُّونَكَ، فَإِنَّهَا تَحِيَّتُكَ وَتَحِيَّةُ ذُرِّيَّتِكَ. فَقَالَ: السَّلاَمُ عَلَيْكُمْ. فَقَالُوا: السَّلاَمُ عَلَيْكَ وَرَحْمَةُ اللَّهِ. فَزَادُوهُ: وَرَحْمَةُ اللَّهِ، فَكُلُّ مَنْ يَدْخُلُ الْجَنَّةَ عَلَى صُورَةِ آدَمَ، فَلَمْ يَزَلِ الْخَلْقُ يَنْقُصُ بَعْدُ حَتَّى الْآنَ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6227)، ومسلم في الجنة وصفة نعيمها (2841) كلاهما من طريق عبد الرزاق، عن معمر، عن همام، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب بدء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6227) and Muslim (2841).","chapter_en":"The Beginning of the Greeting of Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":14,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Allah created Ādam upon his form, and his height was sixty cubits. When He created him, He said: ‘Go and greet that group of angels who are sitting there, and listen to how they greet you, for that will be your greeting and the greeting of your descendants.’ So Ādam said: ‘Peace be upon you.’ They replied: ‘Peace be upon you and the mercy of Allah,’ adding, ‘and the mercy of Allah.’ Everyone who enters Paradise will be in the form of Ādam, and mankind has continued to decrease in stature since then until now.”"]}},"tuhfa":{},"full":1,"rep":[508,8322],"tks":"متفق عليه: رواه البخاري (6227)، ومسلم (2841)."},{"num":14211,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: كُنَّا إِذَا صَلَّيْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْنَا: السَّلاَمُ عَلَى اللَّهِ قَبْلَ عِبَادِهِ، السَّلاَمُ عَلَى جِبْرِيلَ، السَّلاَمُ عَلَى مِيكَائِيلَ، السَّلاَمُ عَلَى فُلاَنٍ، فَلَمَّا انْصَرَفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَقْبَلَ عَلَيْنَا بِوَجْهِهِ، فَقَالَ: إِنَّ اللَّهَ هُوَ السَّلاَمُ، فَإِذَا جَلَسَ أَحَدُكُمْ فِي الصَّلاَةِ فَلْيَقُلِ: التَّحِيَّاتُ لِلَّهِ، وَالصَّلَوَاتُ، وَالطَّيِّبَاتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. فَإِنَّهُ إِذَا قَالَ ذَلِكَ أَصَابَ كُلَّ عَبْدٍ صَالِحٍ فِي السَّمَاءِ وَالأَرْضِ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. ثُمَّ يَتَخَيَّرْ بَعْدُ مِنَ الْكَلاَمِ مَا شَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6230)، ومسلم في الصلاة (402) كلاهما من طرق عن أبي وائل شقيق، عن عبد الله فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب السلام اسم من أسماء الله تعالى","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6230) and Muslim (402).","chapter_en":"Al-Salām Is One of the Names of Allah, the Exalted","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: When we prayed with the Prophet ﷺ, we used to say: “Peace be upon Allah before His servants. Peace be upon Jibrīl. Peace be upon Mīkāʾīl. Peace be upon so-and-so and so-and-so.” When the Prophet ﷺ finished the prayer, he turned his face toward us and said: “Indeed, Allah is al-Salām. When one of you sits in prayer, let him say: ‘All greetings belong to Allah, as do all prayers and all pure words. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah.’ For when he says that, it reaches every righteous servant in the heavens and the earth. Then he should say: ‘I testify that there is no deity except Allah, and I testify that Muḥammad is His servant and Messenger.’ After that, he may choose whatever supplication he wishes.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6230)، ومسلم (402)."},{"num":14212,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ السَّلامَ اسْمٌ مِنْ أَسْمَاءِ اللهِ تَعَالَى، وَضَعَهُ اللَّهُ فِي الأَرْضِ، فَأَفْشُوا السَّلامَ بَيْنَكُمْ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (989) عن شهاب، حدثنا حماد بن سلمة، عن حميد، عن أنس قال: فذكره.","grade":"حسن","chapter_ar":"باب السلام اسم من أسماء الله تعالى","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (989).","chapter_en":"Al-Salām Is One of the Names of Allah, the Exalted","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “Indeed, al-Salām is one of the Names of Allah, the Exalted, which Allah has placed upon the earth, so spread salām among yourselves.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (989)."},{"num":14213,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الله بن مسعود، قَالَ: قَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ السَّلامَ اسْمٌ مِنْ أَسْمَاءِ الله وَضَعَهُ فِي الأَرْضِ، فَأَفْشُوهُ فِيكُمْ، فَإِنَّ الرَّجُلَ إِذَا سَلَّمَ عَلَى الْقَوْمِ فَرَدُّوا عَلَيْهِ، كَانَ لَهُ عَلَيْهِمْ فَضْلُ دَرَجَةٍ، لأَنَّهُ ذَكَّرَهُمْ، فَإِنْ لَمْ يَرُدُّوا عَلَيْهِ رَدَّ عَلَيْهِ مَنْ هُوَ خَيْرٌ مِنْهُمْ وَأَطْيَبُ."],"takhrij":"حسن: رواه البزار (1770)، والطبراني في الكبير (10391)، وابن حبان في روضة العقلاء (ص 74) كلهم من طريق محمد بن جعفر المدائني، حدثنا ورقاء، عن الأعمش، عن زيد بن وهب، عن عبد الله بن مسعود قال: فذكره.","grade":"حسن","chapter_ar":"باب السلام اسم من أسماء الله تعالى","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (1771), al-Ṭabarānī in al-Muʿjam al-Kabīr (10/224), and Ibn Ḥibbān in Rawḍat al-ʿUqalāʾ (p. 74).","chapter_en":"Al-Salām Is One of the Names of Allah, the Exalted","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":15,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Indeed, al-Salām is one of the Names of Allah which He has placed upon the earth, so spread it among yourselves. When a man gives salām to a group and they return it, he has a degree of superiority over them because he was the one who reminded them of it. If they do not return his salām, then those who are better and purer than them will return it to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (1770)، والطبراني في الكبير (10391)، وابن حبان في روضة العقلاء (ص 74)."},{"num":14214,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: أَمَرَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَبْعٍ: بِعِيَادَةِ الْمَرِيضِ، وَاتِّبَاعِ الْجَنَائِزِ، وَتَشْمِيتِ الْعَاطِسِ، وَنَصْرِ الضَّعِيفِ، وَعَوْنِ الْمَظْلُومِ، وَإِفْشَاءِ السَّلاَمِ، وَإِبْرَارِ الْمُقْسِمِ، وَنَهَى."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6235)، ومسلم في اللباس والزينة (2066) كلاهما من طريق أشعث بن أبي الشعثاء، عن معاوية بن سويد بن مقرن، عن البراء بن عازب فذكره.","grade":"متفق عليه","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6235) and Muslim (2066).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: The Messenger of Allah ﷺ commanded us with seven things: Visiting the sick, following funeral processions, saying “yarḥamuk Allah” to one who sneezes, supporting the weak, helping the oppressed, spreading salām, and fulfilling the oath of one who adjures another… to the end of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6235)، ومسلم (2066)."},{"num":14215,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا، وَلَا تُؤْمِنُوا حَتَّى تَحَابُّوا، أَوَلَا أَدُلُّكُمْ عَلَى شَيْءٍ إِذَا فَعَلْتُمُوهُ تَحَابَبْتُمْ؟ أَفْشُوا السَّلَامَ بَيْنَكُمْ وَفِي لفظ: وَالَّذِي نَفْسِي بِيَدِهِ لَا تَدْخُلُونَ الْجَنَّةَ حَتَّى تُؤْمِنُوا."],"takhrij":"صحيح: رواه مسلم في الإيمان (54) من طريق الأعمش، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (54).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “You will not enter Paradise until you believe, and you will not truly believe until you love one another. Shall I not direct you to something which, if you do it, will cause you to love one another? Spread salām among yourselves.” In another wording: “By the One in whose hand is my soul, you will not enter Paradise until you believe.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (54)."},{"num":14216,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي إِذَا رَأَيْتُكَ طَابَتْ نَفْسِي وَقَرَّتْ عَيْنِي، فَأَنْبِئْنِي عَنْ كُلِّ شَيْءٍ. فَقَالَ: كُلُّ شَيْءٍ خُلِقَ مِنْ مَاءٍ قَالَ: قُلْتُ: أَنْبِئْنِي عَنْ أَمْرٍ إِذَا أَخَذْتُ بِهِ دَخَلْتُ الْجَنَّةَ. قَالَ: أَفْشِ السَّلَامَ، وَأَطْعِمِ الطَّعَامَ، وَصِلِ الْأَرْحَامَ، وَقُمْ بِاللَّيْلِ وَالنَّاسُ نِيَامٌ، ثُمَّ ادْخُلِ الْجَنَّةَ بِسَلَامٍ."],"takhrij":"صحيح: رواه أحمد (7932)، وصحّحه ابن حبان (508، 2559)، والحاكم (7278) كلهم من طريق همام، عن قتادة، عن أبي ميمونة، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (7932), authenticated by Ibn Ḥibbān (508, 2559), and al-Ḥākim (7174).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated: I said: “O Messenger of Allah, whenever I see you, my soul feels good and my eyes are comforted. So tell me about everything.” He said: “Everything was created from water.” I then said: “Tell me of an action which, if I hold firmly to it, will cause me to enter Paradise.” He replied: “Spread salām, feed people, maintain kinship ties, and stand in prayer at night while people are asleep; then enter Paradise in peace.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[63,2680,8194,12750,13660,13725],"tks":"صحيح: رواه أحمد (7932)، وصححه ابن حبان (508، 2559)، والحاكم (7174)."},{"num":14217,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، قَالَ: أَمَرَنَا نَبِيُّنَا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ نُفْشِيَ السَّلاَمَ."],"takhrij":"حسن: رواه ابن ماجه (3693) عن أبي بكر بن أبي شيبة –وهو في مصنفه (26251)- عن إسماعيل بن عياش، عن محمد بن زياد، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3693), Abū Bakr ibn Abī Shaybah (26251), and al-Ṭabarānī in al-Muʿjam al-Kabīr (8/130–131).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Abū Umāmah narrated: “The Prophet ﷺ commanded us to spread salām.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3693)، وأبو بكر بن أبي شيبة (26251)، والطبراني في الكبير (8/130-131)."},{"num":14218,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ بْنِ عَازِبٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْشُوا السَّلَامَ تَسْلَمُوا، وَالْأَشَرَةُ شَرُّ."],"takhrij":"حسن: رواه أحمد (18530)، والبخاري في الأدب المفرد (787، 1266)، وصحّحه ابن حبان (491) كلهم من حديث أبي معاوية، حدثنا قنان بن عبدالله النهمي، عن عبد الرحمن بن عوسجة، عن البراء بن عازب فذكره.","grade":"حسن","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (18530), al-Bukhārī in al-Adab al-Mufrad (787, 1266), and authenticated by Ibn Ḥibbān (491).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated that the Messenger of Allah ﷺ said: “Spread salām and you will be safe, and arrogance and insolence are evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18530)، والبخاري في الأدب المفرد (787، 1266)، وصححه ابن حبان (491)."},{"num":14219,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ سَلاَمٍ، قَالَ: لَمَّا قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ انْجَفَلَ النَّاسُ إِلَيْهِ، وَقِيلَ: قَدِمَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجِئْتُ فِي النَّاسِ لأَنْظُرَ إِلَيْهِ، فَلَمَّا اسْتَبَنْتُ وَجْهَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرَفْتُ أَنَّ وَجْهَهُ لَيْسَ بِوَجْهِ كَذَّابٍ، وَكَانَ أَوَّلَ شَيْءٍ تَكَلَّمَ بِهِ أَنْ قَالَ: أَيُّهَا النَّاسُ، أَفْشُوا السَّلاَمَ، وَأَطْعِمُوا الطَّعَامَ، وَصَلُّوا وَالنَّاسُ نِيَامٌ تَدْخُلُونَ الْجَنَّةَ بِسَلاَمٍ."],"takhrij":"صحيح: رواه الترمذي (2485)، وابن ماجه (1334)، وأحمد (23784)، والحاكم (7277) كلهم من طريق يحيى بن سعيد، عن عوف بن أبي جميلة الأعرابي، عن زرارة بن أوفى، عن عبد الله بن سلام فذكره. واللفظ للترمذي.","grade":"صحيح","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2485), Ibn Mājah (1334), Aḥmad (23784), and al-Ḥākim (7277).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn Salām narrated: When the Messenger of Allah ﷺ arrived in Madinah, the people rushed toward him, and it was announced: “The Messenger of Allah ﷺ has arrived!” I came among the people to look at him. When I clearly saw the face of the Messenger of Allah ﷺ, I knew that his face was not the face of a liar. The first words I heard him say were: “O people, spread salām, feed people, and pray at night while people are asleep; you will enter Paradise in peace.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[65],"tks":"صحيح: رواه الترمذي (2485)، وابن ماجه (1334)، وأحمد (23784)، والحاكم (7277)."},{"num":14220,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ أن رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَفْشُوا السَّلاَمَ، وَأَطْعِمُوا الطَّعَامَ، وَكُونُوا إِخْوَانًا كَمَا أَمَرَكُمُ اللَّهُ عَزَّ وَجَلَّ."],"takhrij":"حسن: رواه ابن ماجه (3252)، وأحمد (6450) كلاهما من طريق ابن جريج قال: قال لي سليمان بن موسى، حدثنا نافع أن ابن عمر قال: فذكره.","grade":"حسن","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3252) and Aḥmad (6450).","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “Spread salām, feed people, and be brothers as Allah, Mighty and Majestic, has commanded you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3252)، وأحمد (6450)."},{"num":14221,"demo":false,"sanad":"","matn":["عن هانئ بن يزيد قال: سألتُ النبي صلى الله عليه وسلم، أخبِرْني بأيِّ شيءٍ يُوجبُ لي الجنّةَ؟ فقال: طيبُ الكلامِ، وبذلُ السّلامِ، وإطعامُ الطعامِ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (811)، وابن حبان (504) –واللفظ له- كلاهما عن يزيد بن المقدام بن شريح بن هاني، عن أبيه المقدام، عن شريح بن هانئ قال: حدثني هانئ بن يزيد فذكره.","grade":"حسن","chapter_ar":"باب الأمر بإفشاء السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"“Good speech, freely offering salām, and feeding people.”\nHasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (811) and Ibn Ḥibbān (504), and this is his wording.","chapter_en":"The Command to Spread Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":16,"content":{"translation":{"en":["Hāniʾ ibn Yazīd narrated: I asked the Prophet ﷺ: “Tell me what will make Paradise obligatory for me?” He replied:"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (811)، وابن حبان (504) - واللفظ له."},{"num":14222,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَوْلَى النَّاسِ بِاللَّهِ مَنْ بَدَأَهُمْ بِالسَّلاَمِ."],"takhrij":"صحيح: رواه أبو داود (5197) عن محمد بن يحيى بن فارس الذهلي، حدثنا أبو عاصم (وهو الضحّاك بن مخلد)، عن أبي خالد وهب (وهو ابن خالد الحميري)، عن أبي سفيان الحمصي (هو محمد بن زياد الألهاني)، عن أبي أمامة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب فضل المبتدئ بالسلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5197).","chapter_en":"The Virtue of Being the First to Give Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["Abū Umāmah narrated that the Messenger of Allah ﷺ said: “The people most deserving of closeness to Allah are those who begin by giving salām.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5197)."},{"num":14223,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: الْبَادِئُ بِالسَّلاَمِ بَرِيءٌ مِنَ الصَّرْمِ."],"takhrij":"حسن: رواه أبو نعيم في حلية الأولياء (9/25) عن حبيب بن الحسن، حدثنا يوسف القاضي، حدثنا ابنُ أبي بكر، حدثنا ابن مهدي، حدثنا سفيان (هو الثوري)، عن أبي قيس (مولى عمرو بن العاص واسمه عبد الرحمن بن ثابت)، عن عمرو بن ميمون، عن عبد الله بن مسعود فذكره.","grade":"حسن","chapter_ar":"باب فضل المبتدئ بالسلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Nuʿaym in Ḥilyat al-Awliyāʾ (9/25).","chapter_en":"The Virtue of Being the First to Give Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":17,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “The one who begins with salām is free of the sin of severing ties and estrangement.”"]},"buhuth":{"en":["In another narration:","“He is free of arrogance.”","The word “al-ṣarm” means severance and abandonment."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو نعيم في حلية الأولياء (9/25)."},{"num":14224,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا تُسَلِّمُوا تَسْلِيمَ الْيَهُودِ وَالنَّصَارَى، فَإِنَّ تَسْلِيمَهُمْ بِالْأَكُفِّ وَالرُّؤوسِ وَالْإِشَارَةِ."],"takhrij":"حسن: رواه النسائي في السنن الكبرى (10100) عن إبراهيم بن المستمر، حدثني الصلت بن محمد، حدثنا إبراهيم بن حميد الرؤاسي، عن ثور بن يزيد، قال: حدّث أبوالزبير، عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن السلام بالأكف والإشارة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (10100).","chapter_en":"The Prohibition of Greeting Solely with the Hands, Head, or Gestures","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":18,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “Do not greet with the greeting of the Jews and Christians, for their greeting is by means of the hands, the head, and gestures.”"]},"buhuth":{"en":["The prohibition of greeting by gesture applies to a person who is able to pronounce an audible salām.","As for someone who is far away and cannot hear the greeting, it is permissible to gesture with the hand while also verbally pronouncing the salām."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في السنن الكبرى (10100)."},{"num":14225,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، أَنَّ رَجُلاً، سَأَلَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَىُّ الإِسْلاَمِ خَيْرٌ؟ قَالَ: تُطْعِمُ الطَّعَامَ، وَتَقْرَأُ السَّلاَمَ عَلَى مَنْ عَرَفْتَ، وَعَلَى مَنْ لَمْ تَعْرِفْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6236)، ومسلم في الإيمان (39) كلاهما من طرق عن الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عبد الله بن عمرو فذكره.","grade":"متفق عليه","chapter_ar":"باب يسلم المرء على من يعرفه وعلى من لا يعرفه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6236) and Muslim (39).","chapter_en":"A Person Should Give Salām to Those He Knows and Those He Does Not Know","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":19,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: A man asked the Messenger of Allah ﷺ: “Which aspect of Islam is best?” He replied: “That you feed people and give salām to those whom you know and those whom you do not know.”"]},"buhuth":{"ar":["بداية السلام سنة، والجواب عنه واجب."],"en":["Initiating the salām is a Sunnah, while replying to it is obligatory."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6236)، ومسلم (39)."},{"num":14226,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ، يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُسَلِّمُ الرَّاكِبُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْقَاعِدِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6232-6233)، ومسلم في السلام (2160) كلاهما من طرق عن ابن جريج، قال: أخبرني زياد، أنه سمع ثابتا، مولى عبد الرحمن بن زيد: أنه سمع أبا هريرة، يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب يسلم الراكب على الماشي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6232–6233) and Muslim (2160).","chapter_en":"The Rider Should Give Salām to the One Who Is Walking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The rider should give salām to the one who is walking, the one who is walking to the one who is sitting, and the smaller group to the larger group.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6232-6233)، ومسلم (2160)."},{"num":14227,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُسَلِّمُ الصَّغِيرُ عَلَى الْكَبِيرِ، وَالْمَارُّ عَلَى الْقَاعِدِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6231) عن محمد بن مقاتل أبو الحسن، أخبرنا عبد الله، أخبرنا معمر، عن همام بن منبه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب يسلم الراكب على الماشي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6231).","chapter_en":"The Rider Should Give Salām to the One Who Is Walking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “The younger should give salām to the older, the one passing by to the one sitting, and the smaller group to the larger group.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6231)."},{"num":14228,"demo":false,"sanad":"","matn":["عَنْ فَضَالَةَ بْنِ عُبَيْدٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: يُسَلِّمُ الْفَارِسُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْقَائِمِ، وَالْقَلِيلُ عَلَى الْكَثِيرِ."],"takhrij":"صحيح: رواه الترمذي (2705)، وأحمد (23940)، والبخاري في الأدب المفرد (998)، والطبراني في الكبير (18/312) كلهم من حديث حيوة بن شريح، أخبرني أبو هانئ اسمه حميد بن هانئ الخولاني، عن أبي علي الجنبي، عن فضالة بن عبيد فذكره. وإسناده صحيح.وقال الترمذي: \" حسن صحيح و أبو علي الجنبي اسمه عمرو بن مالك\".","grade":"صحيح","chapter_ar":"باب يسلم الراكب على الماشي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2705), Aḥmad (23941), and al-Bukhārī in al-Adab al-Mufrad (998).","chapter_en":"The Rider Should Give Salām to the One Who Is Walking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Faḍālah ibn ʿUbayd narrated that the Messenger of Allah ﷺ said: “The mounted person should give salām to the one walking, the one walking to the one standing, and the smaller group to the larger group.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه الترمذي (2705)، وأحمد (23940)، والبخاري في الأدب المفرد (998)."},{"num":14229,"demo":false,"sanad":"","matn":["عن عبد الرحمن بن شبل قال: قال رسول الله صلى الله عليه وسلم: يسلم الراكب على الراجل، والراجل على الجالس، والأقل على الأكثر، فمن أجاب السلام كان له، ومن لم يجب فلا شيء له."],"takhrij":"صحيح: رواه أحمد (15666)، والبخاري في الأدب المفرد (992) كلاهما من حديث يحيى بن أبي كثير، عن زيد بن سلام عن جده قال كتب معاوية إلى عبد الرحمن بن شبل أن علِّمِ الناسَ ما سمعت من رسول الله صلى الله عليه وسلم فجمعهم فقال إني سمعت رسول الله صلى الله عليه وسلم يقول: فذكر الحديث.","grade":"صحيح","chapter_ar":"باب يسلم الراكب على الماشي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (15666) and al-Bukhārī in al-Adab al-Mufrad (992).","chapter_en":"The Rider Should Give Salām to the One Who Is Walking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Shibl narrated that the Messenger of Allah ﷺ said: “The rider should give salām to the one on foot, the one on foot to the one sitting, and the smaller number to the larger number. Whoever returns the salām receives its reward, and whoever does not return it has nothing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (15666)، والبخاري في الأدب المفرد (992)."},{"num":14230,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لِيُسَلِّمِ الرَّاكِبُ عَلَى الْمَاشِي، وَالْمَاشِي عَلَى الْقَاعِدِ، وَالْمَاشِيَانِ أَيُّهُمَا بَدَأَ فَهُوَ أَفْضَلُ."],"takhrij":"حسن: رواه البزار –كشف الأستار (2006)، وصححه ابن حبان (498) كلاهما من طريق أبي عاصم (وهو الضحاك بن مخلد)، عن ابن جريج، قال: أخبرني أبو الزبير أنه سمع جابرا يقول: فذكره.","grade":"حسن","chapter_ar":"باب يسلم الراكب على الماشي","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (2006) and authenticated by Ibn Ḥibbān (498).","chapter_en":"The Rider Should Give Salām to the One Who Is Walking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":20,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “The rider should give salām to the one walking, and the one walking to the one sitting. When two people are both walking, whichever of them begins with salām is better.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار - كشف الأستار (2006)، وصححه ابن حبان (498)."},{"num":14231,"demo":false,"sanad":"","matn":["عَنْ سَيَّارٍ، قَالَ:  كُنْتُ أَمْشِي مَعَ ثَابِتٍ الْبُنَانِيِّ، فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ، وَحَدَّثَ ثَابِتٌ أَنَّهُ كَانَ يَمْشِي مَعَ أَنَسٍ، فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ، وَحَدَّثَ أَنَسٌ أَنَّهُ كَانَ يَمْشِي مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَمَرَّ بِصِبْيَانٍ فَسَلَّمَ عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6247)، ومسلم في السلام (2168: 15) كلاهما من طريق شعبة عن سيار فذكره.","grade":"متفق عليه","chapter_ar":"باب السلام على الصبيان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6247) and Muslim (2168:15).","chapter_en":"Giving Salām to Children","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Sayyār narrated: I was walking with Thābit al-Bunānī when he passed by some children and gave them salām. Thābit narrated that he had been walking with Anas when Anas passed by some children and gave them salām. Anas in turn narrated that he had been walking with the Messenger of Allah ﷺ when he passed by some children and gave them salām."]},"buhuth":{"en":["Al-Nasā’ī added in al-Sunan al-Kubrā (8349), with an authentic chain, that Anas said:","“The Messenger of Allah ﷺ used to visit the Anṣār, give salām to their children, stroke their heads, and supplicate for them.”","Giving salām to children is not itself an established Sunnah to be sought independently, but is done for the purpose of teaching them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6247)، ومسلم (2168: 15)."},{"num":14232,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ:  أَتَى عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَنَا أَلْعَبُ مَعَ الْغِلْمَانِ، قَالَ: فَسَلَّمَ عَلَيْنَا، فَبَعَثَنِي إِلَى حَاجَةٍ، فَأَبْطَأْتُ عَلَى أُمِّي، فَلَمَّا جِئْتُ قَالَتْ: مَا حَبَسَكَ؟ قُلْتُ: بَعَثَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِحَاجَةٍ. قَالَتْ: مَا حَاجَتُهُ؟ قُلْتُ: إِنَّهَا سِرٌّ. قَالَتْ: لَا تُحَدِّثَنَّ بِسِرِّ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَحَدًا. قَالَ أَنَسٌ: وَاللهِ لَوْ حَدَّثْتُ بِهِ أَحَدًا لَحَدَّثْتُكَ يَا ثَابِتُ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2482: 145) عن أبي بكر بن نافع، حدثنا بهز، حدثنا حماد، أنا ثابت، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب السلام على الصبيان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2482:145).","chapter_en":"Giving Salām to Children","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":21,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ came upon me while I was playing with some boys. He gave us salām, then sent me on an errand. I was delayed in returning to my mother. When I came back, she asked: “What kept you?” I replied: “The Messenger of Allah ﷺ sent me on an errand.” She asked: “What was his errand?” I replied: “It is a secret.” She said: “Never disclose the secret of the Messenger of Allah ﷺ to anyone.” Anas said: “By Allah, if I were ever going to tell it to anyone, I would have told you, O Thābit.”"]},"buhuth":{"en":["Aḥmad (13469) and Abū Dāwūd (5203) also narrated a similar report through Ḥumayd from Anas, with the wording:","“He sent me with a message and sat in the shade of a wall—or beside a wall—until I returned to him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2482: 145)."},{"num":14233,"demo":false,"sanad":"","matn":["عَنْ سَهْلٍ، قَالَ: كُنَّا نَفْرَحُ يَوْمَ الْجُمُعَةِ. قُلْتُ: وَلِمَ؟ قَالَ: كَانَتْ لَنَا عَجُوزٌ، تُرْسِلُ إِلَى بُضَاعَةَ ـ قَالَ ابْنُ مَسْلَمَةَ: نَخْلٍ بِالْمَدِينَةِ ـ فَتَأْخُذُ مِنْ أُصُولِ السِّلْقِ، فَتَطْرَحُهُ فِي قِدْرٍ، وَتُكَرْكِرُ حَبَّاتٍ مِنْ شَعِيرٍ، فَإِذَا صَلَّيْنَا الْجُمُعَةَ انْصَرَفْنَا، وَنُسَلِّمُ عَلَيْهَا، فَتُقَدِّمُهُ إِلَيْنَا، فَنَفْرَحُ مِنْ أَجْلِهِ، وَمَا كُنَّا نَقِيلُ وَلاَ نَتَغَدَّى إِلاَّ بَعْدَ الْجُمُعَةِ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6248) عن عبد الله بن مسلمة، حدثنا ابن أبي حازم، عن أبيه، عن سهل، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب تسليم الرجال على النساء، والنساء على الرجال إذا أُمِنَت الفتنة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6248) and Muslim (859).","chapter_en":"Men Giving Salām to Women and Women to Men When There Is No Fear of Temptation","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":22,"content":{"translation":{"en":["Sahl narrated: “We used to rejoice on Fridays.” I asked: “Why?” He replied: There was an elderly woman among us who would send someone to Buḍāʿah—an area of date palms in Madinah, as Ibn Maslamah explained—and she would take the roots of chard, place them in a pot, and add crushed grains of barley. After we had prayed Jumuʿah, we would leave, give her salām, and she would serve it to us. We used to rejoice because of that. We would not take our midday nap or eat lunch until after Jumuʿah."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6248)، ومسلم (859)."},{"num":14234,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ، قَالَتْ: مَرَّ بِنَا النَّبِيُّ ﷺ، وَنَحْنُ فِي نِسْوَةٍ، فَسَلَّمَ عَلَيْنَا."],"takhrij":"حسن: رواه أبو داود (5204)، وابن ماجه (3701)، وأحمد (27561) كلهم من طريق سفيان بن عيينة، عن ابن أبي حسين، سمعه من شهر بن حوشب يقول: أخبرته أسماء ابنة يزيد فذكرته.","grade":"حسن","chapter_ar":"باب تسليم الرجال على النساء، والنساء على الرجال إذا أُمِنَت الفتنة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5204), Ibn Mājah (3701), and Aḥmad (27561).","chapter_en":"Men Giving Salām to Women and Women to Men When There Is No Fear of Temptation","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":22,"content":{"translation":{"en":["Asmāʾ bint Yazīd narrated: The Prophet ﷺ passed by us while we were a group of women, and he gave us salām."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5204)، وابن ماجه (3701)، وأحمد (27561)."},{"num":14235,"demo":false,"sanad":"","matn":["عن أَبِي هُرَيْرَةَ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ: مَنْ لَقِيَ أَخَاهُ فَلْيُسَلِّمْ عَلَيْهِ، وَإِنْ حَالَتْ بَيْنَهُمَا شَجَرَةٌ أَوْ حَائِطٌ أَوْ حَجَرٌ، ثُمَّ لَقِيَهُ فَلْيُسَلِّمْ عَلَيْهِ."],"takhrij":"حسن: رواه أبو داود (5600)، وأبو يعلى (6351)، والطبراني في مسند الشاميين (2072) كلهم من طريق معاوية بن صالح، عن عبد الوهاب بن بخت المكي، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الرجل يفارق صاحبه ثم يلقاه يسلم عليه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5200), Abū Yaʿlā (6351), and al-Ṭabarānī in Musnad al-Shāmiyyīn (2072).","chapter_en":"If a Man Parts from His Companion and Then Meets Him Again, He Should Give Salām Again","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":23,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you meets his brother, let him give him salām. If a tree, wall, or rock comes between them and then he meets him again, let him give him salām again.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5600)، وأبو يعلى (6351)، والطبراني في مسند الشاميين (2072)."},{"num":14236,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: كُنَّا إِذَا كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَتُفَرِّقَ بَيْنَنَا الشَّجَرَةُ، فَإِذَا الْتَقَيْنَا يُسَلِّمُ بَعْضُنَا عَلَى بَعْضٍ."],"takhrij":"حسن: رواه الطبراني في الأوسط (7983) عن موسى بن هارون، ثنا سهل بن صالح الأنطاكي قال: رأيت يزيد بن أبي منصور، فقال: ثنا أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب الرجل يفارق صاحبه ثم يلقاه يسلم عليه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (7983).","chapter_en":"If a Man Parts from His Companion and Then Meets Him Again, He Should Give Salām Again","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":23,"content":{"translation":{"en":["Anas narrated: “When we were with the Messenger of Allah ﷺ and a tree came between us so that we became separated, then when we met again we would give salām to one another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط (7983)."},{"num":14237,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا انْتَهَى أَحَدُكُمْ إِلَى الْمَجْلِسِ فَلْيُسَلِّمْ، فَإِذَا أَرَادَ أَنْ يَقُومَ فَلْيُسَلِّمْ، فَلَيْسَتِ الْأُولَى بِأَحَقَّ مِنَ الآخِرَةِ."],"takhrij":"حسن: رواه أبو داود (5208)، والترمذي (2706)، والبخاري في الأدب المفرد (1007، 1008)، وأحمد (7142)، وصحّحه ابن حبان (494-496) كلهم من طرق عن محمد بن عجلان، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب في السلام إذا جاء إلى المجلس وإذا قام من المجلس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5208), al-Tirmidhī (2706), and al-Bukhārī in al-Adab al-Mufrad (1007, 1008).","chapter_en":"Giving Salām When Entering a Gathering and When Leaving It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":24,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you comes to a gathering, let him give salām. When he wishes to get up and leave, let him give salām. The first greeting is no more deserving than the latter.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5208)، والترمذي (2706)، والبخاري في الأدب المفرد (1007، 1008)."},{"num":14238,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ بْنِ حُصَيْنٍ، قَالَ: جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: السَّلاَمُ عَلَيْكُمْ. فَرَدَّ عَلَيْهِ، السَّلاَمَ ثُمَّ جَلَسَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَشْرٌ. ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ. فَرَدَّ عَلَيْهِ، فَجَلَسَ فَقَالَ: عِشْرُونَ. ثُمَّ جَاءَ آخَرُ فَقَالَ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. فَرَدَّ عَلَيْهِ، فَجَلَسَ فَقَالَ: ثَلاَثُونَ."],"takhrij":"حسن: رواه أبو داود (5195)، والترمذي (2689)، وأحمد (19948)، والنسائي في عمل اليوم والليلة (337) كلهم عن محمد بن كثير، حدثنا جعفر بن سليمان، عن عوف-وهو ابن أبي جميلة الأعرابي، عن أبي رجاء العطاردي، عن عمران بن حصين فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في رد السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5195), al-Tirmidhī (2689), Aḥmad (19948), and al-Nasā’ī in ʿAmal al-Yawm wa-al-Laylah (337).","chapter_en":"What Has Been Narrated Concerning Returning the Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":25,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn narrated: A man came to the Prophet ﷺ and said: “Peace be upon you.” The Prophet ﷺ returned his greeting, and the man sat down. The Prophet ﷺ said: “Ten.” Then another man came and said: “Peace be upon you and the mercy of Allah.” The Prophet ﷺ returned his greeting, and the man sat down. He said: “Twenty.” Then another man came and said: “Peace be upon you, and the mercy of Allah, and His blessings.” The Prophet ﷺ returned his greeting, and the man sat down. He said: “Thirty.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12189],"tks":"حسن: رواه أبو داود (5195)، والترمذي (2689)، وأحمد (19948)، والنسائي في عمل اليوم والليلة (337)."},{"num":14239,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً مَرَّ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ فِي مَجْلِسٍ، فَقَالَ: السَّلاَمُ عَلَيْكُمْ، فَقَالَ: عَشْرُ حَسَنَاتٍ، فَمَرَّ رَجُلٌ آخَرُ فَقَالَ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ، فَقَالَ: عِشْرُونَ حَسَنَةً، فَمَرَّ رَجُلٌ آخَرُ فَقَالَ: السَّلاَمُ عَلَيْكُمْ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، فَقَالَ: ثَلاَثُونَ حَسَنَةً، فَقَامَ رَجُلٌ مِنَ الْمَجْلِسِ وَلَمْ يُسَلِّمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا أَوْشَكَ مَا نَسِيَ صَاحِبُكُمْ، إِذَا جَاءَ أَحَدُكُمُ الْمَجْلِسَ فَلْيُسَلِّمْ، فَإِنْ بَدَا لَهُ أَنْ يَجْلِسَ فَلْيَجْلِسْ، وَإِذَا قَامَ فَلْيُسَلِّمْ، مَا الْأُولَى بِأَحَقَّ مِنَ الآخِرَةِ."],"takhrij":"صحيح: رواه البخاري في الأدب المفرد (986) عن عبد العزيز بن عبد الله قال: حدثني محمد بن جعفر بن أبي كثير، عن يعقوب بن زيد التيمي، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في رد السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in al-Adab al-Mufrad (986) and authenticated by Ibn Ḥibbān (493).","chapter_en":"What Has Been Narrated Concerning Returning the Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated: A man passed by the Messenger of Allah ﷺ while he was sitting in a gathering and said: “Peace be upon you.” The Prophet ﷺ said: “Ten good deeds.” Another man passed and said: “Peace be upon you and the mercy of Allah.” He said: “Twenty good deeds.” Then another man passed and said: “Peace be upon you, and the mercy of Allah, and His blessings.” He said: “Thirty good deeds.” Then a man got up from the gathering and left without giving salām. The Prophet ﷺ said: “How quickly your companion forgot! When one of you comes to a gathering, let him give salām. If he then wishes to sit, let him sit. And when he gets up to leave, let him give salām. The first greeting is no more deserving than the latter.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12190,12904],"tks":"صحيح: رواه البخاري في الأدب المفرد (986)، وصححه ابن حبان (493)."},{"num":14240,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُرَىٍّ، جَابِرِ بْنِ سُلَيْمٍ، قَالَ: رَأَيْتُ رَجُلاً يَصْدُرُ النَّاسُ عَنْ رَأْيِهِ، لاَ يَقُولُ شَيْئًا إِلاَّ صَدَرُوا عَنْهُ، قُلْتُ: مَنْ هَذَا؟ قَالُوا: هَذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قُلْتُ: عَلَيْكَ السَّلاَمُ يَا رَسُولَ اللَّهِ، مَرَّتَيْنِ. قَالَ: لاَ تَقُلْ: عَلَيْكَ السَّلاَمُ. فَإِنَّ عَلَيْكَ السَّلاَمُ تَحِيَّةُ الْمَيِّتِ، قُلِ: السَّلاَمُ عَلَيْكَ. قَالَ: قُلْتُ: أَنْتَ رَسُولُ اللَّهِ؟ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَنَا رَسُولُ اللَّهِ الَّذِي إِذَا أَصَابَكَ ضُرٌّ فَدَعَوْتَهُ كَشَفَهُ عَنْكَ، وَإِنْ أَصَابَكَ عَامُ سَنَةٍ فَدَعَوْتَهُ، أَنْبَتَهَا لَكَ، وَإِذَا كُنْتَ بِأَرْضٍ قَفْرَاءَ أَوْ فَلاَةٍ فَضَلَّتْ رَاحِلَتُكَ فَدَعَوْتَهُ، رَدَّهَا عَلَيْكَ. قُلْتُ: اعْهَدْ إِلَىَّ. قَالَ: لاَ تَسُبَّنَّ أَحَدًا. قَالَ: فَمَا سَبَبْتُ بَعْدَهُ حُرًّا، وَلاَ عَبْدًا، وَلاَ بَعِيرًا، وَلاَ شَاةً. قَالَ: وَلاَ تَحْقِرَنَّ شَيْئًا مِنَ الْمَعْرُوفِ، وَأَنْ تُكَلِّمَ أَخَاكَ وَأَنْتَ مُنْبَسِطٌ إِلَيْهِ وَجْهُكَ إِنَّ ذَلِكَ مِنَ الْمَعْرُوفِ، وَارْفَعْ إِزَارَكَ إِلَى نِصْفِ السَّاقِ، فَإِنْ أَبَيْتَ فَإِلَى الْكَعْبَيْنِ، وَإِيَّاكَ وَإِسْبَالَ الإِزَارِ، فَإِنَّهَا مِنَ الْمَخِيلَةِ، وَإِنَّ اللَّهَ لاَ يُحِبُّ الْمَخِيلَةَ، وَإِنِ امْرُؤٌ شَتَمَكَ وَعَيَّرَكَ بِمَا يَعْلَمُ فِيكَ، فَلاَ تُعَيِّرْهُ بِمَا تَعْلَمُ فِيهِ، فَإِنَّمَا وَبَالُ ذَلِكَ عَلَيْهِ."],"takhrij":"صحيح: رواه أبو داود (4084) واللفظ له، والترمذي (2722)، والبيهقي في الشعب (5730) كلهم من حديث أبي غفار المثنى بن سعيد الطائي، عن أبي تميمة الهُجيمي، عن جابر بن سليم فذكره.","grade":"صحيح","chapter_ar":"باب كراهية أن يقول: عليك السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4084), and this is his wording, al-Tirmidhī (2722), and al-Bayhaqī in Shuʿab al-Īmān (5730).","chapter_en":"The Dislike of Saying “ʿAlayka al-Salām”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":26,"content":{"translation":{"en":["Abū Jurayy Jābir ibn Sulaym narrated: I saw a man whose judgment the people followed. He would not say anything except that they acted upon it. I asked: “Who is this?” They replied: “This is the Messenger of Allah ﷺ.” I said twice: “Upon you be peace, O Messenger of Allah.” He said: “Do not say, ‘Upon you be peace,’ for ‘upon you be peace’ is the greeting of the dead. Rather say: ‘Peace be upon you.’” I asked: “Are you the Messenger of Allah?” He replied: “I am the Messenger of Allah. He is the One whom, if harm afflicts you and you call upon Him, He removes it from you; and if a year of drought afflicts you and you call upon Him, He causes the earth to grow for you; and if you are in a barren land—or wilderness—and your riding animal becomes lost, then you call upon Him and He returns it to you.” I said: “Give me some instruction.” He said: “Never insult anyone.” Jābir said: “After that I never insulted a free person, a slave, a camel, or a sheep.” Then the Messenger of Allah ﷺ said: “Do not belittle any good deed, even speaking to your brother while your face is cheerful toward him, for that is part of goodness. Raise your lower garment to the middle of your shin; if you refuse, then at least to the ankles. Beware of letting the lower garment trail beneath the ankles, for that is from arrogance, and Allah does not love arrogance. If a man insults you and shames you for something he knows about you, do not shame him for something you know about him, for the burden of that will fall upon him.”"]},"buhuth":{"en":["Regarding the words, “ʿAlayka al-salām is the greeting of the dead,” al-Khaṭṭābī said:","“This might give the impression that the Sunnah when greeting the dead is to say, ‘ʿAlayka al-salām,’ as many common people do. However, it is authentically established that the Prophet ﷺ entered the graveyard and said: ‘Peace be upon you, inhabitants of the abode of believing people.’ Thus, he placed the supplication before the person being addressed, just as is done when greeting the living. His statement merely referred to the customary manner in which the Arabs used to address the dead, whereby they placed the name of the deceased before the supplication… Therefore, the Sunnah does not differ between greeting the living and greeting the dead.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[15372],"tks":"صحيح: رواه أبو داود (4084) - واللفظ له -، والترمذي (2722)، والبيهقي في الشعب (5730)."},{"num":14241,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: ـ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، دَخَلَ الْمَسْجِدَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسٌ فِي نَاحِيَةِ الْمَسْجِدِ، فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ عَلَيْهِ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَلَيْكَ السَّلاَمُ، ارْجِعْ فَصَلِّ فَإِنَّكَ لَمْ تُصَلِّ. فَرَجَعَ فَصَلَّى، ثُمَّ جَاءَ فَسَلَّمَ. فَقَالَ: وَعَلَيْكَ السَّلاَمُ، فَارْجِعْ فَصَلِّ، فَإِنَّكَ لَمْ تُصَلِّ. فَقَالَ فِي الثَّانِيَةِ، أَوْ فِي الَّتِي بَعْدَهَا: عَلِّمْنِي يَا رَسُولَ اللَّهِ. فَقَالَ: إِذَا قُمْتَ إِلَى الصَّلاَةِ فَأَسْبِغِ الْوُضُوءَ، ثُمَّ اسْتَقْبِلِ الْقِبْلَةَ فَكَبِّرْ، ثُمَّ اقْرَأْ بِمَا تَيَسَّرَ مَعَكَ مِنَ الْقُرْآنِ، ثُمَّ ارْكَعْ حَتَّى تَطْمَئِنَّ رَاكِعًا، ثُمَّ ارْفَعْ حَتَّى تَسْتَوِيَ قَائِمًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا، ثُمَّ اسْجُدْ حَتَّى تَطْمَئِنَّ سَاجِدًا، ثُمَّ ارْفَعْ حَتَّى تَطْمَئِنَّ جَالِسًا، ثُمَّ افْعَلْ ذَلِكَ فِي صَلاَتِكَ كُلِّهَا. وَقَالَ أَبُو أُسَامَةَ، فِي الأَخِيرِ: حَتَّى تَسْتَوِيَ قَائِمًا."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6251) ومسلم في الصلاة (397) كلاهما من طريق عبيد الله (هو ابن عمر)، عن سعيد بن أبي سعيد المقبري، عن أبي هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب من رد فقال: عليك السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6251) and Muslim (397). The wording is that of al-Bukhārī.","chapter_en":"One Who Replies by Saying “ʿAlayka al-Salām”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":27,"content":{"translation":{"en":["Abū Hurayrah narrated: A man entered the mosque while the Messenger of Allah ﷺ was sitting in one part of it. The man prayed, then came and greeted him with salām. The Messenger of Allah ﷺ replied: “And upon you be peace. Go back and pray, for you have not prayed.” So the man went back and prayed, then came and greeted him again. The Messenger of Allah ﷺ replied: “And upon you be peace. Go back and pray, for you have not prayed.” On the second occasion—or a later one—the man said: “Teach me, O Messenger of Allah.” He said: “When you stand for prayer, perform your wuḍūʾ thoroughly. Then face the qiblah and say the takbīr. Then recite whatever is easy for you from the Qur’an. Then bow until you are at rest in bowing. Then rise until you are standing upright. Then prostrate until you are at rest in prostration. Then rise until you are at rest while sitting. Then prostrate until you are at rest in prostration. Then rise until you are at rest while sitting. Then do that throughout your entire prayer.” Abū Usāmah said that in the final wording it says: “Until you are standing upright.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6251)، ومسلم (397)، واللفظ للبخاري."},{"num":14242,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن حسن بن حسن بن عَلِيٍّ عَنِ أَبِيهِ، عَنِ جَدِّهِ قَالَ: قِيلَ: يَا رَسُولَ اللَّهِ، الْقَوْمُ يَأْتُونَ الدَّارَ، فَيَسْتَأْذِنُ وَاحِدٌ مِنْهُمْ أيجزيء عَنْهُمْ جَمِيعًا؟ قَالَ: نَعَمْ قِيلَ: فَيَرُدُّ رَجُلٌ مِنَ الْقَوْمِ أيجزىء عَنِ الْجَمِيعِ؟ قَالَ: نَعَمْ قِيلَ: القوم يَمُرُّونَ فَيُسَلِّمُ وَاحِدٌ مِنْهُمْ أيجزيء عَنِ الْجَمِيعِ؟ قَالَ: نَعَمْ، قِيلَ: فَيَرُدُّ رَجُلٌ مِنَ الْقَوْمِ أيجزىء عَنِ الْجَمِيعِ؟ قَالَ: نَعَمْ."],"takhrij":"حسن: رواه الطبراني في الكبير (2730) عن إبراهيم بن هاشم البغوي، ثنا كثير بن يحيى، ثنا حفص بن عمر الرقاشي، ثنا عبد الله بن حسن بن حسن بن علي عن أبيه، عن جده قال: فذكره.","grade":"حسن","chapter_ar":"باب في رد سلام الواحد عن الجماعة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (3/84).","chapter_en":"One Person Returning Salām on Behalf of a Group","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullāh ibn Ḥasan ibn Ḥasan ibn ʿAlī narrated from his father, from his grandfather: It was asked: “O Messenger of Allah, if a group comes to a house and one of them seeks permission, is that sufficient for all of them?” He replied: “Yes.” It was asked: “If one man from the people of the house responds, is that sufficient on behalf of all of them?” He replied: “Yes.” It was asked: “If a group passes by and one of them gives salām, is that sufficient on behalf of all of them?” He replied: “Yes.” It was asked: “If one person from the other group returns the salām, is that sufficient for all of them?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (2730)."},{"num":14243,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَائِشَةُ هَذَا جِبْرِيلُ يَقْرَأُ عَلَيْكِ السَّلاَمَ. قَالَتْ: قُلْتُ: وَعَلَيْهِ السَّلاَمُ وَرَحْمَةُ اللَّهِ، تَرَى مَا لاَ نَرَى. تُرِيدُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6249)، ومسلم في فضائل الصحابة (2447: 91) كلاهما من طريق الزهري، عن أبي سلمة بن عبد الرحمن، عن عائشة فذكرته. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب كيف يجاب إذا قال: فلان يقرئك السلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6249) and Muslim (2447:91). The wording is that of al-Bukhārī.","chapter_en":"How to Respond When Told, “So-and-So Sends You Salām”","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":29,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ said: “O ʿĀ’ishah, this is Jibrīl sending you salām.” She said: “And upon him be peace and the mercy of Allah. You see what we do not see.” She meant the Messenger of Allah ﷺ."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6249)، ومسلم (2447: 91)، واللفظ للبخاري."},{"num":14244,"demo":false,"sanad":"","matn":["عن جابر: أَنَّ رَجُلا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَال: إِنَّ لِفُلانٍ فِي حَائِطِي عَذْقًا، وَإِنَّهُ قَدْ آذَانِي وَشَقَّ عَلَيَّ مَكَانُ عَذْقِهِ. فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: بِعْنِي عَذْقَكَ الَّذِي فِي حَائِطِ فُلانٍ. قَال: لا قَال: فَهَبْهُ لِي. قَال: لا. قَال: فَبِعْنِيهِ بِعَذْقٍ فِي الجَنَّةِ. قَال: لا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا رَأَيْتُ الَّذِي هُوَ أَبْخَلُ مِنْكَ إِلا الَّذِي يَبْخَلُ بِالسَّلامِ."],"takhrij":"حسن: رواه أحمد (14517) عن أبي عامر العقديّ، حدّثنا زهير، عن عبدالله بن محمد بن عقيل، عن جابر، فذكره.","grade":"حسن","chapter_ar":"باب البخل بالسلام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (14517).","chapter_en":"Miserliness in Giving Salām","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":30,"content":{"translation":{"en":["Jābir narrated: A man came to the Prophet ﷺ and said: “So-and-so has a date-palm cluster in my garden, and its location has caused me harm and hardship.” The Prophet ﷺ sent for the owner and said: “Sell me your date-palm cluster that is in so-and-so’s garden.” He replied: “No.” He said: “Then give it to me as a gift.” He replied: “No.” He said: “Then sell it to me in exchange for a date-palm cluster in Paradise.” He replied: “No.” The Prophet ﷺ then said: “I have not seen anyone more miserly than you except the one who is miserly with salām.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14995],"tks":"حسن: رواه أحمد (14517)."},{"num":14245,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَادِ قَالَ:  أَقْبَلْتُ أَنَا وَصَاحِبَانِ لِي، وَقَدْ ذَهَبَتْ أَسْمَاعُنَا وَأَبْصَارُنَا مِنَ الْجَهْدِ، فَجَعَلْنَا نَعْرِضُ أَنْفُسَنَا عَلَى أَصْحَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَيْسَ أَحَدٌ مِنْهُمْ يَقْبَلُنَا، فَأَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْطَلَقَ بِنَا إِلَى أَهْلِهِ، فَإِذَا ثَلَاثَةُ أَعْنُزٍ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: احْتَلِبُوا هَذَا اللَّبَنَ بَيْنَنَا. قَالَ: فَكُنَّا نَحْتَلِبُ، فَيَشْرَبُ كُلُّ إِنْسَانٍ مِنَّا نَصِيبَهُ، وَنَرْفَعُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَصِيبَهُ، قَالَ: فَيَجِيءُ مِنَ اللَّيْلِ فَيُسَلِّمُ تَسْلِيمًا لَا يُوقِظُ نَائِمًا، وَيُسْمِعُ الْيَقْظَانَ، قَالَ: ثُمَّ يَأْتِي الْمَسْجِدَ فَيُصَلِّي، ثُمَّ يَأْتِي شَرَابَهُ فَيَشْرَبُ، فَأَتَانِي الشَّيْطَانُ ذَاتَ لَيْلَةٍ وَقَدْ شَرِبْتُ نَصِيبِي، فَقَالَ: مُحَمَّدٌ يَأْتِي الْأَنْصَارَ فَيُتْحِفُونَهُ وَيُصِيبُ عِنْدَهُمْ، مَا بِهِ حَاجَةٌ إِلَى هَذِهِ الْجُرْعَةِ، فَأَتَيْتُهَا فَشَرِبْتُهَا، فَلَمَّا أَنْ وَغَلَتْ فِي بَطْنِي، وَعَلِمْتُ أَنَّهُ لَيْسَ إِلَيْهَا سَبِيلٌ، قَالَ: نَدَّمَنِي الشَّيْطَانُ، فَقَالَ: وَيْحَكَ، مَا صَنَعْتَ؟ أَشَرِبْتَ شَرَابَ مُحَمَّدٍ، فَيَجِيءُ فَلَا يَجِدُهُ، فَيَدْعُو عَلَيْكَ فَتَهْلِكُ، فَتَذْهَبُ دُنْيَاكَ وَآخِرَتُكَ؟ وَعَلَيَّ شَمْلَةٌ إِذَا وَضَعْتُهَا عَلَى قَدَمَيَّ خَرَجَ رَأْسِي، وَإِذَا وَضَعْتُهَا عَلَى رَأْسِي خَرَجَ قَدَمَايَ، وَجَعَلَ لَا يَجِيئُنِي النَّوْمُ، وَأَمَّا صَاحِبَايَ فَنَامَا وَلَمْ يَصْنَعَا مَا صَنَعْتُ، قَالَ: فَجَاءَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَلَّمَ كَمَا كَانَ يُسَلِّمُ، ثُمَّ أَتَى الْمَسْجِدَ فَصَلَّى، ثُمَّ أَتَى شَرَابَهُ فَكَشَفَ عَنْهُ، فَلَمْ يَجِدْ فِيهِ شَيْئًا، فَرَفَعَ رَأْسَهُ إِلَى السَّمَاءِ، فَقُلْتُ: الْآنَ يَدْعُو عَلَيَّ فَأَهْلِكُ، فَقَالَ: اللَّهُمَّ، أَطْعِمْ مَنْ أَطْعَمَنِي، وَأَسْقِ مَنْ أَسْقَانِي. قَالَ: فَعَمَدْتُ إِلَى الشَّمْلَةِ فَشَدَدْتُهَا عَلَيَّ، وَأَخَذْتُ الشَّفْرَةَ فَانْطَلَقْتُ إِلَى الْأَعْنُزِ أَيُّهَا أَسْمَنُ، فَأَذْبَحُهَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَإِذَا هِيَ حَافِلَةٌ، وَإِذَا هُنَّ حُفَّلٌ كُلُّهُنَّ، فَعَمَدْتُ إِلَى إِنَاءٍ لِآلِ مُحَمَّدٍ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، مَا كَانُوا يَطْمَعُونَ أَنْ يَحْتَلِبُوا فِيهِ، قَالَ: فَحَلَبْتُ فِيهِ حَتَّى عَلَتْهُ رَغْوَةٌ، فَجِئْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: أَشَرِبْتُمْ شَرَابَكُمُ اللَّيْلَةَ؟. قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، اشْرَبْ. فَشَرِبَ، ثُمَّ نَاوَلَنِي، فَقُلْتُ: يَا رَسُولَ اللَّهِ، اشْرَبْ. فَشَرِبَ، ثُمَّ نَاوَلَنِي، فَلَمَّا عَرَفْتُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ رَوِيَ وَأَصَبْتُ دَعْوَتَهُ، ضَحِكْتُ حَتَّى أُلْقِيتُ إِلَى الْأَرْضِ، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِحْدَى سَوْآتِكَ يَا مِقْدَادُ. فَقُلْتُ: يَا رَسُولَ اللَّهِ، كَانَ مِنْ أَمْرِي كَذَا وَكَذَا، وَفَعَلْتُ كَذَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا هَذِهِ إِلَّا رَحْمَةٌ مِنَ اللَّهِ، أَفَلَا كُنْتَ آذَنْتَنِي فَنُوقِظَ صَاحِبَيْنَا فَيُصِيبَانِ مِنْهَا؟ قَالَ: فَقُلْتُ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا أُبَالِي إِذَا أَصَبْتَهَا وَأَصَبْتُهَا مَعَكَ مَنْ أَصَابَهَا مِنَ النَّاسِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2055) عن أبي بكر بن أبي شيبة، حدثنا شبابة بن سوار، حدثنا سليمان بن المغيرة، عن ثابت، عن عبد الرحمن بن أبي ليلى، عن المقداد بن الأسود فذكره.","grade":"صحيح","chapter_ar":"باب التسليم على النائم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2055).","chapter_en":"Giving Salām in the Presence of a Sleeping Person","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":31,"content":{"translation":{"en":["Al-Miqdād ibn al-Aswad narrated: Two companions and I came in such a state of exhaustion and hunger that our hearing and sight had been affected. We began presenting ourselves to the Companions of the Messenger of Allah ﷺ, but none of them was able to take us in. So we came to the Prophet ﷺ, and he took us to his household. There were three goats there. The Prophet ﷺ said: “Milk them and divide the milk among us.” So we would milk them. Each of us would drink his own share, and we would set aside the share of the Prophet ﷺ for him. He would come during the night and give salām in such a manner that he would not awaken a sleeping person, while one who was awake could hear him. Then he would go to the mosque and pray, after which he would come to his drink and drink it. One night, after I had drunk my own share, Satan came to me and said: “Muḥammad goes to the Anṣār, and they give him gifts and food. He has no need for this little drink.” So I went to his portion and drank it. Once it had settled in my stomach and I knew there was no way to return it, Satan made me regret what I had done. He said: “Woe to you! What have you done? You drank Muḥammad’s drink! He will come and not find it, then he will supplicate against you and you will be destroyed, losing both your worldly life and your Hereafter.” I had only a small cloak. When I covered my feet with it, my head was exposed, and when I covered my head, my feet were exposed. Sleep would not come to me. As for my two companions, they slept because they had not done what I had done. Then the Prophet ﷺ came and gave salām just as he normally did. He went to the mosque and prayed, then came to his drink and uncovered it, but found nothing there. He raised his head toward the sky. I thought: “Now he will supplicate against me and I will be destroyed.” But he said: “O Allah, feed whoever feeds me, and give drink to whoever gives me drink.” I immediately took my cloak and tied it tightly around myself, picked up a knife, and went toward the goats to find the fattest one so that I could slaughter it for the Messenger of Allah ﷺ. But I found one of them with a full udder, and in fact all of them had full udders. So I took a vessel belonging to the household of Muḥammad ﷺ, one which they would never have expected to fill with milk, and I milked into it until foam rose over its top. Then I brought it to the Messenger of Allah ﷺ. He asked: “Have you drunk your share tonight?” I replied: “O Messenger of Allah, drink.” So he drank and handed the vessel back to me. I said: “O Messenger of Allah, drink.” He drank again and handed it back to me. When I realized that the Prophet ﷺ had drunk his fill and that I had received the benefit of his supplication, I began laughing until I fell to the ground. The Prophet ﷺ said: “This must be one of your mischievous acts, O Miqdād.” I said: “O Messenger of Allah, this is what happened to me, and I did such-and-such.” The Prophet ﷺ said: “This was nothing but a mercy from Allah. Why did you not inform me so that we could wake our two companions and they too could have some of it?” I replied: “By the One who sent you with the truth, once you and I have received it together, I do not care who else among the people receives it.”"]}},"tuhfa":{},"full":1,"rep":[10315],"tks":"صحيح: رواه مسلم (2055)."},{"num":14246,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ  أَنَّ رَجُلًا مَرَّ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبُولُ، فَسَلَّمَ، فَلَمْ يَرُدَّ عَلَيْهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (370) عن محمد بن بن عبد الله بن نمير، حدثنا أبي، حدثنا سفيان، عن الضحاك بن عثمان، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب كراهية التسليم على من يبول","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (370).","chapter_en":"The Dislike of Giving Salām to One Who Is Urinating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":32,"content":{"translation":{"en":["Ibn ʿUmar narrated: A man passed by while the Messenger of Allah ﷺ was urinating and gave him salām, but the Prophet ﷺ did not return his greeting."]}},"tuhfa":{},"full":1,"rep":[1443,1720],"tks":"صحيح: رواه مسلم (370)."},{"num":14247,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَبْدَءُوا الْيَهُودَ وَلَا النَّصَارَى بِالسَّلَامِ، فَإِذَا لَقِيتُمْ أَحَدَهُمْ فِي طَرِيقٍ، فَاضْطَرُّوهُ إِلَى أَضْيَقِهِ."],"takhrij":"صحيح: رواه مسلم في السلام (2167) عن قتيبة بن سعيد، حدثنا عبد العزيز (يعني الدراوردي) عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2167).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Do not initiate the Jews or Christians with salām. If you meet one of them on a road, then make him take its narrower side.”"]},"buhuth":{"en":["Abū Dāwūd (5205) also narrated through Shuʿbah, from Suhayl ibn Abī Ṣāliḥ, who said:","“I went with my father to al-Shām. They would pass by monasteries containing Christians and greet them with salām. My father said: ‘Do not initiate them with salām, for Abū Hurayrah narrated to us from the Messenger of Allah ﷺ…’”","Then he mentioned a similar narration.","The words:","“make him take its narrower side”","do not mean that if the road is wide you should deliberately try to constrict it upon them, for that would involve harming them. Rather, it means that you do not move aside from the road for him; instead, he is the one who moves aside. This is unlike when the person passing is a Muslim scholar or a person of standing, in which case one should move aside for him out of honor and respect."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8170],"tks":"صحيح: رواه مسلم (2167)."},{"num":14248,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: دَخَلَ رَهْطٌ مِنَ الْيَهُودِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكُمُ، فَفَهِمْتُهَا فَقُلْتُ: وَعَلَيْكُمْ السَّامُ وَاللَّعْنَةُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَهْلاً يَا عَائِشَةُ، فَإِنَّ اللَّهَ يُحِبُّ الرِّفْقَ فِي الأَمْرِ كُلِّهِ فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَوَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَقَدْ قُلْتُ: وَعَلَيْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6256)، ومسلم في السلام (2165) كلاهما من طرق عن الزهري، عن عروة، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6256) and Muslim (2165).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated: A group of Jews entered upon the Messenger of Allah ﷺ and said: “Al-sāmu ʿalaykum” — meaning, “Death be upon you.” I understood what they had said, so I replied: “And upon you be death and the curse.” The Messenger of Allah ﷺ said: “Gently, O ʿĀ’ishah. Indeed, Allah loves gentleness in every matter.” I said: “O Messenger of Allah, did you not hear what they said?” The Messenger of Allah ﷺ replied: “I already said: ‘And upon you.’”"]},"buhuth":{"en":["In another narration of al-Bukhārī (6030), he said:","“Did you not hear what I said? I returned it upon them, and my supplication concerning them will be answered, while theirs concerning me will not be answered.”","In Muslim’s narration, ʿĀ’ishah said:","“Rather, upon you be death and disgrace.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6256)، ومسلم (2165)."},{"num":14249,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ قَالَ: قَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إن الْيَهُودُ إِذَا سَلَّمَ عَلَيْكُمُ أَحَدُهُمُ فَإِنَّمَا يَقُولُ: السَّامُ عَلَيْكُمُ، فَقُلْ: عَلَيْكَ."],"takhrij":"متفق عليه: رواه مالك في السلام (3) عن عبد الله بن دينار، عن عبد الله بن عمر فذكره. ورواه البخاري في الاستئذان (6257) من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Salām (3), al-Bukhārī (6257), and Muslim (2164).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “When one of the Jews greets you, he may only be saying, ‘Death be upon you,’ so say: ‘And upon you.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8173],"tks":"متفق عليه: رواه مالك (3)، والبخاري (6257)، ومسلم (2164)."},{"num":14250,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ، يَقُولُ:  سَلَّمَ نَاسٌ مِنْ يَهُودَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: السَّامُ عَلَيْكَ يَا أَبَا الْقَاسِمِ! فَقَالَ: وَعَلَيْكُمْ. فَقَالَتْ عَائِشَةُ: وَغَضِبَتْ: أَلَمْ تَسْمَعْ مَا قَالُوا؟ قَالَ: بَلَى، قَدْ سَمِعْتُ فَرَدَدْتُ عَلَيْهِمْ، وَإِنَّا نُجَابُ عَلَيْهِمْ وَلَا يُجَابُونَ عَلَيْنَا."],"takhrij":"صحيح: رواه مسلم في السلام (2166) من طرق عن حجاج بن محمد، قال: قال ابن جريج: أخبرني أبو الزبير، أنه سمع جابر بن عبد الله، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2166).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: Some Jews greeted the Messenger of Allah ﷺ, saying: “Death be upon you, O Abū al-Qāsim.” He replied: “And upon you.” ʿĀ’ishah became angry and said: “Did you not hear what they said?” He replied: “Yes, I heard them and returned it upon them. Our supplication against them is answered, while their supplication against us is not answered.”"]}},"tuhfa":{},"full":1,"rep":[8171,13506],"tks":"صحيح: رواه مسلم (2166)."},{"num":14251,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَصْرَةَ الْغِفَارِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَهُمْ يَوْمًا: إِنِّي رَاكِبٌ إِلَى يَهُودَ، فَمَنْ انْطَلَقَ مَعِي، فَإِنْ سَلَّمُوا عَلَيْكُمْ فَقُولُوا: وَعَلَيْكُمْ، فَانْطَلَقْنَا، فَلَمَّا جِئْنَاهُمْ وَسَلَّمُوا عَلَيْنَا فَقُلْنَا: وَعَلَيْكُمْ."],"takhrij":"حسن: رواه أحمد (27235) –واللفظ له-، والنسائي في الكبرى (10148) مختصرا من طرق عن عبد الحميد بن جعفر، أخبرني يزيد بن أبي حبيب، عن مرثد بن عبد الله، عن أبي بصرة الغفاري فذكره.","grade":"حسن","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (27235), and this is his wording, and al-Nasā’ī in al-Sunan al-Kubrā (10148).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Abū Baṣrah al-Ghifārī narrated: The Messenger of Allah ﷺ said to them one day: “I am going to ride to the Jews. Whoever comes with me, if they greet you, then say: ‘And upon you.’” So we went with him. When we came to them, they greeted us, and we replied: “And upon you.”"]},"buhuth":{"en":["Aḥmad (27226) also narrated it through Ibn Lahīʿah, who said: Yazīd ibn Abī Ḥabīb narrated to us, from Abū al-Khayr—who is Marthad ibn ʿAbdullāh—who said:","“I heard Abū Baṣrah…”","Then he mentioned a shortened version of it, containing the addition:","“Do not initiate them with salām.”","There is well-known scholarly criticism concerning Ibn Lahīʿah."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8175],"tks":"حسن: رواه أحمد (27235) - واللفظ له -، والنسائي في الكبرى (10148)."},{"num":14252,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ فَقُولُوا: وَعَلَيْكُمْ.","وفي لفظ لمسلم: أَنَّ أَصْحَابَ النَّبِيِّ صلى الله عليه وسلم قَالُوا لِلنَّبِيِّ صلى الله عليه وسلم: إِنَّ أَهْلَ الْكِتَابِ يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ؟ قَالَ: قُولُوا: وَعَلَيْكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6258)، ومسلم في السلام (2163: 6) من طرق عن هشيم، أخبرنا عبيد الله بن أبي بكر بن أنس، عن جده أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6258) and Muslim (2163:6). Muslim (2163:7) also narrated the second wording.","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Anas narrated that the Prophet ﷺ said: “When the People of the Book greet you, say: ‘And upon you.’” In another wording of Muslim, the Companions of the Prophet ﷺ said: “The People of the Book greet us. How should we respond to them?” He replied: “Say: ‘And upon you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6258)، ومسلم (2163: 6). ورواه مسلم (2163: 7) باللفظ الثاني."},{"num":14253,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ قَالَ: مرَّ يَهُودِيٌّ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: السَّامُ عَلَيْكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَعَلَيْكَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَتَدْرُونَ مَا يَقُولُ؟ قَالَ: السَّامُ عَلَيْكَ قَالُوا: يَا رَسُولَ اللَّهِ، أَلاَ نَقْتُلُهُ؟ قَالَ: لاَ، إِذَا سَلَّمَ عَلَيْكُمْ أَهْلُ الْكِتَابِ، فَقُولُوا: وَعَلَيْكُمْ."],"takhrij":"صحيح: رواه البخاري في استتابة المرتدين (6926) عن محمد بن مقاتل أبي الحسن، أخبرنا عبد الله، أخبرنا شعبة، عن هشام بن زيد بن أنس بن مالك، قال: سمعت أنس بن مالك، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6926).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["Anas narrated: A Jewish man passed by the Messenger of Allah ﷺ and said: “Death be upon you.” The Messenger of Allah ﷺ replied: “And upon you.” Then the Messenger of Allah ﷺ asked: “Do you know what he said? He said: ‘Death be upon you.’” They said: “O Messenger of Allah, shall we not kill him?” He replied: “No. When the People of the Book greet you, say: ‘And upon you.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6926)."},{"num":14254,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ:  أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُنَاسٌ مِنَ الْيَهُودِ فَقَالُوا: السَّامُ عَلَيْكَ يَا أَبَا الْقَاسِمِ! قَالَ: وَعَلَيْكُمْ. قَالَتْ عَائِشَةُ: قُلْتُ: بَلْ عَلَيْكُمُ السَّامُ وَالذَّامُ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا عَائِشَةُ، لَا تَكُونِي فَاحِشَةً. فَقَالَتْ: مَا سَمِعْتَ مَا قَالُوا؟ فَقَالَ: أَوَلَيْسَ قَدْ رَدَدْتُ عَلَيْهِمُ الَّذِي قَالُوا؟ قُلْتُ: وَعَلَيْكُمْ.","وفي رواية: فَفَطِنَتْ بِهِمْ عَائِشَةُ فَسَبَّتْهُمْ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: مَهْ يَا عَائِشَةُ، فَإِنَّ اللَّهَ لَا يُحِبُّ الْفُحْشَ وَالتَّفَحُّشَ وَزَادَ فَأَنْزَلَ اللَّهُ عز وجل: ﴿وَإِذَا جَاءُوكَ حَيَّوْكَ بِمَا لَمْ يُحَيِّكَ بِهِ اللَّهُ﴾ [المجادلة: ٨] إلى آخر الآية."],"takhrij":"صحيح: رواه مسلم في السلام (2165: 11) عن أبي كريب، حدثنا أبو معاوية، عن الأعمش، عن مسلم، عن مسروق، عن عائشة، قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب كراهية ابتداء أهل الكتاب بالسلام، وكيفية الرد عليهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2165:11).","chapter_en":"The Dislike of Initiating Salām to the People of the Book and How to Respond to Them","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":33,"content":{"translation":{"en":["ʿĀ’ishah narrated: Some Jews came to the Prophet ﷺ and said: “Death be upon you, O Abū al-Qāsim.” He replied: “And upon you.” ʿĀ’ishah said: “Rather, upon you be death and disgrace.” The Messenger of Allah ﷺ said: “O ʿĀ’ishah, do not be obscene in speech.” She replied: “Did you not hear what they said?” He said: “Did I not return upon them what they said? I said: ‘And upon you.’” In another narration, ʿĀ’ishah understood what they meant and insulted them, so the Messenger of Allah ﷺ said: “Enough, O ʿĀ’ishah. Indeed, Allah does not love obscenity or deliberately obscene speech.” The narration adds that Allah, Mighty and Majestic, revealed: “And when they come to you, they greet you with that by which Allah has not greeted you…” [Sūrat al-Mujādilah 58:8] to the end of the verse."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2165: 11)."},{"num":14255,"demo":false,"sanad":"","matn":["عن أُسَامَةَ بن زَيْدٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَكِبَ حِمَارًا، عَلَيْهِ إِكَافٌ، تَحْتَهُ قَطِيفَةٌ فَدَكِيَّةٌ، وَأَرْدَفَ وَرَاءَهُ أُسَامَةَ بْنَ زَيْدٍ، وَهْوَ يَعُودُ سَعْدَ بْنَ عُبَادَةَ فِي بَنِي الْحَارِثِ بْنِ الْخَزْرَجِ، وَذَلِكَ قَبْلَ وَقْعَةِ بَدْرٍ، حَتَّى مَرَّ فِي مَجْلِسٍ فِيهِ أَخْلاَطٌ مِنَ الْمُسْلِمِينَ وَالْمُشْرِكِينَ عَبَدَةِ الأَوْثَانِ وَالْيَهُودِ، وَفِيهِمْ عَبْدُ اللَّهِ بْنُ أُبَىٍّ ابْنُ سَلُولَ، وَفِي الْمَجْلِسِ عَبْدُ اللَّهِ بْنُ رَوَاحَةَ، فَلَمَّا غَشِيَتِ الْمَجْلِسَ عَجَاجَةُ الدَّابَّةِ، خَمَّرَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ أَنْفَهُ بِرِدَائِهِ، ثُمَّ قَالَ: لاَ تُغَبِّرُوا عَلَيْنَا. فَسَلَّمَ عَلَيْهِمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ وَقَفَ، فَنَزَلَ، فَدَعَاهُمْ إِلَى اللَّهِ، وَقَرَأَ عَلَيْهِمُ الْقُرْآنَ، فَقَالَ عَبْدُ اللَّهِ بْنُ أُبَىٍّ ابْنُ سَلُولَ: أَيُّهَا الْمَرْءُ، لاَ أَحْسَنَ مِنْ هَذَا، إِنْ كَانَ مَا تَقُولُ حَقًّا، فَلاَ تُؤْذِنَا فِي مَجَالِسِنَا، وَارْجِعْ إِلَى رَحْلِكَ، فَمَنْ جَاءَكَ مِنَّا فَاقْصُصْ عَلَيْهِ. قَالَ ابْنُ رَوَاحَةَ: اغْشَنَا فِي مَجَالِسِنَا، فَإِنَّا نُحِبُّ ذَلِكَ. فَاسْتَبَّ الْمُسْلِمُونَ وَالْمُشْرِكُونَ وَالْيَهُودُ، حَتَّى هَمُّوا أَنْ يَتَوَاثَبُوا، فَلَمْ يَزَلِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُخَفِّضُهُمْ، ثُمَّ رَكِبَ دَابَّتَهُ حَتَّى دَخَلَ عَلَى سَعْدِ بْنِ عُبَادَةَ، فَقَالَ: أَىْ سَعْدُ، أَلَمْ تَسْمَعْ مَا قَالَ أَبُو حُبَابٍ. يُرِيدُ عَبْدَ اللَّهِ بْنَ أُبَىٍّ قَالَ كَذَا وَكَذَا قَالَ: اعْفُ عَنْهُ يَا رَسُولَ اللَّهِ وَاصْفَحْ، فَوَاللَّهِ لَقَدْ أَعْطَاكَ اللَّهُ الَّذِي أَعْطَاكَ، وَلَقَدِ اصْطَلَحَ أَهْلُ هَذِهِ الْبَحْرَةِ عَلَى أَنْ يُتَوِّجُوهُ، فَيُعَصِّبُونَهُ بِالْعِصَابَةِ، فَلَمَّا رَدَّ اللَّهُ ذَلِكَ بِالْحَقِّ الَّذِي أَعْطَاكَ شَرِقَ بِذَلِكَ، فَذَلِكَ فَعَلَ بِهِ مَا رَأَيْتَ، فَعَفَا عَنْهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6254)، ومسلم في الجهاد والسير (1798) كلاهما من طريق معمر، عن الزهري، عن عورة بن الزبير، أخبرني أسامة بن زيد فذكره.","grade":"متفق عليه","chapter_ar":"باب التسليم في مجلس فيه أخلاط من المسلمين والمشركين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6254) and Muslim (1798).","chapter_en":"Giving Salām to a Gathering Containing a Mixture of Muslims and Polytheists","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":34,"content":{"translation":{"en":["Usāmah ibn Zayd narrated: The Prophet ﷺ mounted a donkey which had a saddle upon it, beneath which was a Fadakī cloak. He seated Usāmah ibn Zayd behind him and went to visit Saʿd ibn ʿUbādah among Banū al-Ḥārith ibn al-Khazraj. This was before the Battle of Badr. He passed by a gathering containing a mixture of Muslims, polytheists who worshipped idols, and Jews. Among them was ʿAbdullāh ibn Ubayy ibn Salūl, and ʿAbdullāh ibn Rawāḥah was also in the gathering. When the dust raised by the animal reached the gathering, ʿAbdullāh ibn Ubayy covered his nose with his cloak and said: “Do not cover us with dust.” The Prophet ﷺ gave them salām, then stopped and dismounted. He called them to Allah and recited the Qur’an to them. ʿAbdullāh ibn Ubayy ibn Salūl said: “O man, there is nothing better than this if what you say is true, but do not disturb us with it in our gatherings. Return to your own place, and whoever comes to you from among us, tell it to him.” ʿAbdullāh ibn Rawāḥah said: “Rather, come to us in our gatherings, for we love that.” The Muslims, polytheists, and Jews then began insulting one another until they nearly came to blows. The Prophet ﷺ continued calming them until they settled down. Then he mounted his animal and went to Saʿd ibn ʿUbādah. He said: “O Saʿd, did you not hear what Abū Ḥubāb said?” meaning ʿAbdullāh ibn Ubayy. He then told him what he had said. Saʿd replied: “Pardon him, O Messenger of Allah, and overlook it. By Allah, Allah has given you what He has given you. The people of this settlement had agreed to crown him and bind the royal turban upon him. But when Allah prevented that through the truth He gave you, he choked with resentment over it. That is what caused him to behave as you saw.” So the Prophet ﷺ pardoned him."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6254)، ومسلم (1798)."},{"num":14256,"demo":false,"sanad":"","matn":["عَنْ قَتَادَةَ، قَالَ: قُلْتُ لأَنَسٍ: أَكَانَتِ الْمُصَافَحَةُ فِي أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نَعَمْ."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6263) عن عمرو بن عاصم، حدثنا همام، عن قتادة فذكره.","grade":"صحيح","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6263).","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Qatādah narrated: I asked Anas: “Was handshaking practiced among the Companions of the Prophet ﷺ?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6263)."},{"num":14257,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَتَاكُمْ أَهْلُ الْيَمَنِ، وَهُمْ أَرَقُّ قُلُوبًا مِنْكُمْ، وَهُمْ أَوَّلُ مَنْ جَاءَ بِالْمُصَافَحَةِ."],"takhrij":"صحيح: رواه أبو داود (5213)، وأحمد (13212)، والبخاري في الأدب المفرد (967) كلهم من طرق عن حماد بن سلمة، عن حميد، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5213), Aḥmad (13212), and al-Bukhārī in al-Adab al-Mufrad (967).","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “The people of Yemen have come to you. Their hearts are softer than yours.” And they were the first to introduce handshaking."]},"buhuth":{"en":["The statement:","“They were the first to introduce handshaking”","is from Anas himself, as is explicitly stated in Aḥmad (13624), from ʿAffān, who said: Ḥammād ibn Salamah narrated to us, saying: Ḥumayd informed us, from Anas, who said:","When the people of Yemen approached, the Messenger of Allah ﷺ said:","“The people of Yemen have come to you; their hearts are softer than yours.”","Anas then said:","“They were the first to introduce handshaking.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5213)، وأحمد (13212)، والبخاري في الأدب المفرد (967)."},{"num":14258,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقْدَمُ عَلَيْكُمْ غَدًا أَقْوَامٌ هُمْ أَرَقُّ قُلُوبًا لِلْإِسْلَامِ مِنْكُمْ. قَالَ: فَقَدِمَ الْأَشْعَرِيُّونَ فِيهِمْ أَبُو مُوسَى الْأَشْعَرِيُّ، فَلَمَّا دَنَوْا مِنَ الْمَدِينَةِ جَعَلُوا يَرْتَجِزُونَ، يَقُولُونَ: [البحر الرجز] غَدًا نَلْقَى الْأَحِبَّهْ... مُحَمَّدًا وَحِزْبَهْ، فَلَمَّا أَنْ قَدِمُوا تَصَافَحُوا، فَكَانُوا هُمْ أَوَّلَ مَنْ أَحْدَثَ الْمُصَافَحَةَ."],"takhrij":"صحيح: رواه أحمد (12582)، وصحّحه ابن حبان (7193) كلاهما من طريق يحيى بن أيوب، عن حميد الطويل قال: سمعت أنس بن مالك يقول: فذكره.","grade":"صحيح","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12582) and authenticated by Ibn Ḥibbān (7193).","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Tomorrow, people will come to you whose hearts are softer toward Islam than yours.” Then the Ashʿarīs arrived, among them Abū Mūsā al-Ashʿarī. As they drew near to Madinah, they began chanting: “Tomorrow we shall meet the beloved ones— Muḥammad and his party.” When they arrived, they shook hands with one another, and they were the first to establish the practice of handshaking."]},"buhuth":{"en":["Anas also said:","“When the Companions of the Prophet ﷺ met one another, they would shake hands, and when they returned from a journey, they would embrace one another.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (12582)، وصححه ابن حبان (7193)."},{"num":14259,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنْ مُسْلِمَيْنِ يَلْتَقِيَانِ، فَيَتَصَافَحَانِ إِلاَّ غُفِرَ لَهُمَا قَبْلَ أَنْ يَفْتَرِقَا."],"takhrij":"حسن: رواه أبو داود (5212)، والترمذي (2727)، وابن ماجه (3703)، وأحمد (18547) كلهم من طريق الأجلح، عن أبي إسحاق، عن البراء بن عازب فذكره.","grade":"حسن","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (5212), al-Tirmidhī (2727), Ibn Mājah (3703), and Aḥmad (18547).","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated that the Messenger of Allah ﷺ said: “No two Muslims meet and shake hands except that they are forgiven before they part.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (5212)، والترمذي (2727)، وابن ماجه (3703)، وأحمد (18547)."},{"num":14260,"demo":false,"sanad":"","matn":["عَنْ أُمَيْمَةَ بِنْتِ رُقَيْقَةَ، أَنَّهَا قَالَتْ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي نِسْوَةٍ بَايَعْنَهُ عَلَى الإِسْلاَمِ فَقُلْنَ: يَا رَسُولَ اللَّهِ نُبَايِعُكَ عَلَى أَنْ لاَ نُشْرِكَ بِاللَّهِ شَيْئًا، وَلاَ نَسْرِقَ، وَلاَ نَزْنِيَ، وَلاَ نَقْتُلَ أَوْلاَدَنَا، وَلاَ نَأْتِيَ بِبُهْتَانٍ نَفْتَرِيهِ بَيْنَ أَيْدِينَا وَأَرْجُلِنَا، وَلاَ نَعْصِيَكَ فِي مَعْرُوفٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِيمَا اسْتَطَعْتُنَّ وَأَطَقْتُنَّ. قَالَتْ: فَقُلْنَ: اللَّهُ وَرَسُولُهُ أَرْحَمُ بِنَا مِنْ أَنْفُسِنَا، هَلُمَّ نُبَايِعْكَ يَا رَسُولَ اللَّهِ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنِّي لاَ أُصَافِحُ النِّسَاءَ، إِنَّمَا قَوْلِي لِمِائَةِ امْرَأَةٍ كَقَوْلِي لاِمْرَأَةٍ وَاحِدَةٍ أَوْ مِثْلِ قَوْلِي لاِمْرَأَةٍ وَاحِدَةٍ."],"takhrij":"صحيح: رواه مالك في البيعة (2) عن محمد بن المنكدر، عن أميمة بنت رقيقة فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Bayʿah (2), al-Tirmidhī (1597), al-Nasā’ī (4181), and Ibn Mājah (2874).","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Umaymah bint Ruqayqah narrated: I came to the Messenger of Allah ﷺ among a group of women who pledged allegiance to him upon Islam. They said: “O Messenger of Allah, we pledge allegiance to you that we will not associate anything with Allah, we will not steal, we will not commit zinā, we will not kill our children, we will not fabricate a false accusation between our hands and feet, and we will not disobey you in what is right.” The Messenger of Allah ﷺ said: “According to what you are able and capable of.” She said: We replied: “Allah and His Messenger are more merciful to us than we are to ourselves. Come, O Messenger of Allah, let us pledge allegiance to you by hand.” The Messenger of Allah ﷺ said: “I do not shake hands with women. My statement to one hundred women is the same as my statement to one woman—or like my statement to a single woman.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7649],"tks":"صحيح: رواه مالك (2)، ورواه الترمذي (1597)، والنسائي (4181)، وابن ماجه (2874)."},{"num":14261,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ يَزِيدَ قَالَتْ: دَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  النِّسَاءَ الْمُؤْمِنِينَ إِلَى الْبَيْعَةِ، فَقَالَتْ أَسْمَاءُ: يَا رَسُولَ اللَّهِ، أَلَا تَحْسِرُ لَنَا عَنْ يَدِكَ؟ فَقَالَ إِنِّي لَا أُصَافِحُ النِّسَاءَ."],"takhrij":"حسن: رواه إسحاق بن راهويه كما في المطالب (2109) –واللفظ له- وأحمد مختصرا (27594) من طريقين عن عبد الحميد بن بهرام، عن شهر بن حوشب، عن أسماء بنت يزيد فذكرته.","grade":"حسن","chapter_ar":"باب المصافحة والمعانقة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Isḥāq ibn Rāhwayh, as cited in al-Maṭālib (2109), and this is his wording.","chapter_en":"Handshaking and Embracing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":35,"content":{"translation":{"en":["Asmāʾ bint Yazīd narrated: The Messenger of Allah ﷺ called the believing women to pledge allegiance. Asmāʾ said: “O Messenger of Allah, will you not extend your hand to us?” He replied: “I do not shake hands with women.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7652],"tks":"حسن: رواه إسحاق بن راهويه كما في المطالب (2109) - واللفظ له."},{"num":14262,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن هِشَامٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَهْوَ آخذٌ بِيَدِ عُمَرَ بْنِ الْخَطَّابِ."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6264) عن يحيى بن سليمان، قال: حدثني ابنُ وهب، قال: أخبرني حيوة قال: حدثني أبو عقيل زهرة بن معبد، سمع جدّه عبد الله بن هشام فذكره.","grade":"صحيح","chapter_ar":"باب المصافحة باليد الواحدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in al-Istiʾdhān (6264).","chapter_en":"Shaking Hands with One Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":36,"content":{"translation":{"en":["ʿAbdullāh ibn Hishām narrated: “We were with the Prophet ﷺ while he was holding the hand of ʿUmar ibn al-Khaṭṭāb.”"]}},"tuhfa":{},"full":1,"rep":[14789],"tks":"صحيح: رواه البخاري (6264)."},{"num":14263,"demo":false,"sanad":"","matn":["عن حذيفة بن اليمان أن رسول الله صلى الله عليه وسلم لقيه، فقال: يا حذيفة، نَاوِلْنِيْ يدَك فقبض يده، ثم الثانية، ثم الثالثة فقال: ما يمنعك؟ فقال: إني جنب، فقال: إن المؤمن إذا لقي المؤمن فأخذ بيدِه تحاتت خطاياه كما تحات ورق الشجر."],"takhrij":"حسن: رواه ابن وهب في الجامع (250) فقال: وأخبرني ابن لهيعة، عن الوليد بن أبي الوليد، عن العلاء بن عبد الرحمن، عن أبيه، أنه سمع حذيفة بن اليمان يذكر فذكر الحديث.","grade":"حسن","chapter_ar":"باب المصافحة باليد الواحدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Wahb in al-Jāmiʿ (250).","chapter_en":"Shaking Hands with One Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":36,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān narrated: The Messenger of Allah ﷺ met him and said: “O Ḥudhayfah, give me your hand.” Ḥudhayfah withheld his hand. The Prophet ﷺ asked him a second time, then a third time, and said: “What is preventing you?” Ḥudhayfah replied: “I am in a state of janābah.” The Prophet ﷺ said: “When a believer meets another believer and takes him by the hand, their sins fall away just as the leaves of a tree fall away.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن وهب في الجامع (250)."},{"num":14264,"demo":false,"sanad":"","matn":["عن سَلْمَانَ الفارسي، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْمُسْلِمَ إِذَا لَقِيَ أَخَاهُ الْمُسْلِمَ فَأَخَذَ بِيَدِهِ، تَحَاتَّتْ عَنْهُمَا ذُنُوبُهُمَا، كَمَا يَتَحَاتُّ الْوَرَقُ عَنِ الشَّجَرَةِ الْيَابِسَةِ فِي يَوْمِ رِيحٍ عَاصِفٍ، وَإِلَّا غُفِرَ لَهُمَا، وَلَوْ كَانَتْ ذُنُوبُهُمَا مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"حسن: رواه الطبراني في الكبير (6150)، والبيهقي في الشعب (8549) كلاهما من طريق عبيد الله بن عمر القواريري ثنا سالم بن غيلان قال: سمعت جعدا أبا عثمان يقول: حدثني أبو عثمان النهدي عن سلمان الفارسي فذكره.","grade":"حسن","chapter_ar":"باب المصافحة باليد الواحدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (6/315) and al-Bayhaqī in Shuʿab al-Īmān (8549).","chapter_en":"Shaking Hands with One Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":36,"content":{"translation":{"en":["Salmān al-Fārisī narrated that the Prophet ﷺ said: “When a Muslim meets his Muslim brother and takes him by the hand, their sins fall away from them just as leaves fall from a dry tree on a day of strong wind; otherwise, they are forgiven even if their sins are like the foam of the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (6150)، والبيهقي في الشعب (8549)."},{"num":14265,"demo":false,"sanad":"","matn":["عن أنس بن مالك، عَنْ النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَا مِنْ مُسْلِمَيْنِ الْتَقَيَا، فَأَخَذَ أَحَدُهُمَا بِيَدِ صَاحِبِهِ، إِلَّا كَانَ حَقًّا عَلَى الله أَنْ يُجيبَ دُعَاءَهُمَا، وَلَا يَرُدَّ أَيْدِيَهُمَا حَتَّى يَغْفِرَ لهُمَا."],"takhrij":"حسن: رواه البزار (6463)، وأبو يعلى (4139) كلاهما من طريق يوسف بن يعقوب الضبعي السدوسي، حدثنا ميمون بن عجلان، عن ميمون بن سياه، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب المصافحة باليد الواحدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (6463) and Abū Yaʿlā (4139).","chapter_en":"Shaking Hands with One Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":36,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ said: “No two Muslims meet and one takes the hand of the other except that it becomes a right upon Allah to answer their supplication, and He does not let their hands separate until He has forgiven them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار (6463)، وأبو يعلى (4139)."},{"num":14266,"demo":false,"sanad":"","matn":["عن ابْنِ مَسْعُودٍ يَقُولُ عَلَّمَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَفِّي بَيْنَ كَفَّيْهِ التَّشَهُّدَ، كَمَا يُعَلِّمُنِي السُّورَةَ مِنَ الْقُرْآنِ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6265)، ومسلم في الصلاة (402: 59) كلاهما من حديث أبي نعيم، حدثنا سيف بن سليمان قال: سمعتُ مجاهدًا يقول: حدثني عبد الله بن سخبرة قال: سمعت ابن مسعود يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب المصافحة باليدين أحيانًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6265) and Muslim (402:59).","chapter_en":"Shaking Hands with Both Hands on Occasion","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":37,"content":{"translation":{"en":["Ibn Masʿūd narrated: “The Messenger of Allah ﷺ taught me the tashahhud while my hand was between his two hands, just as he would teach me a sūrah from the Qur’an.”"]},"buhuth":{"en":["Al-Bukhārī also mentioned in suspended form:","“Ḥammād ibn Zayd shook hands with ʿAbdullāh ibn al-Mubārak using both of his hands.”","Al-Bukhārī, may Allah have mercy on him, first entitled a chapter “Handshaking”, and included in it the hadith of Ibn Masʿūd:","“while my hand was between his two hands,”","as well as the hadith concerning ʿUmar ibn al-Khaṭṭāb:","“while he was holding the hand of ʿUmar ibn al-Khaṭṭāb.”","Then he entitled another chapter “Taking with Both Hands”, in which he cited the report of Ḥammād ibn Zayd and the hadith of ʿAbdullāh ibn Masʿūd to demonstrate permissibility.","However, shaking hands with both hands was not the regular Sunnah of the Prophet ﷺ and his Companions, though there is no harm in doing it occasionally to demonstrate its permissibility."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6265)، ومسلم (402: 59)."},{"num":14267,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا وَدَّعَ رَجُلاً أَخَذَ بِيَدِهِ فَلاَ يَدَعُهَا حَتَّى يَكُونَ الرَّجُلُ هُوَ يَدَعُ يَدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيَقُولُ: أَسْتَوْدِعُ اللَّهَ دِينَكَ، وَأَمَانَتَكَ، وَآخِرَ عَمَلِكَ."],"takhrij":"حسن: رواه الترمذي (3442، 3443)، وأبو داود (2600)، وابن ماجه (2826)، وصحّحه ابن خزيمة (2531)، وابن حبان (2693)، والحاكم (1/442) كلهم من طرق عن ابن عمر إلا أن بعض الطرق فيها مقال، ولكن يقوّي بعضه بعضا كما أن بعضهم اقتصر على دعاء التوديع فقط.","grade":"حسن","chapter_ar":"باب من الأدب ألا يترك الرجل يد رجل حتى يتركها الآخر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3442, 3443), Abū Dāwūd (2600), Ibn Mājah (2826), and authenticated by Ibn Khuzaymah (2531).","chapter_en":"From Good Manners Is That a Man Not Release Another’s Hand Until the Other Releases It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":38,"content":{"translation":{"en":["Ibn ʿUmar narrated: When the Messenger of Allah ﷺ bid farewell to a man, he would take his hand and would not release it until the man himself released the hand of the Prophet ﷺ. He would say: “I entrust to Allah your religion, your trust, and the conclusion of your deeds.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه الترمذي (3442، 3443)، وأبو داود (2600)، وابن ماجه (2826)، وصححه ابن خزيمة (2531)."},{"num":14268,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَكُنْ أَحَدٌ يَأْخُذُ بِيَدِهِ فَيَنْزِعُ يَدَهُ مِنْ يَدِهِ حَتَّى يَكُونَ الرَّجُلُ هُوَ الَّذِي يُرْسِلُهُ وَلَمْ يَكُنْ تَرَى ركبتاه، أَوْ ركيته خارجة عَنْ رُكْبَةِ جليس وَلَمْ يَكُنْ أَحَدٌ يُصَافِحْهُ إِلا أَقْبَلَ عَلَيْهِ بِوَجْهِهِ، ثُمَّ لَمْ يُصْرِفْهُ عَنْهُ حَتَّى يَفْرُغَ مِنْ كَلامِهِ."],"takhrij":"حسن: رواه البزار في مسنده (8548)، والطبراني في الأوسط (8688) كلاهما من طريق عبد الله بن صالح، حدثنا الليث (هو ابن سعد)، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب من الأدب ألا يترك الرجل يد رجل حتى يتركها الآخر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in his Musnad (8548) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (8688).","chapter_en":"From Good Manners Is That a Man Not Release Another’s Hand Until the Other Releases It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":38,"content":{"translation":{"en":["Abū Hurayrah narrated: No one would take the hand of the Messenger of Allah ﷺ and have the Prophet ﷺ pull his hand away first; rather, the other man would be the one to release it. Nor would his knees—or his knee—be seen protruding beyond the knees of the person sitting beside him. Whenever someone shook his hand, he would turn his face fully toward him and would not turn away until the man had finished speaking."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البزار في مسنده (8548)، والطبراني في الأوسط (8688)."},{"num":14269,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ: مَا رَأَيْتُ رَجُلاً الْتَقَمَ أُذُنَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَيُنَحِّي رَأْسَهُ، حَتَّى يَكُونَ الرَّجُلُ هُوَ الَّذِي يُنَحِّي رَأْسَهُ، وَمَا رَأَيْتُ رَجُلاً أَخَذَ بِيَدِهِ فَتَرَكَ يَدَهُ، حَتَّى يَكُونَ الرَّجُلُ هُوَ الَّذِي يَدَعُ يَدَهُ."],"takhrij":"حسن: رواه أبو داود (4794)، والترمذي (2490)، وابن ماجه (3716)، وابن حبان (6435) كلهم من طرقٍ عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب من الأدب ألا يترك الرجل يد رجل حتى يتركها الآخر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4794), al-Tirmidhī (2490), Ibn Mājah (3716), and Ibn Ḥibbān (6435).","chapter_en":"From Good Manners Is That a Man Not Release Another’s Hand Until the Other Releases It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":38,"content":{"translation":{"en":["Anas ibn Mālik narrated: “I never saw a man place his mouth close to the ear of the Messenger of Allah ﷺ to speak privately with him and have the Prophet ﷺ move his head away first; rather, the man himself would be the one to move away. And I never saw a man take his hand and have the Prophet ﷺ release it first; rather, the man himself would be the one to let go.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4794)، والترمذي (2490)، وابن ماجه (3716)، وابن حبان (6435)."},{"num":14270,"demo":false,"sanad":"","matn":["عن الْبَرَاءِ بْنِ عَازِبٍ قَالَ: فَدَخَلْتُ مَعَ أَبِي بَكْرٍ عَلَى أَهْلِهِ، فَإِذَا عَائِشَةُ ابْنَتُهُ مُضْطَجِعَةٌ، قَدْ أَصَابَتْهَا حُمَّى، فَرَأَيْتُ أَبَاهَا، فَقَبَّلَ خَدَّهَا، وَقَالَ: كَيْفَ أَنْتِ يَا بُنَيَّةُ."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3918) عن أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق قال: سمعت البراء يحدث فذكره في آخر حديث طويل.","grade":"صحيح","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3918).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated: I entered with Abū Bakr upon his family and found his daughter ʿĀ’ishah lying down with a fever. I saw her father kiss her cheek and say: “How are you, my daughter?”"]},"buhuth":{"en":["Abū Dāwūd (5222) narrated a similar report, adding:","“I entered with Abū Bakr when he had first arrived in Madinah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3918)."},{"num":14271,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قبّلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْحَسَنَ بْنَ عَلِيٍّ، وَعِنْدَهُ الأَقْرَعُ بْنُ حَابِسٍ التَّمِيمِيُّ جَالِسًا، فَقَالَ الأَقْرَعُ: إِنَّ لِي عَشَرَةً مِنَ الْوَلَدِ مَا قبّلتُ مِنْهُمْ أَحَدًا، فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: مَنْ لاَ يَرْحَمُ لاَ يُرحَم."],"takhrij":"متفق عليه: رواه البخاري في الأدب (5997)، ومسلم في الفضائل (2318) كلاهما من طريق الزهري، حدثنا أبو سلمة بن عبد الرحمن، عن أبي هريرة فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5997) and Muslim (2318). The wording is that of al-Bukhārī.","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ kissed al-Ḥasan ibn ʿAlī while al-Aqraʿ ibn Ḥābis al-Tamīmī was sitting with him. Al-Aqraʿ said: “I have ten children and I have never kissed any of them.” The Messenger of Allah ﷺ looked at him and said: “Whoever does not show mercy will not be shown mercy.”"]}},"tuhfa":{},"full":1,"rep":[9504,13915,14086],"tks":"متفق عليه: رواه البخاري (5997)، ومسلم (2318)، واللفظ للبخاري."},{"num":14272,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَدِمَ نَاسٌ مِنَ الأَعْرَابِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فَقَالُوا: أَتُقَبِّلُونَ صِبْيَانَكُمْ؟ فَقَالُوا: نَعَمْ. فَقَالُوا: لَكِنَّا وَاللَّهِ مَا نُقَبِّلُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  وَأَمْلِكُ إِنْ كَانَ اللَّهُ نَزَعَ مِنْكُمُ الرَّحْمَةَ. وَقَالَ ابْنُ نُمَيْرٍ مِنْ قَلْبِكَ الرَّحْمَةَ."],"takhrij":"متفق عليه: رواه البخاري في الأدب (5998)، ومسلم في الفضائل (2317) كلاهما من طريق هشام بن عروة، عن أبيه عروة، عن عائشة فذكرته. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in al-Adab (5998) and Muslim in al-Faḍāʾil (2317).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["ʿĀ’ishah narrated: Some Bedouins came to the Messenger of Allah ﷺ and asked: “Do you kiss your children?” They replied: “Yes.” The Bedouins said: “By Allah, we do not kiss ours.” The Messenger of Allah ﷺ said: “What can I do if Allah has removed mercy from you?” In another wording: “…removed mercy from your heart?”"]}},"tuhfa":{},"full":1,"rep":[14087],"tks":"متفق عليه: رواه البخاري (5998)، ومسلم (2317)."},{"num":14273,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، أَنَّ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: ثُمَّ قَالَ تَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَبْشِرِي يَا عَائِشَةُ فَإِنَّ اللَّهَ قَدْ أَنْزَلَ عُذْرَكِ. وَقَرَأَ عَلَيْهَا الْقُرْآنَ، فَقَالَ أَبَوَاىَ: قُومِي فَقَبِّلِي رَأْسَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. فَقَالَتْ أَحْمَدُ اللَّهَ لاَ إِيَّاكُمَا."],"takhrij":"صحيح: رواه أبو داود (5219) –ومن طريقه البيهقي (13579)- عن موسى بن إسماعيل، حدثنا حماد (هو ابن سلمة)، أخبرنا هشام بن عروة، عن عروة، أن عائشة، قالت: فذكرته. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5219), and through his route by al-Bayhaqī (7/101).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["ʿĀ’ishah narrated: Then he—meaning the Prophet ﷺ—said: “Rejoice, O ʿĀ’ishah, for Allah has revealed your vindication.” He then recited the Qur’an to her. Her parents said: “Get up and kiss the head of the Messenger of Allah ﷺ.” She replied: “I praise Allah, Mighty and Majestic, not the two of you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (5219)، ومن طريقه البيهقي (13579)."},{"num":14274,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ، قَالَتْ: مَا رَأَيْتُ أَحَدًا أَشْبَهَ سَمْتًا، وَدَلاًّ، وَهَدْيًا بِرَسُولِ اللَّهِ فِي قِيَامِهَا وَقُعُودِهَا مِنْ فَاطِمَةَ بِنْتِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَتْ: وَكَانَتْ إِذَا دَخَلَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ إِلَيْهَا فَقَبَّلَهَا، وَأَجْلَسَهَا فِي مَجْلِسِهِ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ عَلَيْهَا قَامَتْ مِنْ مَجْلِسِهَا فَقَبَّلَتْهُ وَأَجْلَسَتْهُ فِي مَجْلِسِهَا.. فَلَمَّا."],"takhrij":"صحيح: رواه الترمذي (3872)، وابن المقرئ في الرخصة في تقبيل اليد (26)، والحاكم (7715) كلهم من طريق إسرائيل، أخبرنا ميسرة بن حبيب، أخبرني المنهال بن عمرو، حدثتني عائشة بنت طلحة، عن عائشة أم المؤمنين فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3872), Ibn al-Muqriʾ in al-Rukhṣah fī Taqbīl al-Yad (26), and al-Ḥākim (7715).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["ʿĀ’ishah, the Mother of the Believers, narrated: “I never saw anyone more closely resemble the Messenger of Allah ﷺ in demeanor, manner, and conduct—in her standing and sitting—than Fāṭimah, the daughter of the Messenger of Allah ﷺ.” She said: When Fāṭimah entered upon the Prophet ﷺ, he would stand up for her, kiss her, and seat her in his own place. And when the Prophet ﷺ entered upon her, she would stand from her place, kiss him, and seat him in her own place… to the end of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3872)، وابن المقرئ في الرخصة في تقبيل اليد (26)، والحاكم (7715)."},{"num":14275,"demo":false,"sanad":"","matn":["عن أسامة بن شريك قال: قمنا إلى رسول الله صلى الله عليه وسلم فقبّلنا يده."],"takhrij":"حسن: رواه المحاملي في أماليه (247)، وأبوبكر بن المقرئ في الرخصة في تقبيل اليد (2)، والخطيب في الجامع لأخلاق الراوي (314) كلهم من طريق محمد أبي هشام الرفاعي، حدثنا سعيد بن عامر، حدثنا شعبة، عن زياد بن علاقة، عن أسامة بن شريك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Maḥāmilī in his Amālī (247), Abū Bakr ibn al-Muqriʾ in al-Rukhṣah fī Taqbīl al-Yad (2), and al-Khaṭīb in al-Jāmiʿ li-Akhlāq al-Rāwī (314).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["Usāmah ibn Sharīk narrated: “We stood up to meet the Messenger of Allah ﷺ and kissed his hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه المحاملي في أماليه (247)، وأبو بكر بن المقرئ في الرخصة في تقبيل اليد (2)، والخطيب في الجامع لأخلاق الراوي (314)."},{"num":14276,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى، عَنْ أَبِيهِ قَالَ: كَانَ أُسَيْدُ بْنُ حُضَيْرٍ رَجُلًا صَالِحًا ضَاحِكًا مَلِيحًا، فَبَيْنَمَا هُوَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُحَدِّثُ الْقَوْمَ، وَيُضْحِكُهُمْ، فَطَعَنَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي خَاصِرَتِهِ، فَقَالَ: أَوْجَعَتْنِي؟ قَالَ: اقْتَصَّ قَالَ: يَا رَسُولَ اللَّهِ إِنَّ عَلَيْكَ قَمِيصًا، وَلَمْ يَكُنْ عَلَيَّ قَمِيصٌ، قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَمِيصَهُ، فَاحْتَضَنَهُ، ثُمَّ جَعَلَ يُقَبِّلُ كَشْحَهُ، فَقَالَ: بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ أَرَدْتُ هَذَا."],"takhrij":"حسن: رواه الحاكم (5262) –وعنه البيهقي (16021)- عن عبد الله بن محمد الصيدلاني، ثنا محمد بن أيوب، أنا يحيى بن المغيرة السعدي، ثنا جرير (هو ابن عبدالحميد)، عن حصين، عن عبد الرحمن بن أبي ليلى، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (5262), and from him by al-Bayhaqī (8/49).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Laylā narrated from his father: Usayd ibn Ḥuḍayr was a righteous, cheerful, pleasant man. While he was with the Messenger of Allah ﷺ speaking to the people and making them laugh, the Messenger of Allah ﷺ poked him in the side. Usayd said: “You hurt me.” The Prophet ﷺ said: “Take your retaliation.” Usayd said: “O Messenger of Allah, you are wearing a shirt, while I was not wearing one.” So the Messenger of Allah ﷺ lifted his shirt. Usayd embraced him and began kissing his side. He said: “May my father and mother be sacrificed for you, O Messenger of Allah. This is what I wanted.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الحاكم (5262)، وعنه البيهقي (16021)."},{"num":14277,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ وهب بْنِ عَبْدِ اللَّهِ السوائي قَالَ: لَمَّا قَدِمَ جَعْفَرُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ أَرْضِ الْحَبَشَةِ قبّلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا بَيْنَ عَيْنَيْهِ، ثُمَّ قَالَ: مَا أَدْرِي أَنَا بِقُدُومِ جَعْفَرٍ أسرُّ أَوْ بِفَتْحِ خَيْبَرَ."],"takhrij":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (364)، والطبراني في الكبير (22/ح 244) كلاهما من حديث مخلد بن يزيد، حدثنا مسعر، عن عون بن أبي جحيفة، عن أبيه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī ʿĀṣim in al-Āḥād wa-al-Mathānī (364) and al-Ṭabarānī in al-Muʿjam al-Kabīr (22/100).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["Abū Juḥayfah Wahb ibn ʿAbdullāh al-Suwāʾī narrated: When Jaʿfar returned to the Messenger of Allah ﷺ from Abyssinia, the Messenger of Allah ﷺ kissed him between the eyes and then said: “I do not know which makes me happier: the arrival of Jaʿfar or the conquest of Khaybar.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي عاصم في الآحاد والمثاني (364)، والطبراني في الكبير (22/ح 244)."},{"num":14278,"demo":false,"sanad":"","matn":["عَبْدُ الرَّحْمَنِ بْنُ رَزِينٍ قَالَ: مَرَرْنَا بِالرَّبَذَةِ، فَقِيلَ لَنَا: هَا هُنَا سَلَمَةُ بْنُ الأَكْوَعِ، فَأَتَيْنَاهُ فَسَلَّمْنَا عَلَيْهِ، فَأَخْرَجَ يَدَيْهِ، فَقَالَ: بَايَعْتُ بِهَاتَيْنِ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَخْرَجَ كَفًّا لَهُ ضَخْمَةً، كَأَنَّهَا كَفُّ بَعِيرٍ، فَقُمْنَا إِلَيْهَا، فَقَبَّلْنَاهَا."],"takhrij":"حسن: رواه الإمام أحمد (16551)، والبخاري في الأدب المفرد (973) كلاهما من طريق عطّاف بن خالد، حدثني عبد الرحمن بن رزين قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في التقبيل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (16551) and al-Bukhārī in al-Adab al-Mufrad (973).","chapter_en":"What Has Been Narrated Concerning Kissing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":39,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Razīn narrated: We passed through al-Rabadhah and were told: “Salamah ibn al-Akwaʿ is here.” So we went to him and gave him salām. He extended his two hands and said: “With these two hands I pledged allegiance to the Prophet of Allah ﷺ.” He had a large palm, as though it were the palm of a camel. So we rose toward it and kissed it."]},"buhuth":{"en":["Benefit","The hadiths of this chapter indicate the permissibility of kissing the head of one’s parents, as well as an elderly person or someone distinguished by knowledge and honor.","Likewise, they indicate the permissibility of kissing the hand, cheek, side of the body, and between the eyes. All of these practices are reported from many of the early generations.","Among these reports is that of Tamīm ibn Salamah, who said:","When ʿUmar ibn al-Khaṭṭāb arrived in al-Shām, Abū ʿUbaydah ibn al-Jarrāḥ went out to meet him and kissed his hand. Then the two withdrew together and wept.","Tamīm used to say:","“Kissing the hand is a Sunnah.”","Narrated by Ibn Wahb in al-Jāmiʿ (172) and ʿAbd al-Razzāq in his Amālī (118), with an authentic chain.","Another example is what Ibn al-Muqriʾ narrated with a good chain in al-Rukhṣah fī Taqbīl al-Yad (17), from Mūsā ibn Dāwūd, who said:","“I was with Sufyān ibn ʿUyaynah when Ḥusayn al-Juʿfī arrived. Ibn ʿUyaynah stood up and kissed his hand.”","Ḥusayn al-Juʿfī was al-Ḥusayn ibn ʿAlī ibn al-Walīd al-Juʿfī al-Kūfī, the Qur’an reciter.","He was born in 119 AH and died in 203 AH.","Ibn ʿUyaynah narrated from him even though Ibn ʿUyaynah was older than him; Ibn ʿUyaynah was born in 107 AH and died in 198 AH.","He greatly admired al-Juʿfī because of his righteousness and taqwā.","Aḥmad ibn Ḥanbal said:","“I have not seen anyone more virtuous than Ḥusayn al-Juʿfī and Saʿīd ibn ʿĀmir.”","Yaḥyā ibn Yaḥyā al-Naysābūrī said:","“If any of the abdāl still remains, then it is Ḥusayn al-Juʿfī.”","Whenever Sufyān al-Thawrī saw him, he would embrace him and say:","“This is the monk of Juʿfī.”","Al-Nawawī said:","“It is recommended to kiss the hand of a righteous man, an ascetic, a scholar, and others like them from among the people devoted to the Hereafter. As for kissing a person’s hand because of his wealth, worldly status, power, or prestige among worldly people, and the like, that is severely disliked.”","Al-Majmūʿ (4/636).","The scholars disliked kissing the hand of a person who deliberately presents his hand to be kissed, as is done by superstitious people who seek to have others magnify them.","As for kissing the foot, no authentic report establishing it has been proven here."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16551)، والبخاري في الأدب المفرد (973)."},{"num":14279,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ، أنّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَجْمَعُ بَيْنَ الرَّجُلَيْنِ مِنْ قَتْلَى أُحُدٍ - يَعْنِي فِي الْقَبْرِ - ثُمَّ يَقُولُ: أيّهما أَكْثَرُ أَخْذًا لِلْقُرْآنِ؟ فَإِذَا أُشِيرَ إِلَى أَحَدِهِمَا قَدَّمَهُ فِي اللَّحْدِ."],"takhrij":"صحيح: رواه البخاريّ في الجنائز (1343) عن عبدالله بن يوسف، حدثنا الليث، حدثني ابن شهاب، عن عبدالرحمن بن كعب بن مالك، عن جابر بن عبدالله، فذكره.","grade":"صحيح","chapter_ar":"باب إنزال الناس منازلهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1343).","chapter_en":"Giving People Their Proper Rank and Status","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":40,"content":{"translation":{"en":["Jābir narrated: The Prophet ﷺ would place two of those martyred at Uḥud together in one grave, then ask: “Which of these two had taken in more of the Qur’an?” When one of them was pointed out, he would place him first in the burial niche."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1343)."},{"num":14280,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأَشْعَرِيِّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ مِنْ إِجْلاَلِ اللَّهِ إِكْرَامَ ذِي الشَّيْبَةِ الْمُسْلِمِ، وَحَامِلِ الْقُرْآنِ غَيْرِ الْغَالِي فِيهِ وَالْجَافِي عَنْهُ، وَإِكْرَامَ ذِي السُّلْطَانِ الْمُقْسِطِ."],"takhrij":"حسن: رواه أبو داود (4843) عن إسحاق بن إبراهيم الصواف، عن","grade":"حسن","chapter_ar":"باب إنزال الناس منازلهم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4843).","chapter_en":"Giving People Their Proper Rank and Status","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":40,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated that the Messenger of Allah ﷺ said: “Indeed, part of honoring Allah is honoring an elderly Muslim, honoring a bearer of the Qur’an who neither goes to excess concerning it nor neglects it, and honoring a just ruler.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[1227,13932],"tks":"حسن: رواه أبو داود (4843)."},{"num":14281,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ لَمَّا قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَرْحَبًا بِالْوَفْدِ الَّذِينَ جَاءُوا غَيْرَ خَزَايَا وَلاَ نَدَامَى."],"takhrij":"متفق عليه: رواه البخاري في الأدب (6176)، ومسلم في الإيمان (17: 24) كلاهما من طريق أبي جمرة، عن ابن عباس فذكره. واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب الترحيب بالضيف والزائر والوافد","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6176) and Muslim (17:24). The wording is that of al-Bukhārī.","chapter_en":"Welcoming the Guest, Visitor, and Delegation","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":41,"content":{"translation":{"en":["Ibn ʿAbbās narrated: When the delegation of ʿAbd al-Qays came to the Prophet ﷺ, he said: “Welcome to the delegation who have come neither disgraced nor regretful…” to the end of the hadith."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6176)، ومسلم (17: 24)، واللفظ للبخاري."},{"num":14282,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُرَّةَ مَوْلَى أُمِّ هَانِئٍ بِنْتِ أَبِي طَالِبٍ، أَخْبَرَهُ أَنَّهُ سَمِعَ أُمَّ هَانِئٍ بِنْتَ أَبِي طَالِبٍ، تَقُولُ: ذَهَبْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ، فَوَجَدْتُهُ يَغْتَسِلُ، وَفَاطِمَةُ ابْنَتُهُ تَسْتُرُهُ، قَالَتْ: فَسَلَّمْتُ عَلَيْهِ، فَقَالَ: مَنْ هَذِهِ، فَقُلْتُ: أَنَا أُمُّ هَانِئٍ بِنْتُ أَبِي طَالِبٍ فَقَالَ: مَرْحَبًا بِأُمِّ هَانِئٍ."],"takhrij":"متفق عليه: رواه البخاري في الصلاة (357)، ومسلم في صلاةالمسافرين (336: 82) كلاهما من حديث مالك، عن أبي النضر، أن أبا مرة أخبره فذكره.","grade":"متفق عليه","chapter_ar":"باب الترحيب بالضيف والزائر والوافد","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (357) and Muslim (336:82).","chapter_en":"Welcoming the Guest, Visitor, and Delegation","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الاستئذان والسلام","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Seeking Permission and Giving Salām","part_no":61,"group_no":6,"chapter_no":41,"content":{"translation":{"en":["Abū Murrah, the freedman of Umm Hāniʾ bint Abī Ṭālib, narrated that he heard Umm Hāniʾ bint Abī Ṭālib say: I went to the Messenger of Allah ﷺ in the Year of the Conquest and found him bathing while his daughter Fāṭimah was screening him. I gave him salām. He asked: “Who is this?” I replied: “I am Umm Hāniʾ bint Abī Ṭālib.” He said: “Welcome, Umm Hāniʾ.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (357)، ومسلم (336: 82)."},{"num":14283,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن أَبِي عَمْرَةَ الأنصاري قـال: أُوذِنَ أَبُو سَعِيدٍ الْخُدْرِيُّ بِجِنَازَةٍ، قَالَ: فَكَأَنَّهُ تَخَلَّفَ حَتَّى أَخَذَ الْقَوْمُ مَجَالِسَهُمْ، ثُمَّ جَاءَ مَعَهُ، فَلَمَّا رَآهُ الْقَوْمُ تَسَرَّعُوا عَنْهُ، وَقَامَ بَعْضُهُمْ عَنْهُ لِيَجْلِسَ فِي مَجْلِسِهِ، فَقَالَ: لاَ، إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: خَيْرُ الْمَجَالِسِ أَوْسَعُهَا، ثُمَّ تَنَحَّى فَجَلَسَ فِي مَجْلِسٍ وَاسِعٍ."],"takhrij":"حسن: رواه أبو داود (4820)، وأحمد (11137)، والبخاري في الأدب المفرد (1136)، وصحّحه الحاكم (4/269) كلهم من طرقٍ عن عبد الرحمن بن أبي الموال، أخبرني عبد الرحمن بن أبي عمرة الأنصاري قال: فذكره.","grade":"حسن","chapter_ar":"باب خير المجالس أوسعها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4820), Aḥmad (11137), and al-Bukhārī in al-Adab al-Mufrad (1136).","chapter_en":"The Best Gatherings Are the Most Spacious","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":1,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī ʿAmrah al-Anṣārī narrated: Abū Saʿīd al-Khudrī was informed of a funeral. It seems that he was delayed until the people had already taken their seats. Then he arrived. When the people saw him, they quickly made room for him, and some of them stood up so that he could sit in their places. He said: “No. I heard the Messenger of Allah ﷺ say: ‘The best gatherings are the most spacious.’” Then he moved aside and sat in a spacious place."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4820)، وأحمد (11137)، والبخاري في الأدب المفرد (1136)."},{"num":14284,"demo":false,"sanad":"","matn":["عَنْ أَبِي وَاقِدٍ اللَّيْثِيِّ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَمَا هُوَ جَالِسٌ فِي الْمَسْجِدِ، وَالنَّاسُ مَعَهُ، إِذْ أَقْبَلَ ثَلاَثَةُ، نَفَرٍ، فَأَقْبَلَ اثْنَانِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَذَهَبَ وَاحِدٌ، قَالَ فَوَقَفَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَمَّا أَحَدُهُمَا، فَرَأَى فُرْجَةً فِي الْحَلْقَةِ فَجَلَسَ فِيهَا، وَأَمَّا الآخَرُ فَجَلَسَ خَلْفَهُمْ، وَأَمَّا الثَّالِثُ فَأَدْبَرَ ذَاهِبًا، فَلَمَّا فَرَغَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَلاَ أُخْبِرُكُمْ عَنِ النَّفَرِ الثَّلاَثَةِ: أَمَّا أَحَدُهُمْ فَأَوَى إِلَى اللَّهِ، فَآوَاهُ اللَّهُ، وَأَمَّا الآخَرُ فَاسْتَحْيَا، فَاسْتَحْيَا اللَّهُ مِنْهُ، وَأَمَّا الآخَرُ فَأَعْرَضَ، فَأَعْرَضَ اللَّهُ عَنْهُ."],"takhrij":"متفق عليه: رواه مالك في السلام (4) عن إسحاق بن عبد الله بن أبي طلحة، عن أبي مرة، مولى عقيل بن أبي طالب، عن أبي واقد الليثي فذكره.","grade":"متفق عليه","chapter_ar":"باب من قعد حيث ينتهي به المجلس، ومن رأى فرجة في الحلقة فجلس فيها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (4), al-Bukhārī (66), and Muslim (2176).","chapter_en":"Sitting Where One Finds the Gathering Ending, and Sitting in an Open Space within the Circle","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Abū Wāqid al-Laythī narrated: While the Messenger of Allah ﷺ was sitting in the mosque with the people around him, three men approached. Two of them came toward the Messenger of Allah ﷺ, while one went away. When the two stood at the gathering of the Messenger of Allah ﷺ, they gave salām. One of them saw an open space in the circle and sat there. The other sat behind the people. As for the third, he turned away and left. When the Messenger of Allah ﷺ had finished, he said: “Shall I tell you about the three men? One of them sought refuge with Allah, so Allah gave him refuge. The second felt shy, so Allah showed modesty toward him. As for the third, he turned away, so Allah turned away from him.”"]},"buhuth":{"en":["This encourages filling open spaces in the study circle so that one may be nearer to the scholar or teacher, thereby attaining better listening, retention, and mastery of what is being taught.","As for the third man who turned away: if he was a hypocrite, then Allah’s turning away from him means excluding him from His mercy and compassion and then punishing him in the lowest depths of the Fire.","If he was a Muslim, then Allah’s turning away from him means depriving him of the opportunity to sit with the Prophet ﷺ, benefit from his lessons and admonitions, and receive the good attained by his two companions."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (4)، والبخاري (66)، ومسلم (2176)."},{"num":14285,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ: كُنَّا إِذَا أَتَيْنَا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَلَسَ أَحَدُنَا حَيْثُ يَنْتَهِي."],"takhrij":"حسن: رواه أبو داود (4825)، والترمذي (2725)، وأحمد (20855)، وصحّحه ابن حبان (6432) كلهم من طرقٍ عن شريك، عن سماك بن حرب، عن جابر بن سمرة قال: فذكره.","grade":"حسن","chapter_ar":"باب من قعد حيث ينتهي به المجلس، ومن رأى فرجة في الحلقة فجلس فيها","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4825), al-Tirmidhī (2725), Aḥmad (20855), and authenticated by Ibn Ḥibbān (6432).","chapter_en":"Sitting Where One Finds the Gathering Ending, and Sitting in an Open Space within the Circle","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn Samurah narrated: “When we came to the Prophet ﷺ, each one of us would sit wherever the gathering ended.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4825)، والترمذي (2725)، وأحمد (20855)، وصححه ابن حبان (6432)."},{"num":14286,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لا يُقيم الرَّجُلُ الرَّجُلُ مِنْ مقعده، ثُمَّ يُجْلِسَ فِيهِ، وَلَكِنْ تَفَسَّحُوا، وَتَوَسَّعُوا. وَزَادَ فِي رِوَايَةِ: وَكَانَ يَكْرَهُ أَنْ يَقُومَ الرَّجُلُ مِنْ مَجْلِسِهِ، ثُمَّ يُجْلِسَ مَكَانَهُ."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6270)، ومسلم في السلام (2177: 28) كلاهما من طرق عن عبيد الله، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن إقامة أحد من مكانه للجلوس فيه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6270) and Muslim (2177:28). The wording is that of al-Bukhārī, and the additional wording is also from al-Bukhārī.","chapter_en":"The Prohibition of Making Someone Leave His Place in Order to Sit There","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that the Prophet ﷺ said: “A man should not make another man get up from his seat and then sit in his place. Rather, make room and spread out.” Another narration adds: “He disliked that a man should get up from his seat so that another person could sit in his place.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا قِيلَ لَكُمْ تَفَسَّحُوا فِي الْمَجَالِسِ فَافْسَحُوا يَفْسَحِ اللّٰهُ لَكُمْ وَإِذَا قِيلَ انْشُزُوا فَانْشُزُوا يَرْفَعِ اللّٰهُ الَّذِينَ آمَنُوا مِنْكُمْ وَالَّذِينَ أُوتُوا الْعِلْمَ دَرَجَاتٍ وَاللّٰهُ بِمَا تَعْمَلُونَ خَبِيرٌ﴾ [المجادلة: ١١]."],"en":["Allah, the Exalted, says:","“O you who believe, when you are told, ‘Make room in the gatherings,’ then make room, and Allah will make room for you. And when you are told, ‘Rise,’ then rise. Allah will raise those among you who believe and those who have been given knowledge by degrees. And Allah is fully aware of what you do.”","[Sūrat al-Mujādilah 58:11]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6270)، ومسلم (2177: 28). واللفظ للبخاري، والزيادة للبخاري أيضا."},{"num":14287,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا يُقِيمَنَّ أَحَدُكُمْ أَخَاهُ يَوْمَ الْجُمُعَةِ، ثُمَّ لْيُخَالِفْ إِلَى مَقْعَدِهِ، فَيَقْعُدَ فِيهِ، وَلَكِنْ يَقُولُ: افْسَحُوا."],"takhrij":"صحيح: رواه مسلم في السلام (2178) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل وهو ابن عبيد الله، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب النهي عن إقامة أحد من مكانه للجلوس فيه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2178).","chapter_en":"The Prohibition of Making Someone Leave His Place in Order to Sit There","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Jābir narrated that the Prophet ﷺ said: “None of you should make his brother get up from his place on Friday and then move into his seat and sit there. Rather, he should say: ‘Make room.’”"]}},"tuhfa":{},"full":1,"rep":[3355],"tks":"صحيح: رواه مسلم (2178)."},{"num":14288,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يُقِيمُ الرَّجُلُ الرَّجُلَ مِنْ مَجْلِسِهِ ثُمَّ يَجْلِسُ فِيهِ، وَلَكِنْ افْسَحُوا يَفْسَحِ اللهُ لَكُمْ."],"takhrij":"حسن: رواه أحمد (10776) عن عبد الملك بن عمرو-هو العقدي-، حدثنا فُليح، عن أيوب، عن عبد الرحمن بن أبي صعصعة، عن يعقوب بن أبي يعقوب، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن إقامة أحد من مكانه للجلوس فيه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (10776).","chapter_en":"The Prohibition of Making Someone Leave His Place in Order to Sit There","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “A man should not make another man leave his place and then sit there himself. Rather, make room, and Allah will make room for you.”"]},"buhuth":{"en":["The meaning of the hadith is clear. An exception would be if a particular place is specifically reserved for a teacher, Qur’an reciters, or certain designated people, and someone else sits there; in that case, he may be asked to leave so that the person for whom the place was designated may sit there."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (10776)."},{"num":14289,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ يَحِلُّ لِرَجُلٍ أَنْ يُفَرِّقَ بَيْنَ اثْنَيْنِ إِلاَّ بِإِذْنِهِمَا."],"takhrij":"حسن: رواه أبو داود (4845)، والترمذي (2752)، وأحمد (6999) كلهم من طريق أسامة بن زيد، عن عمرو بن شعيب، عن أبيه، عن عبد الله بن عمرو قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية الجلوس بين الرجلين بغير إذنهما","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4845), al-Tirmidhī (2752), and Aḥmad (6999).","chapter_en":"The Dislike of Sitting Between Two People Without Their Permission","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “It is not lawful for a man to separate two people who are sitting together except with their permission.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4845)، والترمذي (2752)، وأحمد (6999)."},{"num":14290,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَجْلِسُ الرَّجُلُ بَيْنَ الرَّجُلِ وَابْنِهِ."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (3051)، وعلي بن الجعد في مسنده (2947) كلاهما من طريق محمد بن حبيب بن محمد الجارودي، حدثنا عبدالعزيز بن أبي حازم، عن أبيه، عن سهل بن سعد قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية الجلوس بين الرجل وولده","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (3051), and ʿAlī ibn al-Jaʿd in his Musnad (2947).","chapter_en":"The Dislike of Sitting Between a Man and His Son","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":5,"content":{"translation":{"en":["Sahl ibn Saʿd narrated that the Messenger of Allah ﷺ said: “A man should not sit between another man and his son.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (3051)، وعلي بن الجعد في مسنده (2947)."},{"num":14291,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَامَ أَحَدُكُمْ –وَفِي رِوَايَةِ: مَنْ قَامَ- مِنْ مَجْلِسِهِ ثُمَّ رَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ."],"takhrij":"صحيح: رواه مسلم في السلام (2179) من طرق عن سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب من قام من مجلسه ثم عاد فهو أحق به","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2179).","chapter_en":"Whoever Leaves His Seat and Then Returns Has More Right to It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “If one of you gets up from his seat and then returns to it, he has more right to it.” In another wording: “Whoever gets up from his seat and then returns to it has more right to it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2179)."},{"num":14292,"demo":false,"sanad":"","matn":["عَنْ وَهْبِ بْنِ حُذَيْفَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قَامَ الرَّجُلُ مِنْ مَجْلِسِهِ، فَرَجَعَ إِلَيْهِ فَهُوَ أَحَقُّ بِهِ، وَإِنْ كَانَتْ لَهُ حَاجَةٌ، فَقَامَ إِلَيْهَا، ثُمَّ رَجَعَ فَهُوَ أَحَقُّ بِهِ."],"takhrij":"صحيح: رواه الترمذي (2751)، وأحمد (15484)، والطحاوي في شرح المشكل (1277) كلهم من طريق خالد بن عبدالله الواسطي، عن عمرو بن يحيى، عن محمد بن يحيى بن حبان، عن عمّه واسع بن حبان، عن وهب بن حيفة فذكره.","grade":"صحيح","chapter_ar":"باب من قام من مجلسه ثم عاد فهو أحق به","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (2751), Aḥmad (15484), and al-Ṭaḥāwī in Sharḥ al-Mushkil (1277).","chapter_en":"Whoever Leaves His Seat and Then Returns Has More Right to It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Wahb ibn Ḥudhayfah narrated that the Prophet ﷺ said: “If a man gets up from his place and then returns to it, he has more right to it. Even if he gets up to attend to some need and then returns, he has more right to it.”"]},"buhuth":{"en":["The words “if a man gets up” mean that he leaves intending to return to that same place shortly. This intention may be known through contextual signs, such as leaving an item in that place or informing the person seated beside him."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2751)، وأحمد (15484)، والطحاوي في شرح المشكل (1277)."},{"num":14293,"demo":false,"sanad":"","matn":["قَالَ: أَبُو رِفَاعَةَ:  انْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يَخْطُبُ. قَالَ: فَقُلْتُ: يَا رَسُولَ اللَّهِ! رَجُلٌ غَرِيبٌ، جَاءَ يَسْأَلُ عَنْ دِينِهِ، لَا يَدْرِي مَا دِينُهُ. قَالَ: فَأَقْبَلَ عَلَيَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. وَتَرَكَ خُطْبَتَهُ حَتَّى انْتَهَى إِلَيَّ، فَأُتِيَ بِكُرْسِيٍّ، حَسِبْتُ قَوَائِمَهُ حَدِيدًا، قَالَ: فَقَعَدَ عَلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَجَعَلَ يُعَلِّمُنِي مِمَّا عَلَّمَهُ اللَّهُ. ثُمَّ أَتَى خُطْبَتَهُ فَأَتَمَّ آخِرَهَا."],"takhrij":"صحيح: رواه مسلم في الجمعة (876) عن شيبان بن فرُّوخ، ثنا سليمان ابن مُغيرة، ثنا حميد بن هِلالٍ، قال: قال أبو رفاعة، فذكره.","grade":"صحيح","chapter_ar":"باب من قام من مجلسه ثم عاد فهو أحق به","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (876).","chapter_en":"Whoever Leaves His Seat and Then Returns Has More Right to It","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":6,"content":{"translation":{"en":["Abū Rifāʿah narrated: I came to the Prophet ﷺ while he was delivering a sermon. I said: “O Messenger of Allah, a stranger has come asking about his religion, for he does not know what his religion is.” The Messenger of Allah ﷺ turned toward me and left the sermon until he came to me. A chair was brought for him, and I thought its legs were made of iron. The Messenger of Allah ﷺ sat on it and began teaching me from what Allah had taught him. Then he returned to his sermon and completed its remaining portion."]}},"tuhfa":{},"full":1,"rep":[3321],"tks":"صحيح: رواه مسلم (876)."},{"num":14294,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُقعدَ بَيْنَ الظِّلِّ وَالشَّمْسِ."],"takhrij":"حسن: رواه ابن ماجه (3722) عن أبي بكر بن أبي شيبة، حدثنا زيد بن الحباب، عن أبي المنيب، عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب كراهية الجلوس بين الظل والشمس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3722).","chapter_en":"The Dislike of Sitting Partly in Shade and Partly in Sunlight","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["Buraydah narrated that the Prophet ﷺ prohibited sitting in a place that is partly shaded and partly exposed to the sun."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3722)."},{"num":14295,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يُجْلَسَ بَيْنَ الضِّحِّ وَالظِّلِّ، وَقَالَ: مَجْلِسُ الشَّيْطَانِ."],"takhrij":"حسن: رواه أحمد (15421) من طرقٍ عن همام، حدثنا قتادة، عن كثير، عن أبي عياض (وهو عمرو بن الأسود)، عن رجل من أصحاب النبي صلى الله عليه وسلم فذكره.","grade":"حسن","chapter_ar":"باب كراهية الجلوس بين الظل والشمس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15421).","chapter_en":"The Dislike of Sitting Partly in Shade and Partly in Sunlight","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":7,"content":{"translation":{"en":["A man from among the Companions of the Prophet ﷺ narrated that the Prophet ﷺ prohibited sitting between direct sunlight and shade, and said: “It is the sitting place of Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15421)."},{"num":14296,"demo":false,"sanad":"","matn":["عن الشريد بن سُوَيْدٍ، قَالَ: مَرَّ بِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا جَالِسٌ هَكَذَا، وَقَدْ وَضَعْتُ يَدِيَ الْيُسْرَى خَلْفَ ظَهْرِي وَاتَّكَأْتُ عَلَى أَلْيَةِ يَدِي، فَقَالَ: أَتَقْعُدُ قِعْدَةَ الْمَغْضُوبِ عَلَيْهِمْ."],"takhrij":"صحيح: رواه أبو داود (4848)، وأحمد (19454)، وصحّحه ابن حبان (5674)، والحاكم (4/269) كلهم من طريق عيسى بن يونس، حدثنا ابنُ جريج، عن إبراهيم بن ميسرة، عن عمرو بن الشريد، عن أبيه الشريد بن سويد قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الجلسة المكروهة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4848), Aḥmad (19454), authenticated by Ibn Ḥibbān (5674), and al-Ḥākim (4/269).","chapter_en":"A Disliked Sitting Posture","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":8,"content":{"translation":{"en":["Al-Sharīd ibn Suwayd narrated: The Messenger of Allah ﷺ passed by me while I was sitting like this: I had placed my left hand behind my back and was leaning on the fleshy base of my palm. He said: “Are you sitting in the manner of those upon whom wrath has been incurred?”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (4848)، وأحمد (19454)، وصححه ابن حبان (5674)، والحاكم (4/269)."},{"num":14297,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِفِنَاءِ الْكَعْبَةِ، مُحْتَبِيًا بِيَدِهِ، هَكَذَا."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6272) عن محمد بن أبي غالب، أخبرنا إبراهيم بن المنذر الحزامي، حدثنا محمد بن فليح، عن أبيه، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الجلوس محتبيا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6272).","chapter_en":"Sitting in the Iḥtibāʾ Posture","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿUmar narrated: “I saw the Messenger of Allah ﷺ in the courtyard of the Kaʿbah, sitting in the iḥtibāʾ posture while holding his legs with his hands, like this.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (6272)."},{"num":14298,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلاَ أُنَبِّئُكُمْ بِأَكْبَرِ الْكَبَائِرِ؟ ثَلاَثًا، قَالُوا: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: الإِشْرَاكُ بِاللَّهِ، وَعُقُوقُ الْوَالِدَيْنِ، - وَجَلَسَ وَكَانَ مُتَّكِئًا فَقَالَ - أَلاَ وَقَوْلُ الزُّورِ قَالَ: فَمَا زَالَ يُكَرِّرُهَا حَتَّى قُلْنَا: لَيْتَهُ سَكَتَ."],"takhrij":"متفق عليه: رواه البخاري في الشهادات (2654)، ومسلم في الإيمان (87) كلاهما من طريق سعيد الجريري، حدثنا عبد الرحمن بن أبي بكرة، عن أبي بكرة فذكره.","grade":"متفق عليه","chapter_ar":"باب من اتكأ بين يدي أصحابه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2654) and Muslim (87).","chapter_en":"One Who Reclines in the Presence of His Companions","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":10,"content":{"translation":{"en":["Abū Bakrah narrated that the Prophet ﷺ said three times: “Shall I inform you of the greatest of the major sins?” They replied: “Yes, O Messenger of Allah.” He said: “Associating partners with Allah and disobedience to parents.” Then he sat upright after having been reclining and said: “And indeed, false speech!” He continued repeating it until we thought: “If only he would stop.”"]}},"tuhfa":{},"full":1,"rep":[229,12795],"tks":"متفق عليه: رواه البخاري (2654)، ومسلم (87)."},{"num":14299,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو، فَحَدَّثَنَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذُكِرَ لَهُ صَوْمِي، فَدَخَلَ عَلَىَّ، فَأَلْقَيْتُ لَهُ وِسَادَةً مِنْ أَدَمٍ، حَشْوُهَا لِيفٌ، فَجَلَسَ عَلَى الأَرْضِ، وَصَارَتِ الْوِسَادَةُ بَيْنِي وَبَيْنَهُ، فَقَالَ لِي."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6277)، ومسلم في الصيام (159: 191) كلاهما من طرق عن خالد بن عبد الله (هو الطحان)، عن خالد الحذاء، عن أبي قلابة، قال: أخبرني أبو المليح، قال: دخلت مع أبيك زيد على عبد الله بن عمرو، فحدثنا فذكره.","grade":"متفق عليه","chapter_ar":"باب من ألقي له وسادة للجلوس فاختار التواضع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6277) and Muslim (1159:191).","chapter_en":"One for Whom a Cushion Was Offered, but Who Chose Humility","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated: The Prophet ﷺ was informed about my fasting, so he entered upon me. I placed a leather cushion for him stuffed with palm fiber, but he sat on the ground, leaving the cushion between me and him… Then he mentioned the remainder of the hadith."]},"buhuth":{"en":["This contains encouragement to honor an elder, to prefer humility and train oneself upon it, and the permissibility of declining an offered honor when doing so will not hurt the feelings of the person offering it, as mentioned in Fatḥ al-Bārī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6277)، ومسلم (1159: 191)."},{"num":14300,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: لَمَّا تَزَوَّجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ زَيْنَبَ ابْنَةَ جَحْشٍ دَعَا النَّاسَ، طَعِمُوا ثُمَّ جَلَسُوا يَتَحَدَّثُونَ ـ قَالَ: ـ فَأَخَذَ كَأَنَّهُ يَتَهَيَّأُ لِلْقِيَامِ فَلَمْ يَقُومُوا، فَلَمَّا رَأَى ذَلِكَ قَامَ، فَلَمَّا قَامَ قَامَ مَنْ قَامَ مَعَهُ مِنَ النَّاسِ، وَبَقِيَ ثَلاَثَةٌ، وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ لِيَدْخُلَ فَإِذَا الْقَوْمُ جُلُوسٌ، ثُمَّ إِنَّهُمْ قَامُوا فَانْطَلَقُوا ـ قَالَ: ـ فَجِئْتُ فَأَخْبَرْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُمْ قَدِ انْطَلَقُوا، فَجَاءَ حَتَّى دَخَلَ، فَذَهَبْتُ أَدْخُلُ، فَأَرْخَى الْحِجَابَ بَيْنِي وَبَيْنَهُ، وَأَنْزَلَ اللَّهُ تَعَالَى: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلاَّ أَنْ يُؤْذَنَ لَكُمْ} إِلَى﴾ [سورة الأحزاب: 53] قَوْلِهِ: ﴿إِنَّ ذَلِكُمْ كَانَ عِنْدَ اللَّهِ عَظِيمًا﴾ [سورة الأحزاب: 53]}."],"takhrij":"متفق عليه: رواه البخاري في الاستئذان (6271)، ومسلم في النكاح (1428: 92) كلاهما من طريق المعتمر بن سليمان قال: سمعت أبي يذكر عن أبي مجلز، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب من قام من مجلسه أو تهيأ للقيام ليقوم الناس","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6271) and Muslim (1428:92).","chapter_en":"One Who Gets Up, or Appears Ready to Get Up, So That the People Will Leave","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik narrated: When the Messenger of Allah ﷺ married Zaynab bint Jaḥsh, he invited the people. They ate and then remained sitting, talking. He began acting as though he were preparing to get up, but they did not leave. When he saw that, he stood up. When he stood, some of the people stood and left with him, while three remained behind. The Prophet ﷺ later came back intending to enter, but those people were still sitting there. Eventually, they got up and left. Anas said: I went and informed the Prophet ﷺ that they had departed. He came and entered. I went to enter after him, but he lowered the curtain between me and him. Then Allah, the Exalted, revealed: “O you who believe, do not enter the houses of the Prophet unless permission is given to you…” until His saying: “…Indeed, that would be, in the sight of Allah, an enormous matter.” [Sūrat al-Aḥzāb 33:53]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (6271)، ومسلم (1428: 92)."},{"num":14301,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا حَدَّثَ الرَّجُلُ بِالْحَدِيثِ، ثُمَّ الْتَفَتَ فَهِيَ أَمَانَةٌ."],"takhrij":"حسن: رواه أبو داود (4868)، والترمذي (1959)، وأحمد (14474) كلهم من طريق ابن أبي ذئب، أخبرني عبد الرحمن بن عطاء، عن عبد الملك بن جابر بن عتيك، عن جابر بن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب أن المجالس أمانة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4868), al-Tirmidhī (1959), and Aḥmad (14474).","chapter_en":"What Is Said in Gatherings Is a Trust","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الجلوس والمجلس","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Sitting and Gatherings","part_no":61,"group_no":7,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “If a man tells another person something and then looks around, it is a trust.”"]},"buhuth":{"en":["The words “then he looks around” mean that while speaking he turns to see whether anyone else is listening, out of concern that the conversation might be overheard. This is an indication that what he is saying is confidential, and therefore it is not permissible to disclose it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4868)، والترمذي (1959)، وأحمد (14474)."},{"num":14302,"demo":false,"sanad":"","matn":["عن عُمَرَ بن أَبِي سَلَمَةَ، يَقُولُ: كُنْتُ غُلاَمًا فِي حَجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا غُلاَمُ، سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ. فَمَا زَالَتْ تِلْكَ طِعْمَتِي بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5376)، ومسلم في الأشربة (2022: 108) كلاهما من طريق سفيان بن عيينة، عن الوليد بن كثير، عن وهب بن كيسان، أنه سمع عمر بن أبي سلمة، يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب التسمية على الطعام والشراب وعند دخول البيت","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5376) and Muslim (2022:108).","chapter_en":"Saying the Name of Allah over Food and Drink and When Entering the House","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn Abī Salamah narrated: I was a young boy under the care of the Messenger of Allah ﷺ, and my hand used to wander around the dish. The Messenger of Allah ﷺ said to me: “Young boy, mention the Name of Allah, eat with your right hand, and eat from what is nearest to you.” That remained my manner of eating thereafter."]}},"tuhfa":{},"full":1,"rep":[11163],"tks":"متفق عليه: رواه البخاري (5376)، ومسلم (2022: 108)."},{"num":14303,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ: كُنَّا إِذَا حَضَرْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا لَمْ نَضَعْ أَيْدِيَنَا، حَتَّى يَبْدَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَيَضَعَ يَدَهُ، وَإِنَّا حَضَرْنَا مَعَهُ مَرَّةً طَعَامًا، فَجَاءَتْ جَارِيَةٌ كَأَنَّهَا تُدْفَعُ، فَذَهَبَتْ لِتَضَعَ يَدَهَا فِي الطَّعَامِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهَا، ثُمَّ جَاءَ أَعْرَابِيٌّ كَأَنَّمَا يُدْفَعُ، فَأَخَذَ بِيَدِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّيْطَانَ يَسْتَحِلُّ الطَّعَامَ أَنْ لَا يُذْكَرَ اسْمُ اللَّهِ عَلَيْهِ، وَإِنَّهُ جَاءَ بِهَذِهِ الْجَارِيَةِ لِيَسْتَحِلَّ بِهَا، فَأَخَذْتُ بِيَدِهَا، فَجَاءَ بِهَذَا الْأَعْرَابِيِّ لِيَسْتَحِلَّ بِهِ، فَأَخَذْتُ بِيَدِهِ، وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ يَدَهُ فِي يَدِي مَعَ يَدِهَا وَزَادَ فِي رِوَايَةِ: ثُمَّ ذَكَرَ اسْمُ اللَّهِ وأكل."],"takhrij":"صحيح: رواه مسلم في الأشربة (2017: 102) من طريق أبي معاوية، عن الأعمش، عن خيثمة، عن أبي حذيفة، عن حذيفة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب التسمية على الطعام والشراب وعند دخول البيت","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2017:102).","chapter_en":"Saying the Name of Allah over Food and Drink and When Entering the House","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Ḥudhayfah narrated: Whenever we attended a meal with the Prophet ﷺ, we would not put our hands into the food until the Messenger of Allah ﷺ began and placed his hand in it. On one occasion we were present with him at a meal when a young girl came rushing as though she were being pushed. She went to put her hand into the food, but the Messenger of Allah ﷺ took hold of her hand. Then a Bedouin came rushing as though he too were being pushed, so the Prophet ﷺ took hold of his hand. The Messenger of Allah ﷺ said: “Satan considers food lawful for himself when the Name of Allah is not mentioned over it. He brought this girl so that he might make the food lawful through her, but I took hold of her hand. Then he brought this Bedouin so that he might make it lawful through him, but I took hold of his hand. By the One in whose hand is my soul, his hand is in my hand along with hers.” Another narration adds: Then he mentioned the Name of Allah and ate."]},"buhuth":{"en":["The words:","“His hand is in my hand along with hers”","mean that Satan’s hand was in the hand of the Messenger of Allah ﷺ together with the hand of the girl.","In some copies of Muslim it reads:","“their two hands,”","meaning the hand of the girl and the hand of the Bedouin.","The hadith indicates that Satan has a hand and that he takes from food when the Name of Allah has not been mentioned over it.","The words:","“so that he might make it lawful through her”","mean that he would actually partake of the food.","It has also been said that his making it lawful means causing the blessing to be removed from that food."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2017: 102)."},{"num":14304,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ، فَذَكَرَ اللهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ، وَلَا عَشَاءَ، وَإِذَا دَخَلَ، فَلَمْ يَذْكُرِ اللَّهَ عِنْدَ دُخُولِهِ، قَالَ الشَّيْطَانُ: أَدْرَكْتُمُ الْمَبِيتَ، وَإِذَا لَمْ يَذْكُرِ اللَّهَ عِنْدَ طَعَامِهِ، قَالَ: أَدْرَكْتُمُ الْمَبِيتَ وَالْعَشَاءَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2018) عن محمد بن المثنى العنزي، حدثنا الضحاك يعني أبا عاصم، عن ابن جريج، أخبرني أبو الزبير، عن جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب التسمية على الطعام والشراب وعند دخول البيت","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2018).","chapter_en":"Saying the Name of Allah over Food and Drink and When Entering the House","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that he heard the Prophet ﷺ say: “When a man enters his house and mentions Allah when entering and when eating, Satan says: ‘You have no lodging here tonight and no dinner.’ But if he enters without mentioning Allah upon entering, Satan says: ‘You have obtained lodging.’ And if he does not mention Allah when eating, Satan says: ‘You have obtained both lodging and dinner.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[8227,11164,11304],"tks":"صحيح: رواه مسلم (2018)."},{"num":14305,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَسِيَ أَنْ يَذْكُرَ اللَّهَ فِي أَوَّلِ طَعَامِهِ فَلْيَقُلْ حِينَ يَذْكُرُ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ، فَإِنَّهُ يَسْتَقْبِلُ طَعَامَهُ جَدِيدًا، وَيَمْنَعُ الْخَبِيثَ مَا كَانَ يُصِيبُ مِنْهُ."],"takhrij":"صحيح: رواه ابن حبان (5213)، وابن السني (460)، والطبراني في الكبير (10354) كلهم من طريق خليفة بن خياط، قال: حدثنا عمر بن علي المقدمي قال: سمعت موسى الجهني، يقول: أخبرني القاسم بن عبد الرحمن بن عبد الله بن مسعود، عن أبيه، عن جده، قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب من نسي التسمية في أوله فليذكره في آخره","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (5213), Ibn al-Sunnī (460), and al-Ṭabarānī in al-Muʿjam al-Kabīr (10/210).","chapter_en":"Whoever Forgets to Mention Allah at the Beginning Should Mention Him When He Remembers","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Whoever forgets to mention Allah at the beginning of his meal should say when he remembers: ‘In the Name of Allah at its beginning and its end.’ He thereby begins his meal anew, and the wicked one is prevented from what he had been taking from it.”"]}},"tuhfa":{},"full":1,"rep":[11166],"tks":"صحيح: رواه ابن حبان (5213)، وابن السني (460)، والطبراني في الكبير (10354)."},{"num":14306,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ وليشرب بِيَمِينِهِ، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ وَيَشْرَبُ بِشِمَالِهِ."],"takhrij":"صحيح: رواه مالك في الجامع (1931- موطأ برواية أبي مصعب الزهري)، عن ابن شهاب، عن أبي بكر بن عبيدالله بن عبدالله بن عمر، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب الأكل والشرب باليمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in al-Jāmiʿ (1931, in the recension of the Muwaṭṭaʾ by Abū Muṣʿab al-Zuhrī) and Muslim (2020:105).","chapter_en":"Eating and Drinking with the Right Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “When one of you eats, let him eat with his right hand, and when he drinks, let him drink with his right hand, for Satan eats with his left hand and drinks with his left hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (1931 - موطأ برواية أبي مصعب الزهري)، ورواه مسلم (2020: 105)."},{"num":14307,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَكَلَ أَحَدُكُمْ فَلْيَأْكُلْ بِيَمِينِهِ، وَلْيَشْرَبْ بِيَمِينِهِ، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ، وَيَشْرَبُ بِشِمَالِهِ."],"takhrij":"حسن: رواه ابن أبي شيبة في المصنف (24439)، وأحمد (13097)، وأبو يعلى (4772-4774) كلهم من طرق عن هشام بن حسان، عن عبد الله بن دهقان، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب الأكل والشرب باليمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Shaybah in al-Muṣannaf (5/555–556, al-Laḥḥām edition), Aḥmad (13097), and Abū Yaʿlā (4772–4774).","chapter_en":"Eating and Drinking with the Right Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Anas narrated that the Messenger of Allah ﷺ said: “When one of you eats, let him eat with his right hand, and let him drink with his right hand, for Satan eats with his left hand and drinks with his left hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن أبي شيبة في المصنف (24439)، وأحمد (13097)، وأبو يعلى (4772-4774)."},{"num":14308,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لِيَأْكُلْ أَحَدُكُمْ بِيَمِينِهِ، وَلْيَشْرَبْ بِيَمِينِهِ، وَلْيَأْخُذْ بِيَمِينِهِ، وَلْيُعْطِ بِيَمِينِهِ، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ، وَيَشْرَبُ بِشِمَالِهِ، وَيُعْطِي بِشِمَالِهِ، وَيَأْخُذُ بِشِمَالِهِ."],"takhrij":"صحيح: رواه ابن ماجه (3266) عن هشام بن عمار، حدثنا الهقل بن زياد، حدثنا هشام بن حسان، عن يحيى بن أبي كثير، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الأكل والشرب باليمين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3266).","chapter_en":"Eating and Drinking with the Right Hand","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “Let one of you eat with his right hand, drink with his right hand, take with his right hand, and give with his right hand, for Satan eats with his left hand, drinks with his left hand, gives with his left hand, and takes with his left hand.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3266)."},{"num":14309,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ: عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَا تَأْكُلُوا بِالشِّمَالِ، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِالشِّمَالِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2019) من طريق الليث (هو ابن سعد)، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الأكل بالشمال من غير عذر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in al-Ashribah (2019).","chapter_en":"The Dislike of Eating with the Left Hand Without an Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “Do not eat with the left hand, for Satan eats with the left hand.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2019)."},{"num":14310,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَا يَأْكُلَنَّ أَحَدٌ مِنْكُمْ بِشِمَالِهِ، وَلَا يَشْرَبَنَّ بِهَا، فَإِنَّ الشَّيْطَانَ يَأْكُلُ بِشِمَالِهِ، وَيَشْرَبُ بِهَا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2020: 106) عن أبي الطاهر وحرملة، قال أبو الطاهر: أخبرنا، وقال حرملة: حدثنا عبد الله بن وهب، حدثني عمر بن محمد، حدثني القاسم بن عبيد الله بن عبد الله بن عمر، حدثه عن سالم، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الأكل بالشمال من غير عذر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2020:106).","chapter_en":"The Dislike of Eating with the Left Hand Without an Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “None of you should eat with his left hand or drink with it, for Satan eats with his left hand and drinks with it.”"]},"buhuth":{"en":["Nāfiʿ used to add:","“Nor should he take with it or give with it.”","This addition is connected through the same preceding chain."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2020: 106)."},{"num":14311,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى أَنْ يَأْكُلَ الرَّجُلُ بِشِمَالِهِ، أَوْ يَمْشِيَ فِي نَعْلٍ وَاحِدَةٍ، وَأَنْ يَشْتَمِلَ الصَّمَّاءَ، وَأَنْ يَحْتَبِيَ فِي ثَوْبٍ وَاحِدٍ كَاشِفًا عَنْ فَرْجِهِ."],"takhrij":"صحيح: رواه مالك في صفة النبي صلى الله عليه وسلم (5) عن أبي الزبير، عن جابر بن عبد الله فذكره. ورواه مسلم في اللباس والزينة (2099: 70) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب كراهية الأكل بالشمال من غير عذر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in Ṣifat al-Nabī ﷺ (5) and Muslim (2099:70).","chapter_en":"The Dislike of Eating with the Left Hand Without an Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ prohibited a man from eating with his left hand, walking while wearing only one sandal, wrapping himself in the ṣammāʾ manner, and sitting in the iḥtibāʾ posture in a single garment while exposing his private parts."]}},"tuhfa":{},"full":1,"rep":[15362],"tks":"صحيح: رواه مالك (5)، ورواه مسلم (2099: 70)."},{"num":14312,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بن الأكوع أَنَّ رَجُلًا أَكَلَ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشِمَالِهِ، فَقَالَ: كُلْ بِيَمِينِكَ، قَالَ: لَا أَسْتَطِيعُ، قَالَ: لَا اسْتَطَعْتَ مَا مَنَعَهُ إِلَّا الْكِبْرُ، قَالَ: فَمَا رَفَعَهَا إِلَى فِيهِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2021) عن أبي بكر بن أبي شيبة، حدثنا زيد بن الحباب، عن عكرمة بن عمار، حدثني إياس بن سلمة بن الأكوع، أن أباه، حدثه فذكره.","grade":"صحيح","chapter_ar":"باب كراهية الأكل بالشمال من غير عذر","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2021).","chapter_en":"The Dislike of Eating with the Left Hand Without an Excuse","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":4,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ narrated: A man ate with his left hand in the presence of the Messenger of Allah ﷺ. He said to him: “Eat with your right hand.” The man replied: “I cannot.” He said: “May you never be able to.” Nothing prevented him except arrogance. Salamah said: “After that, he was never able to raise that hand to his mouth.”"]},"buhuth":{"en":["It is said that this man’s name was Busr ibn Rāʿī al-ʿAyr al-Ashjaʿī, as explicitly stated in the narrations of al-Dārimī, ʿAbd ibn Ḥumayd, Ibn Ḥibbān, and al-Ṭabarānī in the hadith of Salamah ibn al-Akwaʿ, where the Prophet ﷺ saw Busr ibn Rāʿī al-ʿAyr eating and said to him… then the hadith is mentioned. See al-Iṣābah (645).","The word al-ʿayr, with a fatḥah, means a wild donkey.","It is also said that he had been a hypocrite at the beginning, then later embraced Islam, though he is not known except through this hadith.","This contains evidence for the permissibility of supplicating against someone who arrogantly and haughtily violates a religious ruling.","Allah answered the supplication of the Prophet ﷺ concerning this man, and his right hand became paralyzed; after that day he could no longer raise it to his mouth."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14967],"tks":"صحيح: رواه مسلم (2021)."},{"num":14313,"demo":false,"sanad":"","matn":["عَنْ عُمَرَ بْنِ أَبِي سَلَمَةَ أَنَّهُ قَالَ:  أَكَلْتُ يَوْمًا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلْتُ آخُذُ مِنْ لَحْمٍ حَوْلَ الصَّحْفَةِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: كُلْ مِمَّا يَلِيكَ."],"takhrij":"متفق عليه: رواه مسلم في الأشربة (2022: 109) من طريق محمد بن عمرو بن حلحلة، عن وهب بن كيسان، عن عمر بن أبي سلمة فذكره.","grade":"متفق عليه","chapter_ar":"باب استحباب الأكل مما يليه، وكراهية الأكل من وسط الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5377) and Muslim (2022:109).","chapter_en":"The Recommendation to Eat from What Is Nearest and the Dislike of Eating from the Middle of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿUmar ibn Abī Salamah narrated: One day I ate with the Messenger of Allah ﷺ and began taking meat from different parts around the dish. The Messenger of Allah ﷺ said to me: “Eat from what is nearest to you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5377)، ومسلم (2022: 109)."},{"num":14314,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أُتِيَ بِقَصْعَةٍ مِنْ ثَرِيدٍ، فَقَالَ: كُلُوا مِنْ حَوْلِهَا، وَلَا تَأْكُلُوا مِنْ وَسْطِهَا، فَإِنَّ الْبَرَكَةَ تَنْزِلُ فِي وَسْطِهَا.","وفي لفظ: إِذَا أَكَلَ أَحَدُكُمْ طَعَامًا فَلاَ يَأْكُلْ مِنْ أَعْلَى الصَّحْفَةِ، وَلَكِنْ لِيَأْكُلْ مِنْ أَسْفَلِهَا، فَإِنَّ الْبَرَكَةَ تَنْزِلُ مِنْ أَعْلاَهَا."],"takhrij":"صحيح: رواه أبو داود (3772)، وأحمد (3190) كلاهما من طريق شعبة-، والترمذي (1805) من طريق جرير بن عبد الحميد-، وابن ماجه (3277) من طريق محمد بن فضيل-، وأحمد (2439، 3214) من طريق سفيان الثوري- كلهم عن عطاء بن السائب، عن سعيد بن جبير، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الأكل مما يليه، وكراهية الأكل من وسط الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3772) and Aḥmad (3190), and this is Aḥmad’s wording.","chapter_en":"The Recommendation to Eat from What Is Nearest and the Dislike of Eating from the Middle of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ was brought a bowl of tharīd and said: “Eat from around its edges and do not eat from its middle, for blessing descends upon its middle.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3772)، وأحمد (3190) - والسياق له."},{"num":14315,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن بُسر الْمَازِنِيِّ قَالَ: بَعَثَنِي أَبِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَدْعُوهُ إِلَى طَعَامٍ فَجَاءَ مَعِي، فَلَمَّا دَنَوْتُ مِنَ الْمَنْزِلِ أَسْرَعْتُ، فَأَعْلَمْتُ أَبَوَيَّ، فَخَرَجَا، فَتَلَقَّيَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَرَحَّبَا بِهِ، وَوَضَعْنَا لَهُ قَطِيفَةً كَانَتْ عِنْدَنَا زِئْبِرِيَّةً، فَقَعَدَ عَلَيْهَا، ثُمَّ قَالَ أَبِي لِأُمِّي: هَاتِ طَعَامَكِ، فَجَاءَتْ بِقَصْعَةٍ فِيهَا دَقِيقٌ قَدْ عَصَدَتْهُ بِمَاءٍ وَمِلْحٍ، فَوَضَعْتُهُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: خُذُوا بِسْمِ اللَّهِ مِنْ حَوَالَيْهَا، وَذَرُوا ذُرْوَتَهَا، فَإِنَّ الْبَرَكَةَ فِيهَا، فَأَكَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَكَلْنَا مَعَهُ، وَفَضَلَ مِنْهَا فَضْلَةٌ، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللهُمَّ اغْفِرْ لَهُمْ، وَارْحَمْهُمْ، وَبَارِكْ عَلَيْهِمْ، وَوَسِّعْ عَلَيْهِمْ فِي أَرْزَاقِهِمْ."],"takhrij":"صحيح: رواه أحمد (17678) عن أبي المغيرة، حدثنا صفوان بن عمرو، قال: حدثني عبد الله بن بسر المازني قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الأكل مما يليه، وكراهية الأكل من وسط الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17678) and Ibn Ḥibbān (5299).","chapter_en":"The Recommendation to Eat from What Is Nearest and the Dislike of Eating from the Middle of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Busr al-Māzinī narrated: My father sent me to the Messenger of Allah ﷺ to invite him to a meal. He came with me. When I drew near to the house, I hurried ahead and informed my parents. They came out to meet the Messenger of Allah ﷺ, welcomed him, and laid out for him a woolly cloak we had. He sat upon it. My father then said to my mother: “Bring your food.” She brought a bowl containing flour that she had mixed and thickened with water and salt and placed it before the Messenger of Allah ﷺ. He said: “In the Name of Allah, eat from around its edges and leave its top, for the blessing is in it.” The Messenger of Allah ﷺ ate, and we ate with him, yet some food remained. Then the Messenger of Allah ﷺ said: “O Allah, forgive them, have mercy on them, bless them, and expand their provision.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17678)، وابن حبان (5299)."},{"num":14316,"demo":false,"sanad":"","matn":["عَنْ وَاثِلَةَ بْنَ الْأَسْقَعِ قَالَ: كُنْتُ مِنْ أَهْلِ الصُّفَّةِ، فَدَعَا رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمًا بِقُرْصٍ، فَكَسَرَهُ فِي الْقَصْعَةِ، وَصَنَعَ فِيهَا مَاءً سُخْنًا، ثُمَّ صَنَعَ فِيهَا وَدَكًا، ثُمَّ سَفْسَفَهَا، ثُمَّ لَبَّقَهَا، ثُمَّ صَعْنَبَهَا، ثُمَّ قَالَ: اذْهَبْ، فَأْتِنِي بِعَشَرَةٍ، أَنْتَ عَاشِرُهُم، فَجِئْتُ بِهِمْ، فَقَالَ: كُلُوا، وَكُلُوا مِنْ أَسْفَلِهَا، وَلَا تَأْكُلُوا مِنْ أَعْلَاهَا، فَإِنَّ الْبَرَكَةَ تَنْزِلُ مِنْ أَعْلَاهَا، فَأَكَلُوا مِنْهَا حَتَّى شَبِعُوا."],"takhrij":"حسن: رواه الإمام أحمد (16006) عن عتاب بن زياد الخراساني المروزي، حدثنا عبد الله بن المبارك، أخبرنا ابنُ لهيعة، حدثني يزيد بن أبي حبيب أن ربيعة بن يزيد الدمشقي أخبره، عن واثلة بن الأسقع فذكره.","grade":"حسن","chapter_ar":"باب استحباب الأكل مما يليه، وكراهية الأكل من وسط الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (16006).","chapter_en":"The Recommendation to Eat from What Is Nearest and the Dislike of Eating from the Middle of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Wāthilah ibn al-Asqaʿ narrated: I was among the people of al-Ṣuffah. One day the Messenger of Allah ﷺ called for a round loaf of bread. He broke it into a bowl, poured hot water over it, added fat, mixed it thoroughly, blended it together, and prepared it. Then he said: “Go and bring me ten people, with you as the tenth.” So I brought them. He said: “Eat, and eat from its lower sides, and do not eat from its top, for blessing descends from its top.” They ate from it until they were full."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (16006)."},{"num":14317,"demo":false,"sanad":"","matn":["عن سلمى قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَكْرَهُ أَنْ يُؤْخَذَ مِنْ رَأْسِ الطَّعَامِ."],"takhrij":"حسن: رواه الطبراني في الكبير (24/ح 754) عن جعفر بن سليمان النوفلي ومحمد بن عبد الله الحضرمي قالا: ثنا إبراهيم بن المنذر الحزامي، ثنا معن بن عيسى، ثنا فائد مولى عباد، عن مولاه عبيد الله بن علي بن أبي رافع، عن جدّته سلمى قالت: فذكرتْه.","grade":"حسن","chapter_ar":"باب استحباب الأكل مما يليه، وكراهية الأكل من وسط الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (24/297).","chapter_en":"The Recommendation to Eat from What Is Nearest and the Dislike of Eating from the Middle of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Salmā narrated: “The Messenger of Allah ﷺ disliked that food be taken from its top.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (24/ح 754)."},{"num":14318,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ يَقُولُ إِنَّ خَيَّاطًا دَعَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِطَعَامٍ صَنَعَهُ. قَالَ أَنَسٌ: فَذَهَبْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى ذَلِكَ الطَّعَامِ، فَقَرَّبَ إِلَيْهِ خُبْزًا مِنْ شَعِيرٍ وَمَرَقًا فِيهِ دُبَّاءُ. قَالَ أَنَسٌ: فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَتَبَّعُ الدُّبَّاءَ مِنْ حَوْلِ الْقَصْعَةِ، فَلَمْ أَزَلْ أُحِبُّ الدُّبَّاءَ بَعْدَ ذَلِكَ الْيَوْمِ."],"takhrij":"متفق عليه: رواه مالك في النكاح (51) عن إسحاق بن عبد الله بن أبي طلحة، أنه سمع أنس بن مالك، يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الأكل من وسط الطعام إذا علم رضا الجلساء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in al-Nikāḥ (51), al-Bukhārī (2092), and Muslim (2041:144), who added: “gourd and dried meat.”","chapter_en":"The Permissibility of Eating from Different Parts of the Dish When the Companions’ Approval Is Known","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik narrated: A tailor invited the Messenger of Allah ﷺ to a meal he had prepared. Anas said: I went with the Messenger of Allah ﷺ to that meal. The tailor brought him barley bread and a broth containing gourd. Anas said: “I saw the Messenger of Allah ﷺ searching for pieces of gourd around the dish, and from that day onward I continued to love gourd.”"]},"buhuth":{"en":["Al-Ḥāfiẓ Ibn Ḥajar said:","“Al-Bukhārī reconciled the hadith of ʿUmar ibn Abī Salamah with the hadith of Anas by understanding the permissibility to apply when the approval of those eating with him is known. He therefore entitled the chapter: ‘One Who Searches Around the Dish with His Companion When No Dislike Is Known from Him.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14449],"tks":"متفق عليه: رواه مالك (51)، والبخاري (2092)، ومسلم (2041: 144)، وزاد فيه: “دباء وقديد”."},{"num":14319,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَمْ يَجْتَمِعْ لَهُ غَدَاءٌ، وَلَا عَشَاءٌ مِنْ خُبْزٍ وَلَحْمٍ، إِلَّا عَلَى ضَفَفٍ."],"takhrij":"صحيح: رواه أحمد (13859)، والترمذي في الشمائل (138)، وأبو يعلى (3108)، وابن حبان في صحيحه (6359) كلهم من طريق عفان بن مسلم، حدثنا أبان بن يزيد، حدثنا قتادة، عن أنس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الاجتماع على الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (13859), al-Tirmidhī in al-Shamā’il (138), Abū Yaʿlā (3108), and Ibn Ḥibbān in his Ṣaḥīḥ (6359).","chapter_en":"Gathering Together to Eat","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik narrated: No lunch or dinner consisting of bread and meat was ever gathered for the Messenger of Allah ﷺ except upon ḍafaf."]},"buhuth":{"en":["Among the meanings given for “al-ḍafaf” is the gathering of people.","Thus, the meaning is that the Prophet ﷺ did not eat bread and meat alone, but ate together with other people."]}},"tuhfa":{},"full":1,"dr":1,"rep":[15184],"tks":"صحيح: رواه أحمد (13859)، والترمذي في الشمائل (138)، وأبو يعلى (3108)، وابن حبان في صحيحه (6359)."},{"num":14320,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ أَحَبَّ الطَّعَامِ إِلَى اللَّهِ مَا كَثُرَتْ عَلَيْهِ الْأَيْدِي."],"takhrij":"حسن: رواه أبو يعلى (2046)، والطبراني في الأوسط (7313) كلاهما من طريق خلاد بن أسلم، حدثنا عبد المجيد بن أبي رواد، حدثنا ابن جريج، عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب الاجتماع على الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Yaʿlā (2046) and al-Ṭabarānī in al-Muʿjam al-Awsaṭ (7313).","chapter_en":"Gathering Together to Eat","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “The food most beloved to Allah is that over which the greatest number of hands gather.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12901],"tks":"حسن: رواه أبو يعلى (2046)، والطبراني في الأوسط (7313)."},{"num":14321,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ:  رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُقْعِيًا يَأْكُلُ تَمْرًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2044: 148) من طريق حفص بن غياث، عن مصعب بن سُليم، حدثنا أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب صفة القعود للأكل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2044:148).","chapter_en":"The Manner of Sitting While Eating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik narrated: “I saw the Prophet ﷺ sitting in the iqʿāʾ posture while eating dates.”"]},"buhuth":{"en":["The word “muqʿiyan” means sitting on one’s buttocks while keeping the lower legs upright."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9567],"tks":"صحيح: رواه مسلم (2044: 148)."},{"num":14322,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ:  أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمْرٍ، فَجَعَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْسِمُهُ وَهُوَ مُحْتَفِزٌ، يَأْكُلُ مِنْهُ أَكْلًا ذَرِيعًا، وَفِي رِوَايَةِ: زُهَيْرٍ: أَكْلًا حَثِيثًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2044: 149) من طريق سفيان بن عيينة، عن مصعب بن سليم، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب صفة القعود للأكل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2044:149).","chapter_en":"The Manner of Sitting While Eating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Anas narrated: Dates were brought to the Messenger of Allah ﷺ, and the Prophet ﷺ began distributing them while sitting in a raised, ready-to-move posture, eating them quickly. In another narration: “Eating them hurriedly.”"]},"buhuth":{"en":["“It is with the letter zāy and means that he was sitting in a hurried, ready-to-rise posture, not fully settled in his sitting. It has the same meaning as the wording ‘sitting in the iqʿāʾ posture.’ It also corresponds to the statement of the Prophet ﷺ in another hadith in Ṣaḥīḥ al-Bukhārī and elsewhere: ‘I do not eat while reclining,’ according to the explanation of Imām al-Khaṭṭābī. He said that reclining here means being firmly settled while sitting, such as sitting cross-legged or in a similar manner while leaning upon cushioning beneath oneself. He said that anyone sitting firmly upon a cushion is considered to be reclining. The meaning is: I do not eat like one who wishes to consume a great quantity of food and therefore seats himself comfortably for it; rather, I sit ready to rise and eat only a little.”","That was because he was sitting ready to rise due to another matter that occupied him, so he ate quickly in order to satisfy his immediate need, remove his hunger, and then proceed to that task."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2044: 149)."},{"num":14323,"demo":false,"sanad":"","matn":["عَنْ أَبِي جُحَيْفَةَ قَالَ: كُنْتُ عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ لِرَجُلٍ عِنْدَهُ: لاَ آكُلُ وَأَنَا مُتَّكِئٌ. وَفِي لفظ: لاَ آكُلُ مُتَّكِئًا."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5399) عن عثمان بن أبي شيبة، أخبرنا جرير، عن منصور، عن علي بن الأقمر، عن أبي جحيفة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأكل متكئًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5399), with the other wording at (5398).","chapter_en":"What Has Been Narrated Concerning Eating While Reclining","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abū Juḥayfah narrated: I was with the Prophet ﷺ when he said to a man who was with him: “I do not eat while reclining.” In another wording: “I do not eat reclining.”"]},"buhuth":{"en":["The scholars differed concerning the meaning of reclining.","It was said that it means settling oneself comfortably in any posture for the purpose of eating.","It was also said that it means leaning onto one side.","And it was said that it means leaning upon one’s left hand on the ground.","They also differed concerning the ruling on eating while reclining.","Ibn al-Qāṣ claimed that avoiding it was among the special characteristics of the Prophet ﷺ.","Al-Bayhaqī responded that it may also be disliked for others because it is an action associated with people who display grandeur, originally taken from the kings of the Persians.","He said that if a person has some condition preventing him from eating except while reclining, then there is no dislike in doing so.","Al-Ḥāfiẓ Ibn Ḥajar said:","“There is room for criticism in interpreting it that way. Ibn Abī Shaybah narrated from Ibn ʿAbbās, Khālid ibn al-Walīd, ʿUbaydah al-Salmānī, Muḥammad ibn Sīrīn, ʿAṭāʾ ibn Yasār, and al-Zuhrī that they considered it permissible without restriction…”","Fatḥ al-Bārī (9/541–542)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5399)، واللفظ الآخر bukhari(5398)."},{"num":14324,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عمرو بْنِ الْعَاصِ عَنْ أَبِيهِ، قَالَ: مَا رُئِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْكُلُ مُتَّكِئًا قَطُّ، وَلاَ يَطَأُ عَقِبَهُ رَجُلاَنِ."],"takhrij":"حسن: رواه أبو داود (3770)، وابن ماجه (244)، وأحمد (6549) كلهم من طريق حماد بن سلمة، عن ثابت البناني، عن شعيب بن عبد الله بن عمرو، عن أبيه فذكره. وإسناده حسن من أجل شعيب بن عبد الله بن عمرو، وهو شعيب بن محمد بن عبد الله بن عمرو.","grade":"حسن","chapter_ar":"باب ما جاء في الأكل متكئًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3770), Ibn Mājah (244), and Aḥmad (6549).","chapter_en":"What Has Been Narrated Concerning Eating While Reclining","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated: “The Messenger of Allah ﷺ was never seen eating while reclining, nor would two men walk directly behind his heels.”"]},"buhuth":{"en":["The words:","“nor would two men walk directly behind his heels”","mean that two men would not walk behind him in the manner of attendants following a superior; rather, the Prophet ﷺ did not place himself ahead of his Companions while walking."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3770)، وابن ماجه (244)، وأحمد (6549)."},{"num":14325,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن بُسْرٍ، قَالَ: أَهْدَيْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةً، فَجَثَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رُكْبَتَيْهِ يَأْكُلُ، فَقَالَ أَعْرَابِيٌّ: مَا هَذِهِ الْجِلْسَةُ؟ فَقَالَ: إِنَّ اللَّهَ جَعَلَنِي عَبْدًا كَرِيمًا، وَلَمْ يَجْعَلْنِي جَبَّارًا عَنِيدًا."],"takhrij":"حسن: رواه ابن ماجه (3263)، وأبو داود (3773) كلاهما عن عمرو بن عثمان بن سعيد بن كثير بن دينار الحمصي قال: حدثنا أبي قال: أنبأنا محمد بن عبدالرحمن بن عرق قال: حدثنا عبد الله بن بسر، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في الأكل متكئًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3263) and Abū Dāwūd (3773).","chapter_en":"What Has Been Narrated Concerning Eating While Reclining","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated: A sheep was presented to the Prophet ﷺ. The Messenger of Allah ﷺ knelt upon his knees and began eating. A Bedouin asked: “What kind of sitting posture is this?” He replied: “Allah has made me a noble servant and has not made me an arrogant, stubborn tyrant.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3263)، وأبو داود (3773)."},{"num":14326,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِنَّ الشَّيْطَانَ يَحْضُرُ أَحَدَكُمْ عِنْدَ كُلِّ شَيْءٍ مِنْ شَأْنِهِ، حَتَّى يَحْضُرَهُ عِنْدَ طَعَامِهِ، فَإِذَا سَقَطَتْ مِنْ أَحَدِكُمُ اللُّقْمَةُ، فَلْيُمِطْ مَا كَانَ بِهَا مِنْ أَذًى، ثُمَّ لْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ، فَإِذَا فَرَغَ فَلْيَلْعَقْ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ تَكُونُ الْبَرَكَةُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2033: 135) عن عثمان بن أبي شيبة، حدثنا جرير، عن الأعمش، عن أبي سفيان، عن جابر، قال: فذكره.","grade":"صحيح","chapter_ar":"باب إذا سقطت اللقمة فلا تتركها للشيطان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2033:135).","chapter_en":"If a Morsel Falls, Do Not Leave It for Satan","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Jābir narrated: I heard the Prophet ﷺ say: “Satan attends one of you in every matter of his, even at his food. If a morsel falls from one of you, let him remove whatever dirt has gotten onto it, then eat it and not leave it for Satan. When he finishes, let him lick his fingers, for he does not know in which part of his food the blessing lies.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2033: 135)."},{"num":14327,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ إِذَا أَكَلَ طَعَامًا لَعِقَ أَصَابِعَهُ الثَّلَاثَ، قَالَ: وَقَالَ: إِذَا سَقَطَتْ لُقْمَةُ أَحَدِكُمْ فَلْيُمِطْ عَنْهَا الْأَذَى وَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ. وَأَمَرَنَا أَنْ نَسْلُتَ الْقَصْعَةَ، قَالَ: فَإِنَّكُمْ لَا تَدْرُونَ فِي أَيِّ طَعَامِكُمُ الْبَرَكَةُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2034) من طريق بهز، حدثنا حماد بن سلمة، حدثنا ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب إذا سقطت اللقمة فلا تتركها للشيطان","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2034).","chapter_en":"If a Morsel Falls, Do Not Leave It for Satan","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Anas narrated: When the Messenger of Allah ﷺ ate food, he would lick his three fingers. He also said: “If a morsel belonging to one of you falls, let him remove the dirt from it and eat it, and not leave it for Satan.” He also commanded us to wipe the dish clean, saying: “For you do not know in which part of your food the blessing lies.”"]}},"tuhfa":{},"full":1,"rep":[9565],"tks":"صحيح: رواه مسلم (2034)."},{"num":14328,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا أَكَلَ أَحَدُكُمْ مِنَ الطَّعَامِ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَهَا، أَوْ يُلْعِقَهَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5456)، ومسلم في الأشربة (2031: 129) كلاهما من طريق سفيان (هو ابن عيينة)، عن عمرو بن دينار، عن عطاء، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في لعق الأصابع والصحفة والتماس بركة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5456) and Muslim (2031:129).","chapter_en":"What Has Been Narrated Concerning Licking the Fingers and the Dish and Seeking the Blessing of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “When one of you eats food, he should not wipe his hand until he has licked it himself or had someone else lick it.”"]},"buhuth":{"en":["The expression:","“or had someone else lick it”","refers, for example, to a servant, spouse, children, or someone who does not find the remnants of his food distasteful."]}},"tuhfa":{},"full":1,"dr":1,"rep":[14332],"tks":"متفق عليه: رواه البخاري (5456)، ومسلم (2031: 129)."},{"num":14329,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِلَعْقِ الْأَصَابِعِ وَالصَّحْفَةِ، وَقَالَ: إِنَّكُمْ لَا تَدْرُونَ فِي أَيِّهِ الْبَرَكَةُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2033: 133) عن أبي بكر بن أبي شيبة، حدثنا سفيان بن عيينة، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في لعق الأصابع والصحفة والتماس بركة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2033:133).","chapter_en":"What Has Been Narrated Concerning Licking the Fingers and the Dish and Seeking the Blessing of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Jābir narrated: The Prophet ﷺ commanded that the fingers and the dish be licked clean and said: “You do not know in which part of it the blessing lies.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2033: 133)."},{"num":14330,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  إِذَا أَكَلَ أَحَدُكُمْ فَلْيَلْعَقْ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيَّتِهِنَّ الْبَرَكَةُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2035) عن محمد بن حاتم، حدثنا بهز، حدثنا وهيب، حدثنا سهيل، عن أبيه، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في لعق الأصابع والصحفة والتماس بركة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2035).","chapter_en":"What Has Been Narrated Concerning Licking the Fingers and the Dish and Seeking the Blessing of the Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “When one of you eats, let him lick his fingers, for he does not know in which of them the blessing lies.”"]}},"tuhfa":{},"full":1,"rep":[9566],"tks":"صحيح: رواه مسلم (2035)."},{"num":14331,"demo":false,"sanad":"","matn":["عن كعب بن مالك، قال: رأيت النبي صلى الله عليه وسلم يلعق أصابعه الثلاث من الطعام. وفي رواية: كان رسول الله صلى الله عليه وسلم يأكل بثلاث أصابع، ويلعق يده قبل أن يمسحها."],"takhrij":"صحيح: رواه مسلم في الأشربة (2032: 131) من طريق ابن مهدي، عن سفيان، عن سعد بن إبراهيم، عن ابن كعب بن مالك، عن أبيه، قال: فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الأكل بثلاثة أصابع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2032:131).","chapter_en":"The Recommendation to Eat with Three Fingers","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["Kaʿb ibn Mālik narrated: “I saw the Prophet ﷺ licking his three fingers after eating.” In another narration: “The Messenger of Allah ﷺ used to eat with three fingers and would lick his hand before wiping it.”"]},"buhuth":{"en":["It is recommended to eat with three fingers when the food is solid. If the nature of the food requires otherwise, it is permissible to eat using all five fingers."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2032: 131)."},{"num":14332,"demo":false,"sanad":"","matn":["عن ابْنِ عَبَّاسٍ، يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا أَكَلَ أَحَدُكُمْ مِنَ الطَّعَامِ فَلَا يَمْسَحْ يَدَهُ حَتَّى يَلْعَقَهَا، أَوْ يُلْعِقَهَا."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5456)، ومسلم في الأشربة (2031: 129) كلاهما من طريق سفيان (هو ابن عيينة)، عن عمرو بن دينار، عن عطاء، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب في المسح بالمنديل بعد لعق الأصابع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5456) and Muslim (2031:129).","chapter_en":"Wiping with a Cloth After Licking the Fingers","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Messenger of Allah ﷺ said: “When one of you eats food, he should not wipe his hand until he has licked it himself or had someone else lick it.”"]}},"tuhfa":{},"full":1,"rep":[14328],"tks":"متفق عليه: رواه البخاري (5456)، ومسلم (2031: 129)."},{"num":14333,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا أَنَّهُ سَأَلَهُ عَنِ الْوُضُوءِ مِمَّا مَسَّتِ النَّارُ، فَقَالَ: لاَ، قَدْ كُنَّا زَمَانَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ نَجِدُ مِثْلَ ذَلِكَ مِنَ الطَّعَامِ إِلاَّ قَلِيلاً، فَإِذَا نَحْنُ وَجَدْنَاهُ لَمْ يَكُنْ لَنَا مَنَادِيلُ، إِلاَّ أَكُفَّنَا وَسَوَاعِدَنَا وَأَقْدَامَنَا، ثُمَّ نُصَلِّي وَلاَ نَتَوَضَّأُ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5457) عن إبراهيم بن المنذر، حدثني محمد بن فليح، حدثني أبي، عن سعيد بن الحارث، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب في المسح بالمنديل بعد لعق الأصابع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5457).","chapter_en":"Wiping with a Cloth After Licking the Fingers","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh was asked about performing wuḍūʾ after eating food touched by fire. He replied: “No. During the time of the Prophet ﷺ, we rarely found such food. When we did find it, we had no napkins except our palms, forearms, and feet. Then we would pray without performing wuḍūʾ.”"]},"buhuth":{"en":["Regarding the words:","“We had no napkins,”","Ibn Ḥajar said that the apparent implication is that if they had possessed napkins, they would have wiped their hands with them.","Thus, the hadith prohibiting wiping the hand with a napkin—meaning the previous hadith of Jābir in Muslim stating that one should not wipe his hand until he has licked his fingers—is understood to apply when there is food remaining upon them.","The ruling is likewise applicable if a person wipes his hand with something other than a napkin.","Fatḥ al-Bārī (9/577)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5457)."},{"num":14334,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ فَلْيَأْخُذْهَا، فَلْيُمِطْ مَا كَانَ بِهَا مِنْ أَذًى وَلْيَأْكُلْهَا، وَلَا يَدَعْهَا لِلشَّيْطَانِ، وَلَا يَمْسَحْ يَدَهُ بِالْمِنْدِيلِ حَتَّى يَلْعَقَ أَصَابِعَهُ، فَإِنَّهُ لَا يَدْرِي فِي أَيِّ طَعَامِهِ الْبَرَكَةُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2033: 134) عن محمد بن عبد الله بن نمير، حدثنا أبي، حدثنا سفيان، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب في المسح بالمنديل بعد لعق الأصابع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2033:134).","chapter_en":"Wiping with a Cloth After Licking the Fingers","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “If a morsel belonging to one of you falls, let him pick it up, remove whatever dirt is upon it, and eat it. He should not leave it for Satan. And he should not wipe his hand with a napkin until he has licked his fingers, for he does not know in which part of his food the blessing lies.”"]},"buhuth":{"ar":["أحاديث هذه الأبواب تشتمل على كثير من السنن، منها:","١- لعق الأصابع بعد أكل الطعام وقبل مسحها بالمنديل أو غسلها.","٢- فإن لم يلعقها فليُلعق غيره مثل الزوجة أو الأولاد أو الجارية أو من لا يرى سؤره مستقذرًا.","٣- لعق الأصابع ثلاث مرات.","٤- أكله بثلاث أصابع.","٥- لعق الصحفة.","٦- إذا وقعت اللقمة فليأخذها ولا يتركها للشيطان، فإن كان بها أذى فليمطه.","٧- أمرنا بهذه الأحكام لأننا لا نعرف أين البركة في الطعام: فيما أكلنا، أو فيما بقي في الأصابع، أو فيما بقي في القصعة، أو فيما سقط على الأرض.","٨- وفيه التحذير من ملازمة الشيطان له في تصرفاته، فيجب أن يحترز منه ولا يمكنه من التلاعب به، ويحصل ذلك بالتسمية عند الأكل."],"en":["The Hadiths of These Chapters Contain Many Sunnahs, Including:","Licking the fingers after eating and before wiping them with a napkin or washing them.","If a person does not lick them himself, he may allow someone else to do so, such as a spouse, children, a servant girl, or someone who does not find his food remnants distasteful.","Licking the fingers three times.","Eating with three fingers.","Licking the dish clean.","If a morsel falls, one should pick it up and not leave it for Satan. If there is dirt upon it, it should be removed.","We have been commanded with these practices because we do not know where the blessing in the food lies: whether in what we have eaten, what remains upon the fingers, what remains in the dish, or what has fallen to the ground.","These hadiths also warn that Satan accompanies a person in his affairs. One must therefore guard himself against Satan and not allow him to interfere with him. This is accomplished by mentioning the Name of Allah when eating."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2033: 134)."},{"num":14335,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ،  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ مِنَ الْخَلَاءِ، فَأُتِيَ بِطَعَامٍ، فَذَكَرُوا لَهُ الْوُضُوءَ، فَقَالَ: أُرِيدُ أَنْ أُصَلِّيَ فَأَتَوَضَّأَ."],"takhrij":"صحيح: رواه مسلم في الحيض (374) من طرق عن حماد بن زيد، عن عمرو بن دينار، عن سعيد بن الحويرث، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب لا وضوء للطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (374).","chapter_en":"Wuḍūʾ Is Not Required Because of Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ came out after relieving himself and food was brought to him. Wuḍūʾ was mentioned to him, so he said: “Am I intending to pray so that I should perform wuḍūʾ?”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (374)."},{"num":14336,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَامَ وَفِي يَدِهِ غَمَرٌ، وَلَمْ يَغْسِلْهُ، فَأَصَابَهُ شَىْءٌ، فَلاَ يَلُومَنَّ إِلاَّ نَفْسَهُ."],"takhrij":"صحيح: رواه أبو داود (3852)، وابن ماجه (3297)، والبخاري في الأدب المفرد (1220)، وأحمد (7569)، وصحّحه ابن حبان (5521)، والبيهقي في السنن (14606) كلهم من حديث سهيل بن ابي صالح، عن أبيه، عن أبي هريرة فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب غسل اليدين بعد الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3852), Ibn Mājah (3297), and Aḥmad (7569).","chapter_en":"Washing the Hands After Eating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever goes to sleep while food grease or residue remains on his hand and he does not wash it, then something happens to him, let him blame no one but himself.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3852)، وابن ماجه (3297)، وأحمد (7569)."},{"num":14337,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ نَامَ، وَبِيَدِهِ غَمَرٌ قَبْلَ أَنْ يَغْسِلَهُ، فَأَصَابَهُ شَيْءٌ، فَلا يَلُومَنَّ إِلا نَفْسَهُ."],"takhrij":"حسن: رواه البخاري في الأدب المفرد (1219)، والطبراني في الأوسط –مجمع البحرين (4052) كلاهما من طريق أحمد بن إشكاب، حدثنا محمد بن فضيل، عن ليث، عن محمد بن عمرو بن عطاء، عن ابن عباس قال: فذكره.","grade":"حسن","chapter_ar":"باب غسل اليدين بعد الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bukhārī in al-Adab al-Mufrad (1219) and ʿAbd al-Razzāq (19840).","chapter_en":"Washing the Hands After Eating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “Whoever goes to sleep with food residue on his hand before washing it, and then some harm befalls him, let him blame no one but himself.”"]},"buhuth":{"en":["The words:","“with food residue on his hand”","refer to remnants of food or grease remaining upon the hand which may cause harm or discomfort.","For this reason, it is recommended to wash the hands after eating."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه البخاري في الأدب المفرد (1219)، وعبد الرزاق (19840)."},{"num":14338,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: مَا عَابَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا قَطُّ، إِنِ اشْتَهَاهُ أَكَلَهُ، وَإِنْ كَرِهَهُ تَرَكَهُ.","وفي رواية: كان إذا اشتهاه أكله، وإنْ لم يشتهه سكت."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5409)، ومسلم في الأشربة (2064: 187) كلاهما من طريق الأعمش، عن أبي حازم، عن ابي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب لا يُعاب الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5409) and Muslim (2064:187).","chapter_en":"Food Should Not Be Criticized","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah narrated: “The Prophet ﷺ never criticized any food. If he desired it, he ate it, and if he disliked it, he left it.” In another narration: “If he desired it, he ate it, and if he did not desire it, he remained silent.”"]},"buhuth":{"en":["Mentioning that food needs more pepper, salt, or spices is not considered criticizing the food, because the intention is to improve it rather than to disparage it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5409)، ومسلم (2064: 187)."},{"num":14339,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامُ الاِثْنَيْنِ كَافِي الثَّلاَثَةِ، وَطَعَامُ الثَّلاَثَةِ كَافِي الأَرْبَعَةِ."],"takhrij":"متفق عليه: رواه مالك في صفة النبي صلى الله عليه وسلم (20) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الأطعمة (5392)، ومسلم في الأشربة (2058) كلاهما من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب طعام الواحد يكفي اثنين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ṣifat al-Nabī ﷺ (20), al-Bukhārī (5392), and Muslim (2058).","chapter_en":"The Food of One Is Sufficient for Two","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The food of two is sufficient for three, and the food of three is sufficient for four.”"]}},"tuhfa":{},"full":1,"rep":[12903],"tks":"متفق عليه: رواه مالك (20)، والبخاري (5392)، ومسلم (2058)."},{"num":14340,"demo":false,"sanad":"","matn":["عن جابر قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  طَعَامُ الْوَاحِدِ يَكْفِي الِاثْنَيْنِ، وَطَعَامُ الِاثْنَيْنِ يَكْفِي الْأَرْبَعَةَ، وَطَعَامُ الْأَرْبَعَةِ يَكْفِي الثَّمَانِيَةَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2059: 179) من طريق روح، حدثنا ابن جريج، أخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب طعام الواحد يكفي اثنين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2059:179).","chapter_en":"The Food of One Is Sufficient for Two","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Jābir narrated: I heard the Messenger of Allah ﷺ say: “The food of one is sufficient for two, the food of two is sufficient for four, and the food of four is sufficient for eight.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2059: 179)."},{"num":14341,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَأْكُلُ الْمُسْلِمُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"متفق عليه: رواه مالك في صفة النبي صلى الله عليه وسلم (9) عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره. ورواه البخاري في الأطعمة (5396) من طريق مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ṣifat al-Nabī ﷺ (9), al-Bukhārī (5396), and Muslim (2060).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “The Muslim eats with one intestine, while the disbeliever eats with seven intestines.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13282],"tks":"متفق عليه: رواه مالك (9)، والبخاري (5396)، ومسلم (2060)."},{"num":14342,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَجُلاً، كَانَ يَأْكُلُ أَكْلاً كَثِيرًا، فَأَسْلَمَ، فَكَانَ يَأْكُلُ أَكْلاً قَلِيلاً، فَذُكِرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: إِنَّ الْمُؤْمِنَ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5397) عن سليمان بن حرب، حدثنا شعبة، عن عدي بن ثابت، عن أبي حازم، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5397).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated: A man used to eat a great deal. Then he embraced Islam and began eating only a little. This was mentioned to the Prophet ﷺ, and he said: “The believer eats with one intestine, while the disbeliever eats with seven intestines.”"]}},"tuhfa":{},"full":1,"rep":[13284],"tks":"صحيح: رواه البخاري (5397)."},{"num":14343,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَافَهُ ضَيْفٌ وَهُوَ كَافِرٌ، فَأَمَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ فَحُلِبَتْ، فَشَرِبَ حِلَابَهَا، ثُمَّ أُخْرَى فَشَرِبَهُ، ثُمَّ أُخْرَى فَشَرِبَهُ، حَتَّى شَرِبَ حِلَابَ سَبْعِ شِيَاهٍ، ثُمَّ إِنَّهُ أَصْبَحَ، فَأَسْلَمَ، فَأَمَرَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِشَاةٍ فَشَرِبَ حِلَابَهَا، ثُمَّ أَمَرَ بِأُخْرَى، فَلَمْ يَسْتَتِمَّهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْمُؤْمِنُ يَشْرَبُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَشْرَبُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"صحيح: رواه مالك في صفة النبي صلى الله عليه وسلم (10) عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره. ورواه مسلم في الأشربة (2063: 186) من طريق مالك به مثله.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik in Ṣifat al-Nabī ﷺ (10) and Muslim (2063:186).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ hosted a disbelieving guest. The Messenger of Allah ﷺ ordered that a sheep be milked for him, and the man drank all of its milk. Then another was milked and he drank its milk, then another, until he had drunk the milk of seven sheep. The next morning he embraced Islam. The Messenger of Allah ﷺ ordered a sheep to be milked for him, and he drank its milk. Then another was milked for him, but he could not finish it. The Messenger of Allah ﷺ said: “The believer drinks with one intestine, while the disbeliever drinks with seven intestines.”"]}},"tuhfa":{},"full":1,"rep":[13283,14468],"tks":"صحيح: رواه مالك (10)، ومسلم (2063: 186)."},{"num":14344,"demo":false,"sanad":"","matn":["عَنْ نَافِعٍ، قَالَ: كَانَ ابْنُ عُمَرَ، لاَ يَأْكُلُ حَتَّى يُؤْتَى بِمِسْكِينٍ يَأْكُلُ مَعَهُ، فَأَدْخَلْتُ رَجُلاً يَأْكُلُ مَعَهُ فَأَكَلَ كَثِيرًا، فَقَالَ: يَا نَافِعُ، لاَ تُدْخِلْ هَذَا عَلَىَّ، سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5393)، ومسلم في الأشربة (2060: 183) كلاهما من طريق شعبة، عن واقد بن محمد بن زيد، عن نافع قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5393) and Muslim (2060:183).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Nāfiʿ narrated: Ibn ʿUmar would not eat until a poor person was brought to eat with him. I once brought a man to eat with him, and the man ate a great deal. Ibn ʿUmar said: “O Nāfiʿ, do not bring this man to me again. I heard the Prophet ﷺ say: ‘The believer eats with one intestine, while the disbeliever eats with seven intestines.’”"]}},"tuhfa":{},"full":1,"rep":[13287],"tks":"متفق عليه: رواه البخاري (5393)، ومسلم (2060: 183)."},{"num":14345,"demo":false,"sanad":"","matn":["عَنْ عَمْرٍو، قَالَ: كَانَ أَبُو نَهِيكٍ رَجُلاً أَكُولاً، فَقَالَ لَهُ ابْنُ عُمَرَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْكَافِرَ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ. فَقَالَ: فَأَنَا أُومِنُ بِاللَّهِ وَرَسُولِهِ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5395) عن علي بن عبد الله، حدثنا سفيان، عن عمرو (هو ابن دينار) قال: فذكره.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5395).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["ʿAmr ibn Dīnār narrated: Abū Nuhayk was a man who ate a great deal. Ibn ʿUmar said to him: “The Messenger of Allah ﷺ said: ‘The disbeliever eats with seven intestines.’” Abū Nuhayk replied: “But I believe in Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"rep":[13288],"tks":"صحيح: رواه البخاري (5395)."},{"num":14346,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، وَابْنِ عُمَرَ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2061: 184) عن محمد بن المثنى، حدثنا عبد الرحمن، عن سفيان، عن أبي الزبير، عن جابر، وابن عمر فذكراه.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2061:184).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Jābir and Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “The believer eats with one intestine, while the disbeliever eats with seven intestines.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13285],"tks":"صحيح: رواه مسلم (2061: 184)."},{"num":14347,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  الْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ، وَالْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2062: 185) عن أبي كريب محمد بن العلاء، حدثنا أبو أسامة، حدثنا بريد، عن جده، عن أبي موسى فذكره.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2062:185).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Abū Mūsā narrated that the Prophet ﷺ said: “The believer eats with one intestine, while the disbeliever eats with seven intestines.”"]}},"tuhfa":{},"full":1,"rep":[13286],"tks":"صحيح: رواه مسلم (2062: 185)."},{"num":14348,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ مِنْ جُهَيْنَةَ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ الْكَافِرَ يَشْرَبُ فِي سَبْعَةِ أَمْعَاءٍ، وَإِنَّ الْمُؤْمِنَ يَشْرَبُ فِي مِعًى وَاحِدٍ."],"takhrij":"صحيح: رواه أحمد (23135) عن أبي سلمة الخزاعي، أخبرنا سليمان يعني بن بلال، عن عمرو بن يحيى بن عمارة، عن سعد بن يسار، عن رجل من جهينة قال: فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23135).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["A man from Juhaynah narrated: I heard the Prophet ﷺ say: “The disbeliever drinks with seven intestines, while the believer drinks with one intestine.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (23135)."},{"num":14349,"demo":false,"sanad":"","matn":["عَنْ مَيْمُونَةَ بِنْتِ الْحَارِثِ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الْكَافِرُ يَأْكُلُ فِي سَبْعَةِ أَمْعَاءٍ، وَالْمُؤْمِنُ يَأْكُلُ فِي مِعًى وَاحِدٍ."],"takhrij":"صحيح: رواه أحمد (26845) عن وكيع قال: سمعت الأعمش قال: أظن أبا خالد الوالبي، ذكره عن ميمونة بنت الحارث قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب المؤمن يأكل ويشرب في معى واحد، والكافر يأكل في سبعة أمعاء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (26845).","chapter_en":"The Believer Eats and Drinks with One Intestine, While the Disbeliever Eats with Seven Intestines","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["Maymūnah bint al-Ḥārith narrated that the Messenger of Allah ﷺ said: “The disbeliever eats with seven intestines, while the believer eats with one intestine.”"]},"buhuth":{"en":["Meaning of the Statement: “The Believer Eats with One Intestine…”","It has been said that this hadith originally concerned a particular man who used to eat and drink a great deal, so this example was given concerning him.","It has also been observed that when a believer mentions Allah’s Name over his food, Satan does not share in it with him. The disbeliever, by contrast, does not mention Allah’s Name when eating, so Satan shares in his food and he does not become satisfied.","This is illustrated by the disbelieving guest hosted by the Messenger of Allah ﷺ, who drank the milk of seven sheep. When he embraced Islam the following day, he became satisfied with the milk of a single sheep.","The hadith also encourages moderation in eating and drinking because this is more beneficial for the body. Excessive eating and drinking, besides being harmful to the body, resembles the conduct described here concerning disbelievers. For this reason, Ibn ʿUmar did not wish the poor man who had eaten excessively to be brought to him again.","The expression:","“seven intestines”","conveys extreme excess in eating.","The disbeliever’s primary concern is enjoyment of worldly life, whereas the believer eats in order to preserve his life, remembering Allah and thanking Him for the blessings of this world.","For this reason, the Sacred Law recommends allocating one-third of the stomach for food, one-third for drink, and one-third for breathing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (26845)."},{"num":14350,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ يَقُولُ: قَالَ أَبُو طَلْحَةَ لأُمِّ سُلَيْمٍ: لَقَدْ سَمِعْتُ صَوْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَعِيفًا، أَعْرِفُ فِيهِ الْجُوعَ، فَهَلْ عِنْدَكِ مِنْ شَيْءٍ؟ فَقَالَتِ: نَعَمْ، فَأَخْرَجَتْ أَقْرَاصًا مِنْ شَعِيرٍ، ثُمَّ أخذت خِمَارًا لَهَا، فَلَفَّتِ الْخُبْزَ بِبَعْضِهِ، ثُمَّ دَسَّتْهُ تَحْتَ يدي، وَرَدَّتْنِي بِبَعْضِهِ، ثُمَّ أَرْسَلَتْنِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، قَالَ: فَذَهَبْتُ بِهِ، فَوَجَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي الْمَسْجِدِ، وَمَعَهُ النَّاسُ، فَقُمْتُ عَلَيْهِمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَرْسَلَكَ أَبُو طَلْحَةَ؟ قَالَ: فَقُلْتُ: نَعَمْ، قَالَ: للطعام؟ قَالَ: فَقُلْتُ: نَعَمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَنْ مَعَهُ: قُومُوا، قَالَ: فَانْطَلَقَ، وَانْطَلَقْتُ بَيْنَ أَيْدِيهِمْ حَتَّى جِئْتُ أَبَا طَلْحَةَ فأخبرته، فَقَالَ أَبُو طَلْحَةَ: يَا أُمَّ سُلَيْمٍ، قَدْ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ، وَلَيْسَ عِنْدَنَا مِنَ الطَّعَامِ مَا نُطْعِمُهُمْ، فَقَالَتِ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَانْطَلَقَ أَبُو طَلْحَةَ، حَتَّى لَقِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو طَلْحَةَ مَعَهُ، حَتَّى دَخَلاَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلُمِّي يَا أُمَّ سُلَيْمٍ مَا عِنْدَكِ؟ فَأَتَتْ بِذَلِكَ الْخُبْزِ، فَأَمَرَ بِهِ رسول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفُتَّ، وَعَصَرَتْ عَلَيْهِ أُمُّ سُلَيْمٍ عُكَّةً لَهَا فآدمته، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَاءَ اللَّهُ أَنْ يَقُولَ، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ، فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا، ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ، فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا، ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ، فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا، ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ، فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا، ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ، حَتَّى آكُلَ الْقَوْمُ كُلُّهُمْ وَشَبِعُوا، وَالْقَوْمُ سَبْعُونَ رَجُلاً أَوْ ثَمَانُونَ رَجُلاً."],"takhrij":"متفق عليه: رواه مالك في صفة النبي صلى الله عليه وسلم (19) عن إسحاق بن عبدالله بن أبي طلحة، أنه سمع أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل حتى الشبع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in Ṣifat al-Nabī ﷺ (19), al-Bukhārī (5381), and Muslim (2040:142).","chapter_en":"What Has Been Narrated Concerning Eating Until Full","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Mālik narrated: Abū Ṭalḥah said to Umm Sulaym: “I have heard the voice of the Messenger of Allah ﷺ sounding weak, and I can recognize hunger in it. Do you have anything?” She replied: “Yes.” She brought out some barley loaves, then took a veil of hers, wrapped some of the bread in part of it, tucked it under my arm, wrapped the rest of the cloth around me, and sent me to the Messenger of Allah ﷺ. I took it to him and found the Messenger of Allah ﷺ sitting in the mosque with some people. I stood before them. The Messenger of Allah ﷺ asked: “Did Abū Ṭalḥah send you?” I replied: “Yes.” He asked: “For food?” I replied: “Yes.” The Messenger of Allah ﷺ said to those with him: “Get up.” So he set out, and I went ahead of them until I reached Abū Ṭalḥah and informed him. Abū Ṭalḥah said: “O Umm Sulaym, the Messenger of Allah ﷺ has come with the people, but we do not have enough food to feed them.” She replied: “Allah and His Messenger know best.” Abū Ṭalḥah went out to meet the Messenger of Allah ﷺ, and the Messenger of Allah ﷺ came with him until they entered. The Messenger of Allah ﷺ said: “Bring what you have, O Umm Sulaym.” She brought the bread. The Messenger of Allah ﷺ ordered that it be crumbled, and Umm Sulaym squeezed some fat from a leather container over it to season it. Then the Messenger of Allah ﷺ said whatever Allah willed him to say, and then said: “Give permission to ten.” Ten were admitted and ate until they were full, then they left. He then said: “Give permission to ten.” Another ten entered and ate until they were full, then left. He continued doing this until all of the people had eaten and become full. There were seventy or eighty men."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (19)، والبخاري (5381)، ومسلم (2040: 142)."},{"num":14351,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثِينَ وَمِائَةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ مَعَ أَحَدٍ مِنْكُمْ طَعَامٌ. فَإِذَا مَعَ رَجُلٍ صَاعٌ مِنْ طَعَامٍ أَوْ نَحْوُهُ، فَعُجِنَ، ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ مُشْعَانٌّ طَوِيلٌ، بِغَنَمٍ يَسُوقُهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَبَيْعٌ أَمْ عَطِيَّةٌ أَوْ ـ قَالَ: ـ هِبَةٌ. قَالَ: لاَ، بَلْ بَيْعٌ. قَالَ: فَاشْتَرَى مِنْهُ شَاةً فَصُنِعَتْ، فَأَمَرَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَوَادِ الْبَطْنِ يُشْوَى، وَايْمُ اللَّهِ، مَا مِنَ الثَّلاَثِينَ وَمِائَةٍ إِلاَّ قَدْ حَزَّ لَهُ حُزَّةً مِنْ سَوَادِ بَطْنِهَا، إِنْ كَانَ شَاهِدًا أَعْطَاهَا إِيَّاهُ، وَإِنْ كَانَ غَائِبًا خَبَأَهَا لَهُ، ثُمَّ جَعَلَ فِيهَا قَصْعَتَيْنِ، فَأَكَلْنَا أَجْمَعُونَ وَشَبِعْنَا، وَفَضَلَ فِي الْقَصْعَتَيْنِ، فَحَمَلْتُهُ عَلَى الْبَعِيرِ. أَوْ كَمَا قَالَ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5382)، ومسلم في الأشربة (2056) كلاهما من طريق المعتمر بن سليمان، حدثنا أبي، عن أبي عثمان، وحدّث أيضا عن عبد الرحمن بن أبي بكر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل حتى الشبع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5382) and Muslim (2056).","chapter_en":"What Has Been Narrated Concerning Eating Until Full","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Bakr narrated: We were with the Prophet ﷺ, one hundred and thirty of us. The Prophet ﷺ asked: “Does any one of you have food?” A man had approximately one ṣāʿ of food, so it was kneaded. Then a tall, disheveled polytheist came driving some sheep. The Prophet ﷺ asked him: “Are they for sale or a gift?” —or he said: “A donation?” The man replied: “No, they are for sale.” So the Prophet ﷺ purchased a sheep from him, and it was prepared. The Prophet of Allah ﷺ ordered that the dark meat from the abdomen be roasted. By Allah, not one of the one hundred and thirty people was left without receiving a piece of it. If a person was present, he gave him his share; if he was absent, he kept it for him. Then the food was placed into two large bowls. We all ate and became full, and some food still remained in the two bowls. I loaded what remained onto the camel—or words to that effect."]},"buhuth":{"en":["The expression “the dark part of the abdomen” means the liver, or the internal organs of the abdomen including the liver and other parts."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9681],"tks":"متفق عليه: رواه البخاري (5382)، ومسلم (2056)."},{"num":14352,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تُوُفِّيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ شَبِعْنَا مِنَ الأَسْوَدَيْنِ: التَّمْرِ وَالْمَاءِ. وَفِي لفظ: حِينَ شَبِعَ الناس."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5383)، ومسلم في الزهد (2875: 30) كلاهما من طريق منصور بن عبد الرحمن الحجبي، عن أمه صفية، عن عائشة قالت: فذكرته. واللفظ للبخاري واللفظ الآخر لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل حتى الشبع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5383) and Muslim (2875:30).","chapter_en":"What Has Been Narrated Concerning Eating Until Full","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["ʿĀ’ishah narrated: “The Prophet ﷺ passed away at a time when we had begun to eat our fill of the two dark things: dates and water.” In another wording: “when the people had begun to eat their fill.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5383)، ومسلم (2875: 30)."},{"num":14353,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ أَوْ لَيْلَةٍ، فَإِذَا هُوَ بِأَبِي بَكْرٍ، وَعُمَرَ، فَقَالَ: مَا أَخْرَجَكُمَا مِنْ بُيُوتِكُمَا هَذِهِ السَّاعَةَ؟. قَالَا: الْجُوعُ يَا رَسُولَ اللَّهِ. قَالَ: وَأَنَا، وَالَّذِي نَفْسِي بِيَدِهِ، لَأَخْرَجَنِي الَّذِي أَخْرَجَكُمَا، قُومُوا. فَقَامُوا مَعَهُ، فَأَتَى رَجُلًا مِنَ الْأَنْصَارِ فَإِذَا هُوَ لَيْسَ فِي بَيْتِهِ، فَلَمَّا رَأَتْهُ الْمَرْأَةُ، قَالَتْ: مَرْحَبًا وَأَهْلًا، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيْنَ فُلَانٌ؟ قَالَتْ: ذَهَبَ يَسْتَعْذِبُ لَنَا مِنَ الْمَاءِ، إِذْ جَاءَ الْأَنْصَارِيُّ، فَنَظَرَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَصَاحِبَيْهِ، ثُمَّ قَالَ: الْحَمْدُ لِلهِ، مَا أَحَدٌ الْيَوْمَ أَكْرَمَ أَضْيَافًا مِنِّي. قَالَ: فَانْطَلَقَ، فَجَاءَهُمْ بِعِذْقٍ فِيهِ بُسْرٌ وَتَمْرٌ وَرُطَبٌ، فَقَالَ: كُلُوا مِنْ هَذِهِ. وَأَخَذَ الْمُدْيَةَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِيَّاكَ، وَالْحَلُوبَ. فَذَبَحَ لَهُمْ، فَأَكَلُوا مِنَ الشَّاةِ، وَمِنْ ذَلِكَ الْعِذْقِ، وَشَرِبُوا، فَلَمَّا أَنْ شَبِعُوا وَرَوُوا، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ، وَعُمَرَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَتُسْأَلُنَّ عَنْ هَذَا النَّعِيمِ يَوْمَ الْقِيَامَةِ، أَخْرَجَكُمْ مِنْ بُيُوتِكُمُ الْجُوعُ، ثُمَّ لَمْ تَرْجِعُوا حَتَّى أَصَابَكُمْ هَذَا النَّعِيمُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2038) عن أبي بكر بن أبي شيبة، حدثنا خلف بن خليفة، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة، قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأكل حتى الشبع","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2038).","chapter_en":"What Has Been Narrated Concerning Eating Until Full","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ went out one day—or one night—and came across Abū Bakr and ʿUmar. He asked them: “What brought the two of you out of your homes at this hour?” They replied: “Hunger, O Messenger of Allah.” He said: “And by the One in whose hand is my soul, the same thing that brought you out brought me out as well. Get up.” So they went with him. He came to the house of a man from the Anṣār, but the man was not at home. When the man’s wife saw the Prophet ﷺ, she said: “Welcome and greetings.” The Messenger of Allah ﷺ asked her: “Where is so-and-so?” She replied: “He has gone to bring us fresh, sweet water.” Then the Anṣārī man arrived. When he saw the Messenger of Allah ﷺ and his two companions, he said: “Praise be to Allah! No one today has more honored guests than I do.” He went and brought them a cluster containing unripe or partly ripe dates, dried ripe dates, and fresh ripe dates and said: “Eat from these.” Then he took a knife. The Messenger of Allah ﷺ said: “Do not slaughter a milk-producing sheep.” So he slaughtered a sheep for them. They ate from the sheep and from the date cluster and drank. When they had eaten their fill and quenched their thirst, the Messenger of Allah ﷺ said to Abū Bakr and ʿUmar: “By the One in whose hand is my soul, you will certainly be questioned about this blessing on the Day of Resurrection. Hunger brought you out of your homes, and you did not return until you had received this blessing.”"]},"buhuth":{"en":["Regarding the words “until they were full,” al-Qurṭubī said:","“This is evidence that it is permissible to eat one’s fill from lawful food. Reports from the Prophet ﷺ and the early generations indicating dislike of fullness refer to the kind of fullness that burdens the stomach, slows a person down from prayer and remembrance, harms the body through indigestion and similar effects, and leads to vanity, excess, sleep, and laziness. This is what is disliked. It may even approach the prohibited if its harms become numerous and widespread.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2038)."},{"num":14354,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا وُضِعَ عَشَاءُ أَحَدِكُمْ وَأُقِيمَتِ الصَّلاَةُ، فَابْدَءُوا بِالْعَشَاءِ، وَلاَ يَعْجَلْ حَتَّى يَفْرُغَ مِنْهُ. وَكَانَ ابْنُ عُمَرَ يُوضَعُ لَهُ الطَّعَامُ وَتُقَامُ الصَّلاَةُ فَلاَ يَأْتِيهَا حَتَّى يَفْرُغَ، وَإِنَّهُ لَيَسْمَعُ قِرَاءَةَ الإِمَامِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (673)، ومسلم في المساجد (559) كلاهما من حديث أبي أسامة، حدثنا عبيد الله، عن نافع، عن ابن عمر فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية الصلاة بحضرة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (673) and Muslim (559).","chapter_en":"The Dislike of Praying When Food Has Been Served","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["Ibn ʿUmar narrated that the Messenger of Allah ﷺ said: “If dinner is placed before one of you and the prayer is commenced, begin with dinner, and do not hurry until you have finished eating.” Food would be placed before Ibn ʿUmar and the prayer would begin, yet he would not go to it until he had finished, even though he could hear the imam reciting."]}},"tuhfa":{},"full":1,"rep":[2385],"tks":"متفق عليه: رواه البخاري (673)، ومسلم (559)."},{"num":14355,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا قُدِّمَ الْعَشَاءُ، فَابْدَءُوا بِهِ قَبْلَ أَنْ تُصَلُّوا صَلاَةَ الْمَغْرِبِ، وَلاَ تَعْجَلُوا عَنْ عَشَائِكُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (672)، ومسلم في المساجد (557) كلاهما من حديث ابن شهاب، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب كراهية الصلاة بحضرة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (672) and Muslim (557).","chapter_en":"The Dislike of Praying When Food Has Been Served","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “When dinner is served, begin with it before praying Maghrib, and do not rush away from your dinner.”"]}},"tuhfa":{},"full":1,"rep":[2384],"tks":"متفق عليه: رواه البخاري (672)، ومسلم (557)."},{"num":14356,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا وُضِعَ الْعَشَاءُ وَأُقِيمَتِ الصَّلاَةُ فابدؤوا بِالْعَشَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (671)، ومسلم في المساجد (558) كلاهما من حديث هشام، قال: حدثني أبي، قال: سمعت عائشة تقول: فذكرته.","grade":"متفق عليه","chapter_ar":"باب كراهية الصلاة بحضرة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (671) and Muslim (558).","chapter_en":"The Dislike of Praying When Food Has Been Served","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Prophet ﷺ said: “When dinner has been served and the prayer is commenced, begin with dinner.”"]},"buhuth":{"en":["Abū al-Dardāʾ said, as al-Bukhārī mentioned:","“Part of a person’s understanding of religion is that he attends to his need first, so that when he turns to his prayer, his heart is free of distraction.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (671)، ومسلم (558)."},{"num":14357,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ قَالَ: أَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ شِعْبٍ مِنَ الْجَبَلِ وَقَدْ قَضَى حَاجَتَهُ، وَبَيْنَ أَيْدِينَا تَمْرٌ عَلَى تُرْسٍ أَوْ حَجَفَةٍ، فَدَعَوْنَاهُ، فَأَكَلَ مَعَنَا وَمَا مَسَّ مَاءً."],"takhrij":"حسن: رواه أبو داود (3762)، وأحمد (15272)، وصحّحه ابن حبان (1160) كلهم من طرق عن أبي الزبير، عن جابر فذكره.","grade":"حسن","chapter_ar":"باب كراهية الصلاة بحضرة الطعام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3762), Aḥmad (15272), and authenticated by Ibn Ḥibbān (1160).","chapter_en":"The Dislike of Praying When Food Has Been Served","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: The Messenger of Allah ﷺ came from a mountain pass after relieving himself. We had dates in front of us placed upon a shield or similar object. We invited him to eat, so he ate with us without touching water."]},"buhuth":{"en":["Aḥmad’s wording states:","“We invited him to eat some ʿajwah dates that were before us on a shield. He ate from them, and he had not performed wuḍūʾ before eating them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3762)، وأحمد (15272)، وصححه ابن حبان (1160)."},{"num":14358,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: أُتيَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ فِي بَيْتِ مَيْمُونَةَ بِضَبَّيْنِ مَشْوِيَّيْنِ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5400)، ومسلم في الصيد والذبائح (1945) كلاهما من طريق معمر، عن الزهري، عن أبي أمامة بن سهل بن حنيف، عن ابن عباس فذكره. واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الشواء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5400) and Muslim (1945). The wording is that of Muslim.","chapter_en":"What Has Been Narrated Concerning Roasted Food","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: Two roasted lizards were brought to the Prophet ﷺ while we were in the house of Maymūnah."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَقَدْ جَاءَتْ رُسُلُنَا إِبْرَاهِيمَ بِالْبُشْرَى قَالُوا سَلَامًا قَالَ سَلَامٌ فَمَا لَبِثَ أَنْ جَاءَ بِعِجْلٍ حَنِيذٍ﴾ [هود: ٦٩]."],"en":["Allah, the Exalted, says:","“And surely Our messengers came to Ibrāhīm with good news. They said, ‘Peace.’ He replied, ‘Peace,’ and before long he brought them a roasted calf.”","[Sūrat Hūd 11:69]"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5400)، ومسلم (1945)، واللفظ لمسلم."},{"num":14359,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ السلمي قَالَ: كُنْتُ يَوْمًا جَالِسًا مَعَ رِجَالٍ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَنْزِلٍ فِي طَرِيقِ مَكَّةَ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَازِلٌ أَمَامَنَا، وَالْقَوْمُ مُحْرِمُونَ وَأَنَا غَيْرُ مُحْرِمٍ، فَأَبْصَرُوا حِمَارًا وَحْشِيًّا وَأَنَا مَشْغُولٌ أَخْصِفُ نَعْلِي، فَلَمْ يُؤْذِنُونِي لَهُ، وَأَحَبُّوا لَوْ أَنِّي أَبْصَرْتُهُ، فَالْتَفَتُّ فَأَبْصَرْتُهُ، فَقُمْتُ إِلَى الْفَرَسِ فَأَسْرَجْتُهُ، ثُمَّ رَكِبْتُ وَنَسِيتُ السَّوْطَ وَالرُّمْحَ، فَقُلْتُ لَهُمْ: نَاوِلُونِي السَّوْطَ وَالرُّمْحَ، فَقَالُوا: لاَ وَاللَّهِ لاَ نُعِينُكَ عَلَيْهِ بشيء، فَغَضِبْتُ فَنَزَلْتُ فَأَخَذْتُهُمَا ثُمَّ رَكِبْتُ، فَشَدَدْتُ عَلَى الْحِمَارِ فَعَقَرْتُهُ، ثُمَّ جِئْتُ بِهِ وَقَدْ مَاتَ، فَوَقَعُوا فِيهِ يَأْكُلُونَهُ، ثُمَّ إِنَّهُمْ شَكُّوا فِي أَكْلِهِمْ إِيَّاهُ وَهُمْ حُرُمٌ، فَرُحْنَا، وَخَبَأْتُ الْعَضُدَ مَعِي، فَأَدْرَكْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلْنَاهُ عَنْ ذَلِكَ، فَقَالَ: مَعَكُمْ مِنْهُ شيء؟ فَنَاوَلْتُهُ الْعَضُدَ فَأَكَلَهَا حَتَّى تَعَرَّقَهَا وَهْوَ مُحْرِمٌ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5407)، ومسلم في الحج (1194: 63) كلاهما من طريق أبي حازم، عن عبد الله بن أبي قتادة السلمي، عن أبيه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عرق اللحم من العظام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5407) and Muslim (1194:63).","chapter_en":"What Has Been Narrated Concerning Gnawing Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["Abū Qatādah al-Sulamī narrated: One day I was sitting with some men from among the Companions of the Prophet ﷺ at a stopping place on the road to Makkah. The Messenger of Allah ﷺ had camped ahead of us. The people were in iḥrām, while I was not. They saw a wild donkey while I was busy repairing my sandal. They did not alert me to it, although they wished that I would notice it myself. I turned and saw it, so I went to my horse, saddled it, and mounted. I had forgotten my whip and spear. I said to them: “Hand me the whip and spear.” They replied: “No, by Allah, we will not assist you in any way with it.” I became angry, dismounted, took them myself, then mounted again. I pursued the wild donkey and struck it down. I brought it back after it had died, and they began eating from it. Then they became uncertain about whether they were permitted to eat it while they were in iḥrām. We continued traveling, and I kept the foreleg with me. When we reached the Messenger of Allah ﷺ, we asked him about it. He said: “Do you have any of it with you?” I handed him the foreleg, and he ate from it, gnawing the meat from the bone while he was in iḥrām."]},"buhuth":{"en":["The word al-ʿarq refers to a bone from which most of the meat has already been removed.","Al-Nihāyah (3/220)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5407)، ومسلم (1194: 63)."},{"num":14360,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ قَالَ: انتثل النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَرْقًا مِنْ قدرٍ، فَأَكَلَ ثُمَّ صَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5404-5405) عن عبد الله بن عبدالوهاب، حدثنا حماد، عن أيوب وعاصم، عن عكرمة، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عرق اللحم من العظام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5404–5405) and Muslim (354).","chapter_en":"What Has Been Narrated Concerning Gnawing Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The Prophet ﷺ took a meat-covered bone out of a cooking pot, ate from it, then prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5404-5405)، ومسلم (354)."},{"num":14361,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ أُمَيَّةَ أَنَّهُ رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَزُّ مِنْ كَتِفِ شَاةٍ فِي يَدِهِ، فَدُعِيَ إِلَى الصَّلاَةِ، فَأَلْقَاهَا وَالسِّكِّينَ الَّتِي يَحْتَزُّ بِهَا، ثُمَّ قَامَ فَصَلَّى وَلَمْ يَتَوَضَّأْ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5408)، ومسلم في الحيض (355: 92) كلاهما من طريق الزهري، أخبرني جعفر بن عمرو بن أمية، أن أباه عمرو بن أمية أخبره فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في عرق اللحم من العظام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5408) and Muslim (355:92).","chapter_en":"What Has Been Narrated Concerning Gnawing Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["ʿAmr ibn Umayyah narrated: He saw the Prophet ﷺ cutting meat from a sheep’s shoulder that he was holding in his hand. Then he was called to prayer. He put down the shoulder and the knife with which he had been cutting it, stood up, and prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5408)، ومسلم (355: 92)."},{"num":14362,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ بْنِ شُعْبَةَ، قَالَ: ضِفْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ لَيْلَةٍ فَأَمَرَ بِجَنْبٍ فَشُوِيَ، وَأَخَذَ الشَّفْرَةَ فَجَعَلَ يَحُزُّ لِي بِهَا مِنْهُ."],"takhrij":"حسن: رواه أبو داود (188)، والترمذي في الشمائل (168)، وأحمد (18212) كلهم من طرق عن وكيع، عن مسعر، عن أبي صخرة جامع بن شداد، عن المغيرة بن عبد الله، عن المغيرة بن شعبة، قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في عرق اللحم من العظام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (188), al-Tirmidhī in al-Shamā’il (168), and Aḥmad (18212).","chapter_en":"What Has Been Narrated Concerning Gnawing Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah narrated: I was the guest of the Prophet ﷺ one night. He ordered that a side of meat be roasted, then took a knife and began cutting pieces from it for me."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (188)، والترمذي في الشمائل (168)، وأحمد (18212)."},{"num":14363,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ الْحَارِثِ، قَالَ: أَكَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شِوَاءً فِي الْمَسْجِدِ."],"takhrij":"حسن: رواه الترمذي في الشمائل (167) عن قتيبة (هو ابن سعيد)، حدثنا ابن لهيعة، عن سليمان بن زياد، عن عبد الله بن الحارث فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في عرق اللحم من العظام","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī in al-Shamā’il (167).","chapter_en":"What Has Been Narrated Concerning Gnawing Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["ʿAbdullāh ibn al-Ḥārith narrated: “We ate roasted meat with the Messenger of Allah ﷺ in the mosque.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي في الشمائل (167)."},{"num":14364,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ:  إِنَّ خَلِيلِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَوْصَانِي: إِذَا طَبَخْتَ مَرَقًا فَأَكْثِرْ مَاءَهُ، ثُمَّ انْظُرْ أَهْلَ بَيْتٍ مِنْ جِيرَانِكَ، فَأَصِبْهُمْ مِنْهَا بِمَعْرُوفٍ.","وفي لفظ: يَا أَبَا ذَرٍّ : إِذَا طَبَخْتَ مَرَقَةً فَأَكْثِرْ مَاءَهَا وَتَعَاهَدْ جِيرَانَكَ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2625، 143) من طرق عن ابن إدريس، أخبرنا شعبة، عن أبي عمران الجوني، عن عبد الله بن الصامت، عن أبي ذر، قال: فذكره. ورواه مسلم أيضا (2625، 142) من طريق عبدالعزيز بن عبد الصمد العمي، عن أبي عمران الجوني باللفظ الثاني.","grade":"صحيح","chapter_ar":"باب ما جاء في إكثار ماء المرقة للجيران","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2625:143), and Muslim also narrated the second wording at (2625:142).","chapter_en":"What Has Been Narrated Concerning Increasing the Broth for One’s Neighbors","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":23,"content":{"translation":{"en":["Abū Dharr narrated: The Prophet ﷺ, my beloved, advised me: “When you cook broth, increase its water, then look to a household among your neighbors and give them some of it in a good manner.” In another wording: “O Abū Dharr, when you cook broth, increase its water and remember your neighbors.”"]}},"tuhfa":{},"full":1,"rep":[14162],"tks":"صحيح: رواه مسلم (2625: 143)، ورواه مسلم أيضا (2625: 142) باللفظ الثاني."},{"num":14365,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لاَ يَحْقِرَنَّ أَحَدُكُمْ شَيْئًا مِنَ الْمَعْرُوفِ، وَإِنْ لَمْ يَجِدْ فَلْيَلْقَ أَخَاهُ بِوَجْهٍ طَلِيقٍ وَإِنِ اشْتَرَيْتَ لَحْمًا أَوْ طَبَخْتَ قِدْرًا، فَأَكْثِرْ مَرَقَتَهُ، وَاغْرِفْ لِجَارِكَ مِنْهُ."],"takhrij":"صحيح: رواه ابن ماجه (3362) عن محمد بن بشار- وابن حبان (523) من حديث عبد الملك بن هوذة بن خليفة- كلاهما عن عثمان بن عمر، قال: حدثنا صالح بن رستم، عن أبي عمران الجوني، عن عبد الله بن الصامت، عن أبي ذر فذكره. واللفظ لابن حبان.","grade":"صحيح","chapter_ar":"باب ما جاء في إكثار ماء المرقة للجيران","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3362) and Ibn Ḥibbān (523).","chapter_en":"What Has Been Narrated Concerning Increasing the Broth for One’s Neighbors","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":23,"content":{"translation":{"en":["Abū Dharr narrated that the Messenger of Allah ﷺ said: “None of you should belittle any good deed. If he finds nothing to give, then let him meet his brother with a cheerful face. And if you buy meat or prepare a pot of food, increase its broth and give some of it to your neighbor.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3362)، وابن حبان (523)."},{"num":14366,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا طَبَخْتُمُ اللَّحْمَ، فَأَكْثِرُوا الْمَرَقَ أَوِ الْمَاءَ، فَإِنَّهُ أَوْسَعُ - أَوْ أَبْلَغُ - لِلْجِيرَانِ."],"takhrij":"حسن: رواه أحمد (15030) عن يحيى بن سعيد الأموي، حدثنا الأعمش، قال: بلغني عن جابر بن عبد الله قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في إكثار ماء المرقة للجيران","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15030).","chapter_en":"What Has Been Narrated Concerning Increasing the Broth for One’s Neighbors","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":23,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Messenger of Allah ﷺ said: “When you cook meat, increase the broth or water, for that makes it more plentiful—or more sufficient—for the neighbors.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (15030)."},{"num":14367,"demo":false,"sanad":"","matn":["عَنْ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، أَنَّهَا كَانَتْ إِذَا ثَرَدَتْ، غَطَّتْهُ شَيْئًا حَتَّى يَذْهَبَ فَوْرُهُ، ثُمَّ تَقُولُ: إِنِّي سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّهُ أَعْظَمُ لِلْبَرَكَةِ."],"takhrij":"حسن: رواه أحمد من ثلاثة أوجه (26958، 26959) عن حسن بن موسى الأشيب، وعن قتيبة بن سعيد-، وعن عتاب بن زياد الخراساني قال: حدثنا عبدالله بن المبارك- ثلاثتُهم- عن ابن لهيعة قال: حدثنا عُقيل بن خالد، عن ابن شهاب، عن عروة، عن أسماء بنت أبي بكر فذكرتْه.","grade":"حسن","chapter_ar":"باب كراهية أكل الطعام الحار","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (26958, 26959).","chapter_en":"The Dislike of Eating Food While It Is Very Hot","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":24,"content":{"translation":{"en":["Asmāʾ bint Abī Bakr used to cover tharīd for a short time after preparing it until its intense heat subsided. Then she would say: I heard the Messenger of Allah ﷺ say: “That is greater in blessing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (26958، 26959)."},{"num":14368,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي دَعْوَةٍ، فَرُفِعَ إِلَيْهِ الذِّرَاعُ، وَكَانَتْ تُعْجِبُهُ، فَنَهَسَ مِنْهَا نَهْسَةً."],"takhrij":"متفق عليه: رواه البخاري في كتاب الأنبياء (3340)، ومسلم في الإيمان (194) كلاهما من حديث أبي حيان، عن أبي زرعة، عن أبي هريرة فذكره في حديث طويل وهو مخرج في موضعه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نهس اللحم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3340) and Muslim (194).","chapter_en":"What Has Been Narrated Concerning Biting Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":25,"content":{"translation":{"en":["Abū Hurayrah narrated: We were with the Prophet ﷺ at a meal to which he had been invited. A foreleg was presented to him, and he liked that part of the meat. He bit a piece of meat from it."]},"buhuth":{"en":["The words:","“He bit from it”","mean that he removed the meat from the bone with his mouth."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3340)، ومسلم (194)."},{"num":14369,"demo":false,"sanad":"","matn":["عَنْ صَفْوَانَ بن أُمَيَّةَ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: انْهَسُوا اللَّحْمَ نَهْسًا؛ فَإِنَّهُ أَهْنَأُ وَأَمْرَأُ."],"takhrij":"حسن: رواه الترمذي (1835)، وأحمد (15300) كلاهما من طريق سفيان بن عيينة، عن عبد الكريم بن أمية، عن عبد الله بن الحارث قال: زوّجني أبي فدعا أناسا فيهم صفوان بن أمية فقال: فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما جاء في نهس اللحم","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1835) and Aḥmad (15300).","chapter_en":"What Has Been Narrated Concerning Biting Meat from the Bone","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":25,"content":{"translation":{"en":["Ṣafwān ibn Umayyah narrated that the Prophet ﷺ said: “Bite the meat directly from the bone, for that is more wholesome and more pleasant.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1835)، وأحمد (15300)."},{"num":14370,"demo":false,"sanad":"","matn":["عَمْرَو بْنَ أُمَيَّةَ، أَخْبَرَهُ أَنَّهُ، رَأَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَحْتَزُّ مِنْ كَتِفِ شَاةٍ فِي يَدِهِ، فَدُعِيَ إِلَى الصَّلاَةِ، فَأَلْقَاهَا وَالسِّكِّينَ الَّتِي يَحْتَزُّ بِهَا، ثُمَّ قَامَ فَصَلَّى، وَلَمْ يَتَوَضَّأْ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5408)، ومسلم في الحيض (355) كلاهما من حديث الزهري، عن جعفر بن عمرو بن أمية الضمري، عن أبيه فذكره.","grade":"متفق عليه","chapter_ar":"باب قطع اللحم بالسكين","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5408) and Muslim (355).","chapter_en":"Cutting Meat with a Knife","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":26,"content":{"translation":{"en":["ʿAmr ibn Umayyah narrated: He saw the Prophet ﷺ cutting meat from a sheep’s shoulder that he was holding in his hand. Then he was called to prayer. He put down the shoulder and the knife with which he had been cutting it, stood up, and prayed without performing wuḍūʾ."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5408)، ومسلم (355)."},{"num":14371,"demo":false,"sanad":"","matn":["عن جبلة بن سُحَيْمٍ قَالَ:  كَانَ ابْنُ الزُّبَيْرِ يَرْزُقُنَا التَّمْرَ، قَالَ: وَقَدْ كَانَ أَصَابَ النَّاسَ يَوْمَئِذٍ جَُهْدٌ، وَكُنَّا نَأْكُلُ فَيَمُرُّ عَلَيْنَا ابْنُ عُمَرَ وَنَحْنُ نَأْكُلُ، فَيَقُولُ: لَا تُقَارِنُوا، فَإِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الْإِقْرَانِ، إِلَّا أَنْ يَسْتَأْذِنَ الرَّجُلُ أَخَاهُ.","قَالَ شُعْبَةُ: لَا أُرَى هَذِهِ الْكَلِمَةَ إِلَّا مِنْ كَلِمَةِ ابْنِ عُمَرَ يَعْنِي الِاسْتِئْذَانَ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5446)، ومسلم في الأشربة (2045: 150) كلاهما من طريق شعبة قال: سمعت جبلة بن سحيم قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن قران تمرتين أو أكثر عند الشدة إلا بإذن أصحابه","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5446) and Muslim (2045:150).","chapter_en":"The Prohibition of Taking Two or More Dates at Once During Hardship Except with the Permission of One’s Companions","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":27,"content":{"translation":{"en":["Jabalah ibn Suḥaym narrated: Ibn al-Zubayr used to provide us with dates. The people were suffering hardship at that time, and while we were eating, Ibn ʿUmar would pass by us and say: “Do not take two dates together at once, for the Messenger of Allah ﷺ prohibited taking dates in pairs, unless a man seeks the permission of his companion.” Shuʿbah said: “I think the words concerning seeking permission are from Ibn ʿUmar himself.”"]},"buhuth":{"en":["Shuʿbah’s statement means that he considered the condition of seeking permission to be an inserted explanatory statement from Ibn ʿUmar rather than directly attributed to the Prophet ﷺ.","However, Muslim also narrated immediately afterward through Sufyān al-Thawrī, from Jabalah ibn Suḥaym, who said:","I heard Ibn ʿUmar say:","“The Messenger of Allah ﷺ prohibited a man from taking two dates together at once until he seeks the permission of his companions.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5446)، ومسلم (2045: 150)."},{"num":14372,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ بُسْرٍ، قَالَ:  نَزَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي، قَالَ: فَقَرَّبْنَا إِلَيْهِ طَعَامًا وَوَطْبَةً، فَأَكَلَ مِنْهَا، ثُمَّ أُتِيَ بِتَمْرٍ، فَكَانَ يَأْكُلُهُ وَيُلْقِي النَّوَى بَيْنَ إِصْبَعَيْهِ، وَيَجْمَعُ السَّبَّابَةَ وَالْوُسْطَى، قَالَ شُعْبَةُ: هُوَ ظَنِّي، وَهُوَ فِيهِ إِنْ شَاءَ اللَّهُ: إِلْقَاءُ النَّوَى بَيْنَ الْإِصْبَعَيْنِ. ثُمَّ أُتِيَ بِشَرَابٍ فَشَرِبَهُ، ثُمَّ نَاوَلَهُ الَّذِي عَنْ يَمِينِهِ، قَالَ: فَقَالَ أَبِي، وَأَخَذَ بِلِجَامِ دَابَّتِهِ: ادْعُ اللَّهَ لَنَا، فَقَالَ: اللَّهُمَّ، بَارِكْ لَهُمْ فِي مَا رَزَقْتَهُمْ، وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2042) عن محمد بن المثنى العنزي، حدثنا محمد بن جعفر، حدثنا شعبة، عن يزيد بن خمير، عن عبد الله بن بسر فذكره.","grade":"صحيح","chapter_ar":"باب طلب الدعاء من الضيف بعد الأكل","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2042).","chapter_en":"Asking the Guest to Supplicate After Eating","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":28,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated: The Messenger of Allah ﷺ stayed with my father. We brought him food and waṭbah, and he ate from it. Then dates were brought to him. He would eat them and place the pits between his fingers, joining his index and middle fingers together. Shuʿbah said: “I think that is how it was narrated—and Allah willing, it is indeed in the hadith—that he placed the pits between the two fingers.” Then a drink was brought to him. He drank from it and then handed it to the person on his right. My father took hold of the bridle of his riding animal and said: “Supplicate to Allah for us.” He said: “O Allah, bless them in what You have provided for them, forgive them, and have mercy on them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2042)."},{"num":14373,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: مَا عَلِمْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَكَلَ عَلَى سُكُرُّجَةٍ قَطُّ، وَلاَ خُبِزَ لَهُ مُرَقَّقٌ قَطُّ، وَلاَ أَكَلَ عَلَى خِوَانٍ. قِيلَ لِقَتَادَةَ: فَعَلَى مَا كَانُوا يَأْكُلُونَ؟ قَالَ: عَلَى السُّفَرِ."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5386) عن علي بن عبدالله، حدثنا معاذ بن هشام، قال: حدثني أبي، عن يونس-هو الإسكاف- عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في الأكل على الخوان والسفرة والمائدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5386).","chapter_en":"What Has Been Narrated Concerning Eating on a Khuwān, a Dining Cloth, and a Table","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":29,"content":{"translation":{"en":["Anas narrated: “As far as I know, the Prophet ﷺ never ate from a sukkurrajah, never had thin refined bread prepared for him, and never ate upon a khuwān.” Qatādah was asked: “Then what did they eat upon?” He replied: “Upon dining cloths.”"]},"buhuth":{"en":["The word “sukkurrajah” is an Arabized Persian word.","It has been said to mean small dishes used for eating.","It has also been said to mean a wooden bowl with raised divisions, resembling a small table.","Al-Ḥāfiẓ Ibn Ḥajar said in Fatḥ al-Bārī (9/532):","“The first interpretation is more likely.”","The reason the Prophet ﷺ did not eat from a sukkurrajah may have been that they ate together from larger dishes, or simply that the Prophet ﷺ did not possess such a dish.","The expression “upon a khuwān” uses an Arabized foreign word, pronounced with either kasrah or ḍammah on the letter khāʾ.","It has been said to mean a table when no food has yet been placed upon it.","The word “sufar” is the plural of sufrah.","Originally, a sufrah referred to food prepared for a traveler, then came to refer to the container in which that food was carried, and later became commonly used for the dining cloth upon which food is placed.","Such cloths were most commonly made of leather."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5386)."},{"num":14374,"demo":false,"sanad":"","matn":["عن أنس قَالَ: قَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَبْنِي بِصَفِيَّةَ، فَدَعَوْتُ الْمُسْلِمِينَ إِلَى وَلِيمَتِهِ، أَمَرَ بِالأَنْطَاعِ فَبُسِطَتْ، فَأُلْقِيَ عَلَيْهَا التَّمْرُ وَالأَقِطُ وَالسَّمْنُ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5387) عن ابن أبي مريم، أخبرنا محمد بن جعفر، أخبرنا حميد أنه سمع أنسا يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل على الخوان والسفرة والمائدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5387, 371) and Muslim (1365:84).","chapter_en":"What Has Been Narrated Concerning Eating on a Khuwān, a Dining Cloth, and a Table","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":29,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ stayed in order to consummate his marriage with Ṣafiyyah. I invited the Muslims to his wedding feast. He ordered that leather mats be spread out, and dates, dried curd, and clarified butter were placed upon them."]},"buhuth":{"en":["At the end of the narration it states:","“The Prophet ﷺ entered the morning as a bridegroom and said: ‘Whoever has anything should bring it.’ A leather mat was spread out, and one man would bring dates while another would bring clarified butter…”","The word “al-anṭāʿ” is the plural of niṭʿ, meaning a mat or spread made of leather."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5387، 371)، ومسلم (1365: 84)."},{"num":14375,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ أُمَّ حُفَيْدٍ بِنْتَ الْحَارِثِ بْنِ حَزْن، ٍ ـ خَالَةَ ابْنِ عَبَّاسٍ ـ أَهْدَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمْنًا وَأَقِطًا وَأَضُبًّا، فَدَعَا بِهِنَّ، فَأُكِلْنَ عَلَى مَائِدَتِهِ، وَتَرَكَهُنَّ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَالْمُسْتَقْذِرِ لَهُنَّ، وَلَوْ كُنَّ حَرَامًا مَا أُكِلْنَ عَلَى مَائِدَةِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَلاَ أَمَرَ بِأَكْلِهِنَّ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5389)، ومسلم في الصيد والذبائح (1947) كلاهما من طريق أبي بشر، عن سعيد بن جبير قال: سمعت ابن عباس يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الأكل على الخوان والسفرة والمائدة","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5389) and Muslim (1947).","chapter_en":"What Has Been Narrated Concerning Eating on a Khuwān, a Dining Cloth, and a Table","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":29,"content":{"translation":{"en":["Ibn ʿAbbās narrated: Umm Ḥufayd bint al-Ḥārith ibn Ḥazn, the maternal aunt of Ibn ʿAbbās, presented the Prophet ﷺ with clarified butter, dried curd, and desert lizards. They were brought forward and eaten upon his table, while the Prophet ﷺ refrained from eating the lizards because he found them distasteful. Had they been forbidden, they would not have been eaten upon the table of the Prophet ﷺ, nor would he have instructed that they be eaten."]},"buhuth":{"en":["The phrase “upon his table” appears to conflict with the statement of Anas at the beginning of the chapter:","“He never ate upon a khuwān.”","Al-Ḥāfiẓ Ibn Ḥajar answered that māʾidah here refers generally to anything placed on the ground in order to protect the food, such as a cloth, tray, or the like. It is therefore broader than the specific khuwān whose use Anas denied.","He said that denying the more specific thing does not necessarily entail denying the more general thing.","He added that this explanation is preferable to the answer of some commentators who said that Anas merely denied knowing that the Prophet ﷺ had eaten upon a khuwān, which does not conflict with the testimony of someone who did know.","The author states:","However, Ibn Ḥajar’s explanation is complicated by what occurs in Ṣaḥīḥ Muslim in the hadith of Ibn ʿAbbās:","“A khuwān upon which there was meat was brought near to them,”","as will appear later in the chapter concerning eating desert lizard."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5389)، ومسلم (1947)."},{"num":14376,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ  نَهَى أَنْ يَشْرَبَ الرَّجُلُ قَائِمًا. قَالَ قَتَادَةُ: فَقُلْنَا: فَالْأَكْلُ؟ فَقَالَ: ذَاكَ أَشَرُّ أَوْ أَخْبَثُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2024: 113) عن محمد بن المثنى، حدثنا عبد الأعلى، حدثنا سعيد، عن قتادة، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2024:113).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Prophet ﷺ prohibited a man from drinking while standing. Qatādah said: “We asked: What about eating?” He replied: “That is worse—or more objectionable.”"]},"buhuth":{"ar":["قول قتادة: ذاك أشر أو أخبث. هذا رأيه، وليس بمرفوع."],"en":["Qatādah’s statement:","“That is worse—or more objectionable”","is his own opinion and is not attributed to the Prophet ﷺ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2024: 113)."},{"num":14377,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  نَهَى عَنِ الشُّرْبِ قَائِمًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2025: 115) من طريق شعبة، حدثنا قتادة، عن أبي عيسى الأسواري، عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2025:115).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ prohibited drinking while standing."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2025: 115)."},{"num":14378,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا يَشْرَبَنَّ أَحَدٌ مِنْكُمْ قَائِمًا، فَمَنْ نَسِيَ فَلْيَسْتَقِئْ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2026) عن عبد الجبار بن العلاء، حدثنا مروان يعني الفزاري، حدثنا عمر بن حمزة، أخبرني أبو غطفان المري، أنه سمع أبا هريرة، يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2026).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “None of you should drink while standing. Whoever forgets and does so should make himself vomit.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2026)."},{"num":14379,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عن النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَوْ يَعْلَمُ الَّذِي يَشْرَبُ وَهُوَ قَائِمٌ مَا فِي بَطْنِهِ لاستقاء."],"takhrij":"صحيح: رواه أحمد (7808، 7809) من طريقين عن عبد الرزاق، حدثنا معمر، عن الزهري، عن رجل، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (7808, 7809).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “If the one who drinks while standing knew what was in his stomach, he would make himself vomit.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (7808، 7809)."},{"num":14380,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ رَأَى رَجُلًا يَشْرَبُ قَائِمًا فَقَالَ لَهُ: قِه، قَالَ: لِمَهْ؟ قَالَ: أَيَسُرُّكَ أَنْ يَشْرَبَ مَعَكَ الْهِرُّ؟ قَالَ: لَا، قَالَ: فَإِنَّهُ قَدْ شَرِبَ مَعَكَ مَنْ هُوَ شَرٌّ مِنْهُ الشَّيْطَانُ."],"takhrij":"حسن: رواه أحمد (8003)، والبزار –كشف الأستار (2896) كلاهما من طريق شعبة، عن أبي زياد الطحان، قال: سمعت أبا هريرة يقول: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8003) and al-Bazzār in Kashf al-Astār (2896).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ saw a man drinking while standing and said to him: “Vomit it.” The man asked: “Why?” He said: “Would you be pleased if a cat drank together with you?” The man replied: “No.” He said: “Then one worse than a cat has drunk with you: Satan.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8003)، والبزار - كشف الأستار (2896)."},{"num":14381,"demo":false,"sanad":"","matn":["عَنِ الْجَارُودِ بْنِ الْمُعَلَّى، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى عَنِ الشُّرْبِ قَائِمًا."],"takhrij":"حسن: رواه الترمذي (1881) عن حميد بن مسعدة، حدثنا خالد بن الحارث، عن سعيد، عن قتادة، عن أبي مسلم، عن الجارود بن المعلى قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في النهي عن الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1881).","chapter_en":"What Has Been Narrated Concerning the Prohibition of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":30,"content":{"translation":{"en":["Al-Jārūd ibn al-Muʿallā narrated that the Prophet ﷺ prohibited drinking while standing."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (1881)."},{"num":14382,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ، قَالَ: سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ زَمْزَمَ، فَشَرِبَ وَهُوَ قَائِمٌ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5617)، ومسلم في الأشربة (2027: 117) كلاهما من حديث عاصم الأحول، عن الشعبي، عن ابن عباس فذكره.","grade":"متفق عليه","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5617) and Muslim (2027:117).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: “I gave the Messenger of Allah ﷺ water from Zamzam, and he drank it while standing.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5617)، ومسلم (2027: 117)."},{"num":14383,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ: رَضِيَ اللَّهُ عَنْهُ أَنَّهُ صَلَّى الظُّهْرَ، ثُمَّ قَعَدَ فِي حَوَائِجِ النَّاسِ فِي رَحَبَةِ الْكُوفَةِ، حَتَّى حَضَرَتْ صَلاَةُ الْعَصْرِ، ثُمَّ أُتِيَ بِمَاءٍ، فَشَرِبَ وَغَسَلَ وَجْهَهُ وَيَدَيْهِ، وَذَكَرَ رَأْسَهُ وَرِجْلَيْهِ، ثُمَّ قَامَ، فَشَرِبَ فَضْلَهُ وَهْوَ قَائِمٌ، ثُمَّ قَالَ: إِنَّ نَاسًا يَكْرَهُونَ الشُّرْبَ قَائِمًا وَإِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ صَنَعَ مِثْلَ مَا صَنَعْتُ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5616) من طرق عن عبد الملك بن ميسرة، سمعت النـزال بن سبرة، يحدّث عن علي أنه صلى الظهر... فذكره.","grade":"صحيح","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5616).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["ʿAlī prayed Ẓuhr, then remained attending to the people’s needs in the courtyard of Kūfah until the time for ʿAṣr arrived. Water was brought to him. He drank from it and washed his face and hands, and the narration also mentions his head and feet. Then he stood and drank the remaining water while standing. He said: “Some people dislike drinking while standing, but the Prophet ﷺ did exactly what you have seen me do.”"]}},"tuhfa":{},"full":1,"rep":[9559],"tks":"صحيح: رواه البخاري (5616)."},{"num":14384,"demo":false,"sanad":"","matn":["عَنِ النَّزَّالِ، قَالَ: أَتَى عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ عَلَى بَابِ الرَّحَبَةِ، فَشَرِبَ قَائِمًا، فَقَالَ: إِنَّ نَاسًا يَكْرَهُ أَحَدُهُمْ أَنْ يَشْرَبَ وَهْوَ قَائِمٌ، وَإِنِّي رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَلَ كَمَا رَأَيْتُمُونِي فَعَلْتُ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5615) عن أبي نعيم، حدثنا مسعر، عن عبد الملك بن ميسرة، عن النزال، قال: فذكره.","grade":"صحيح","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5615).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["Al-Nazzāl narrated: ʿAlī came to the gate of the courtyard and drank while standing. He said: “Some people dislike drinking while standing, but I saw the Prophet ﷺ do just as you have seen me do.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (5615)."},{"num":14385,"demo":false,"sanad":"","matn":["عَنْ زَاذَانَ، أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ، شَرِبَ قَائِمًا، فَنَظَرَ إِلَيْهِ النَّاسُ كَأَنَّهُمْ أَنْكَرُوهُ، فَقَالَ: مَا تَنْظُرُونَ؟ إِنْ أَشْرَبْ قَائِمًا، فَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا، وَإِنْ أَشْرَبْ قَاعِدًا، فَقَدْ رَأَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَاعِدًا."],"takhrij":"صحيح: رواه أحمد (795) عن عفان، حدثنا حماد، عن عطاء بن السائب، عن زاذان فذكره.","grade":"صحيح","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (795).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["Zādhān narrated: ʿAlī ibn Abī Ṭālib drank while standing. The people looked at him as though they disapproved. He said: “Why are you looking at me? If I drink while standing, I have seen the Prophet ﷺ drink while standing; and if I drink while sitting, I have seen the Prophet ﷺ drink while sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (795)."},{"num":14386,"demo":false,"sanad":"","matn":["عَنْ أُمِّ الْفَضْلِ بِنْتِ الْحَارِثِ، أَنَّهَا أَرْسَلَتْ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِ لَبَنٍ، وَهُوَ وَاقِفٌ عَشِيَّةَ عَرَفَةَ، فَأَخَذَ بِيَدِهِ فَشَرِبَهُ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5618)، ومسلم في الصيام (1123) كلاهما من حديث أبي النضر، عن عمير مولى ابن عباس، عن أم الفضل فذكرته.","grade":"متفق عليه","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5618) and Muslim (1123).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["Umm al-Faḍl bint al-Ḥārith sent a cup of milk to the Prophet ﷺ while he was standing on the evening of ʿArafah. He took it in his hand and drank it."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5618)، ومسلم (1123)."},{"num":14387,"demo":false,"sanad":"","matn":["عن كَبْشَةَ الأنصارية قَالَتْ: دَخَلَ عَلَىَّ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَشَرِبَ مِنْ فِي قِرْبَةٍ مُعَلَّقَةٍ قَائِمًا، فَقُمْتُ إِلَى فِيهَا فَقَطَعْتُهُ."],"takhrij":"صحيح: رواه الترمذي في الجامع (1892)، وفي الشمائل (214)، وأحمد (27448)، وصحّحه ابن حبان (5318) كلهم من طرق عن سفيان بن عيينة، عن يزيد بن يزيد بن جابر، عن عبد الرحمن بن أبي عمرة، عن جدته كبشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī in al-Jāmiʿ (1892) and al-Shamā’il (214), Aḥmad (27448), and authenticated by Ibn Ḥibbān (5318).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["Kabshah al-Anṣāriyyah narrated: The Messenger of Allah ﷺ entered upon me and drank while standing directly from the mouth of a hanging waterskin. I then went to the mouth of the waterskin and cut it off."]}},"tuhfa":{},"full":1,"dr":1,"rep":[9560],"tks":"صحيح: رواه الترمذي في الجامع (1892)، وفي الشمائل (214)، وأحمد (27448)، وصححه ابن حبان (5318)."},{"num":14388,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: كُنَّا نَأْكُلُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ نَمْشِي، وَنَشْرَبُ وَنَحْنُ قِيَامٌ."],"takhrij":"صحيح: رواه الترمذي (1880)، وابن ماجه (3301)، وأحمد (5874)، وصحّحه ابن حبان (5322) كلهم من طريق حفص بن غياث، عن عبيد الله بن عمر، عن نافع، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (1880), Ibn Mājah (3301), Aḥmad (5874), and authenticated by Ibn Ḥibbān (5322).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated: “During the time of the Messenger of Allah ﷺ, we used to eat while walking and drink while standing.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (1880)، وابن ماجه (3301)، وأحمد (5874)، وصححه ابن حبان (5322)."},{"num":14389,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَمْرِو بْنِ الْعَاصِ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا وَقَاعِدًا."],"takhrij":"حسن: رواه الترمذي في الجامع (1883)، وفي الشمائل (209)، وأبو داود (653)، وابن ماجه (931)، وأحمد (6660) كلهم من طريق عمرو بن شعيب، عن أبيه، عن جده عبد الله بن عمرو قال: فذكره.","grade":"حسن","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī in al-Jāmiʿ (1883) and al-Shamā’il (209), Abū Dāwūd (653), Ibn Mājah (931), and Aḥmad (6660).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated: “I saw the Messenger of Allah ﷺ drink both while standing and while sitting.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9562],"tks":"حسن: رواه الترمذي في الجامع (1883)، وفي الشمائل (209)، وأبو داود (653)، وابن ماجه (931)، وأحمد (6660)."},{"num":14390,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَشْرَبُ قَائِمًا وَقَاعِدًا، وَيُصَلِّي مُنْتَعِلًا وَحَافِيًا، وَيَنْصَرِفُ مِنَ الصَّلَاةِ عَنْ يَمِينِهِ وَعَنْ يَسَارِهِ."],"takhrij":"حسن: رواه الطبراني في الأوسط (1235) عن أحمد قال: نا يحيى بن حكيم المقوم قال: نا مخلد بن يزيد الحراني، عن يحيى بن سعيد الأنصاري، عن عطاء، عن عائشة قالت: فذكرته.","grade":"حسن","chapter_ar":"باب جواز الشرب قائمًا","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ (1235).","chapter_en":"The Permissibility of Drinking While Standing","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":31,"content":{"translation":{"en":["ʿĀ’ishah narrated: “I saw the Messenger of Allah ﷺ drink while standing and while sitting, pray while wearing sandals and while barefoot, and turn away after prayer both to his right and to his left.”"]},"buhuth":{"en":["The statement in the hadith of Abū Hurayrah:","“Whoever forgets should make himself vomit”","was not acted upon as an established obligation.","It has also been said that this wording is actually a statement of Abū Hurayrah rather than being directly attributed to the Prophet ﷺ.","The majority of scholars held that drinking while standing is permissible. Among the early Muslims who did so were Abū Bakr, ʿUmar, and ʿAlī, may Allah be pleased with them, and this was also the view of the majority of jurists and Mālik.","They relied upon the Prophet ﷺ drinking Zamzam while standing.","It appears that they regarded this action of the Prophet ﷺ as later than the reports of prohibition, since it occurred during the Farewell Pilgrimage.","There is further scholarly discussion concerning this issue."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2211,2579,9563],"tks":"حسن: رواه الطبراني في الأوسط (1235)."},{"num":14391,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَنَفَّسُ فِي الشَّرَابِ ثَلَاثًا، وَيَقُولُ: إِنَّهُ أَرْوَى، وَأَبْرَأُ، وَأَمْرَأُ.","قَالَ أَنَسٌ: فَأَنَا أَتَنَفَّسُ فِي الشَّرَابِ ثَلَاثًا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2028: 123) من طريق عبد الوارث بن سعيد، عن أبي عصام، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب استحباب الشرب بثلاثة أنفاس خارج الإناء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2028:123).","chapter_en":"The Recommendation to Drink in Three Breaths Outside the Vessel","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":32,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ used to take three breaths while drinking and would say: “It is more thirst-quenching, healthier, and more pleasant.” Anas said: “So I also take three breaths when drinking.”"]},"buhuth":{"en":["The word “arwā” means more effective in quenching thirst.","“Abraʾ” means safer from illness and harm.","“Amraʾ” means easier and more pleasant to swallow."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2028: 123)."},{"num":14392,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ يَتَنَفَّسُ فِي الْإِنَاءِ ثَلَاثًا."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5631)، ومسلم في الأشربة (2028: 122) كلاهما من حديث عزرة بن ثابت الأنصاري، عن ثمامة بن عبدالله بن أنس، عن أنس فذكره. واللفظ لمسلم. وزاد البخاري في أوله: كان أنسٌ يتنفّس في الإناء مرتين أو ثلاثا.","grade":"متفق عليه","chapter_ar":"باب استحباب الشرب بثلاثة أنفاس خارج الإناء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5631) and Muslim (2028:122). The wording is that of Muslim.","chapter_en":"The Recommendation to Drink in Three Breaths Outside the Vessel","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":32,"content":{"translation":{"en":["Anas narrated: “The Messenger of Allah ﷺ used to breathe three times while drinking.”"]},"buhuth":{"en":["Al-Bukhārī added at the beginning:","“Anas used to take two or three breaths while drinking.”","The phrase:","“He used to breathe three times while drinking”","means that he would remove the vessel from his mouth and breathe between sips.","As for breathing directly into the vessel, that is prohibited."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5631)، ومسلم (2028: 122)، واللفظ لمسلم."},{"num":14393,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَشْرَبُ فِي ثَلَاثَةِ أَنْفَاسٍ، إِذَا أَدْنَى الْإِنَاءَ إِلَى فِيهِ سَمَّى اللَّهَ، فَإِذَا أَخَّرَهُ حَمِدَ اللَّهَ، يَفْعَلُ بِهِ ثَلَاثَ مَرَّاتٍ."],"takhrij":"حسن: رواه الطبراني في الأوسط –مجمع البحرين (4141)، والخرائطي في فضيلة الشكر (24) كلاهما من طريق عتيق بن يعقوب الزبيري، حدثنا عبد العزيز بن محمد الدراوردي، عن محمد بن عجلان، عن أبيه، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب استحباب الشرب بثلاثة أنفاس خارج الإناء","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (4141), and al-Kharāʾiṭī in Faḍīlat al-Shukr (24).","chapter_en":"The Recommendation to Drink in Three Breaths Outside the Vessel","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ used to drink in three breaths. Whenever he brought the vessel to his mouth, he would mention the Name of Allah, and whenever he moved it away, he would praise Allah. He would do this three times."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (4141)، والخرائطي في فضيلة الشكر (24)."},{"num":14394,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمُثَنَّى الْجُهَنِيِّ أَنَّهُ قَالَ: كُنْتُ عِنْدَ مَرْوَانَ بْنِ الْحَكَمِ، فَدَخَلَ عَلَيْهِ أَبُو سَعِيدٍ الْخُدْرِيُّ، فَقَالَ لَهُ مَرْوَانُ بنُ الْحَكَمِ: أسمعتَ مِنْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنِ النَّفْخِ فِي الشَّرَابِ؟ فقَالَ لَهُ أَبُو سَعِيدٍ: نَعَمْ، فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللَّهِ، إِنِّي لَا أَرْوَى مِنْ نَفَسٍ وَاحِدٍ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فأبِنِ الْقَدَحَ عَنْ فيكَ، ثُمَّ تَنَفَّسْ، قَالَ: فَإِنِّي أَرَى الْقَذَاةَ فِيهِ، قَالَ: فَأَهْرِقْهَا."],"takhrij":"حسن: رواه مالك في صفة النبي صلى الله عليه وسلم (12) عن أيوب بن خبيب، مولى سعد بن أبي وقاص، عن أبي المثنى الجهني، أنه قال: فذكره.","grade":"حسن","chapter_ar":"باب جواز الشرب بنفس واحد","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Mālik in Ṣifat al-Nabī ﷺ (12), al-Tirmidhī (1887), Ibn Ḥibbān (5327), and al-Ḥākim (7208).","chapter_en":"The Permissibility of Drinking in a Single Breath","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":33,"content":{"translation":{"en":["Abū al-Muthannā al-Juhanī narrated: I was with Marwān ibn al-Ḥakam when Abū Saʿīd al-Khudrī entered upon him. Marwān asked him: “Did you hear from the Messenger of Allah ﷺ that he prohibited blowing into a drink?” Abū Saʿīd replied: “Yes.” A man had said: “O Messenger of Allah, I do not become fully quenched from a single breath.” The Messenger of Allah ﷺ said: “Then remove the cup from your mouth and breathe.” The man said: “I see a speck of dirt in it.” He replied: “Then pour it out.”"]},"buhuth":{"en":["Imām Mālik said:","“This hadith contains permission to drink in a single breath.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14397],"tks":"حسن: رواه مالك (12)، والترمذي (1887)، وابن حبان (5327)، والحاكم (7208)."},{"num":14395,"demo":false,"sanad":"","matn":["عن أَبِي قَتَادَةَ، عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا شَرِبَ أَحَدُكُمْ فَلاَ يَتَنَفَّسْ فِي الإِنَاءِ، وَإِذَا بَالَ أَحَدُكُمْ فَلاَ يَمْسَحْ ذَكَرَهُ بِيَمِينِهِ، وَإِذَا تَمَسَّحَ أَحَدُكُمْ فَلاَ يَتَمَسَّحْ بِيَمِينِهِ."],"takhrij":"متفق عليه: رواه البخاري في الأشربة (5630)، ومسلم في الأشربة (267: 63) كلاهما من طريق يحيى بن أبي كثير، عن عبد الله بن أبي قتادة، عن أبيه، فذكره.","grade":"متفق عليه","chapter_ar":"باب النهي عن التنفس في الإناء أثناء الشرب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5630) and Muslim (267:63). The wording is that of al-Bukhārī.","chapter_en":"The Prohibition of Breathing into the Vessel While Drinking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":34,"content":{"translation":{"en":["Abū Qatādah narrated that the Messenger of Allah ﷺ said: “When one of you drinks, he should not breathe into the vessel. When one of you urinates, he should not wipe his private part with his right hand. And when one of you cleans himself after relieving himself, he should not do so with his right hand.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5630)، ومسلم (267: 63)، واللفظ للبخاري."},{"num":14396,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا شَرِبَ أَحَدُكُمْ فَلاَ يَتَنَفَّسْ فِي الإِنَاءِ، فَإِذَا أَرَادَ أَنْ يَعُودَ، فَلْيُنَحِّ الإِنَاءَ، ثُمَّ لْيَعُدْ إِنْ كَانَ يُرِيدُ."],"takhrij":"حسن: رواه ابن ماجه (3427) عن أبي بكر بن أبي شيبة –وهو في مصنفه (8/217) في نسخة الدار السلفية، وساقط في تحقيق محمد عوامة-، وأبو يعلى (6677)، والحاكم (4/139) كلهم من طرقٍ عن الحارث بن أبي ذباب، عن عمّه، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب النهي عن التنفس في الإناء أثناء الشرب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (3427), Ibn Abī Shaybah (8/217), Abū Yaʿlā (6677), and al-Ḥākim (4/139).","chapter_en":"The Prohibition of Breathing into the Vessel While Drinking","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":34,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you drinks, he should not breathe into the vessel. If he wishes to drink again, let him move the vessel away, then return to it if he wishes.”"]},"buhuth":{"en":["The wisdom behind prohibiting breathing into the vessel is to prevent the water from becoming contaminated by saliva or moisture coming from the mouth.","The statement:","“Remove the cup from your mouth and then breathe”","indicates that drinking in a single breath is permissible if that is sufficient to quench the person.","As for the statement of Anas:","“The Messenger of Allah ﷺ used to take three breaths while drinking,”","he did so to demonstrate the permissibility of drinking in stages.","Some scholars said that breathing in this manner was specific to the Prophet ﷺ because nothing impure or unpleasant would come from his breath, unlike other people."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (3427)، وابن أبي شيبة (24169)، وأبو يعلى (6677)، والحاكم (4/139)."},{"num":14397,"demo":false,"sanad":"","matn":["عَنْ أَبِي الْمُثَنَّى الْجُهَنِيِّ أَنَّهُ قَالَ: كُنْتُ عِنْدَ مَرْوَانَ بْنِ الْحَكَمِ، فَدَخَلَ عَلَيْهِ أَبُو سَعِيدٍ الْخُدْرِيُّ، فَقَالَ لَهُ مَرْوَانُ بن الْحَكَمِ: أسمعت مِنْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّهُ نَهَى عَنِ النَّفْخِ فِي الشَّرَابِ؟ فقَالَ لَهُ أَبُو سَعِيدٍ: نَعَمْ، فَقَالَ لَهُ رَجُلٌ: يَا رَسُولَ اللَّهِ، إِنِّي لَا أَرْوَى مِنْ نَفَسٍ وَاحِدٍ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فأَبِنِ الْقَدَحَ عَنْ فِيكَ، ثُمَّ تنفَّسْ، قَالَ: فَإِنِّي أَرَى الْقَذَاةَ فِيهِ، قَالَ: فَأَهْرِقْهَا."],"takhrij":"حسن: رواه مالك في صفة النبي صلى الله عليه وسلم (12) عن أيوب بن خبيب، مولى سعد بن أبي وقاص، عن أبي المثنى الجهني، أنه قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية النفخ في الشراب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by Mālik in Ṣifat al-Nabī ﷺ (12), al-Tirmidhī (1887), Ibn Ḥibbān (5327), and al-Ḥākim (7208).","chapter_en":"The Dislike of Blowing into a Drink","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":35,"content":{"translation":{"en":["Abū al-Muthannā al-Juhanī narrated: I was with Marwān ibn al-Ḥakam when Abū Saʿīd al-Khudrī entered upon him. Marwān asked: “Did you hear from the Messenger of Allah ﷺ that he prohibited blowing into a drink?” Abū Saʿīd replied: “Yes.” A man said: “O Messenger of Allah, I do not become fully quenched from one breath.” The Messenger of Allah ﷺ said: “Then remove the cup from your mouth and breathe.” The man said: “I see a speck of dirt in it.” He said: “Then pour it out.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14394],"tks":"حسن: رواه مالك (12)، والترمذي (1887)، وابن حبان (5327)، والحاكم (7208)."},{"num":14398,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَهَى أَنْ يتنفّسَ فِي الإِنَاءِ، أَوْ يُنفخَ فِيهِ."],"takhrij":"صحيح: رواه أبو داود (3728)، والترمذي (1888)، وابن ماجه (3429)، وأحمد (1907) كلهم من حديث سفيان بن عيينة، عن عبد الكريم الجزري، عن عكرمة، عن ابن عباس فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كراهية النفخ في الشراب","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3728), al-Tirmidhī (1888), Ibn Mājah (3429), and Aḥmad (1907).","chapter_en":"The Dislike of Blowing into a Drink","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":35,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Prophet ﷺ prohibited breathing into a vessel or blowing into it."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (3728)، والترمذي (1888)، وابن ماجه (3429)، وأحمد (1907)."},{"num":14399,"demo":false,"sanad":"","matn":["عن أبي هريرة قال: نَهَى أن يشربَ مِنْ كَسْرِ القدحِ."],"takhrij":"حسن: رواه الطبراني في الأوسط – مجمع البحرين (4131)-، وأبو نعيم في حلية الأولياء (9/38) كلاهما من طريق عبد الله بن المبارك، عن معمر، عن جعفر بن بُرقان، عن يزيد بن الأصم، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب كراهية الشرب من كسر القدح","chapter_ur":"","part_ar":"كتاب الأدب العالي","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Awsaṭ, as cited in Majmaʿ al-Baḥrayn (4131), and Abū Nuʿaym in Ḥilyat al-Awliyāʾ (9/38).","chapter_en":"The Dislike of Drinking from a Chipped or Broken Edge of a Cup","part_en":"The Book of Lofty Manners","group_ar":"جموع ما جاء في آداب الأكل والشرب","group_en":"Collection of What Has Been Narrated Concerning the Etiquette of Eating and Drinking","part_no":61,"group_no":8,"chapter_no":36,"content":{"translation":{"en":["Abū Hurayrah narrated: “It was prohibited to drink from the broken or chipped edge of a cup.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الأوسط - مجمع البحرين (4131)، وأبو نعيم في حلية الأولياء (9/38)."}]);